\begin{equation}
 |\Delta h_{ij}|\le Ct^{-1/2}
 \exp\{-at[(d_T(i,B)-1)_++(d_T(j,B)-1)_+]\}.
\end{equation}

For every local root chart \eqref{eq:local-root}, every integer
\(j\), and every \(k\geq1\), the map
\begin{equation}
 g_*\mathcal T_{j,k+1}\longrightarrow g_*\mathcal T_{j,k}
\end{equation}
is an epimorphism of sheaves of complex vector spaces on \(U\).
The neighborhoods used to lift a particular germ may depend on \(j\)
and \(k\).

The tangent bundle $T_V$ is strongly semistable for the slope
$c_1(-)HD/\rk(-)$.  Moreover,
\begin{equation}
  c_2(V)D\ge0.

\end{equation}

The scalar widths satisfy
\begin{equation}
 a_*=\lim_{e\to\infty}\frac{d_e}{M_e}
 =\frac{p}{p+1},\qquad Dc_2(V)=0.
\end{equation}

For fixed interval weights, $\ell$ is concave on the closed cone of
nonnegative nondecreasing covariance levels. For any two such step
paths $h,v$, represented on a common subdivision,
\begin{equation}
 \ell(v)\leq\ell(h)
   -\frac12\int_0^1B_h(s)(v(s)-h(s))\,ds,
\end{equation}
where $B_h$ is the step path with values $B_i(h)$. Furthermore,
\begin{equation}
 |\ell(h)-\ell(v)|\leq\frac12\|h-v\|_{L^1(0,1)}.
\end{equation}
Thus $\ell$ has a unique Lipschitz extension to bounded nonnegative
nondecreasing paths, independent of the step approximations used.

For every finite step quantile $p$, the cascade factor constructed above
satisfies
\begin{equation}
 \frac1n\E\log\langle W\rangle_p
 =\ell(h_p)+\frac12\int_0^1p(s)h_p(s)\,ds+G_1(p).
\end{equation}
For a fixed cavity site $j$ and a bounded continuous function $\phi$,
the same tilted calculation satisfies
\begin{equation}
 \E\langle\phi(Q_{12})\varepsilon_j^1\varepsilon_j^2\rangle_{p,W}
 =\int_0^1\phi(p(s))B_{h_p}(s)\,ds,
\end{equation}
where $Q_{12}$ is the common-level value prescribed by $p$ and
$B_{h_p}$ is the conditional two-spin product from
Proposition~\ref{fld:derivative}.  The common-level distribution itself
is unchanged by the tilt.

Let $p$ be a limiting total-overlap quantile along any sequence
$\theta_N\in\mathcal G_N$ used in
\eqref{cav:preliminary-lower}.  For value roundings $\bar p\to p$
as above,
\begin{equation}
 B_{h_{\bar p}}\longrightarrow p\quad\text{in }L^1(0,1).
\end{equation}
Consequently
\begin{equation}
 S(p)=\ell(h_p)+\frac12\int_0^1p(s)h_p(s)\,ds.
\end{equation}
Thus $h_p$ attains the field supremum in the bounded-path completion.

For every fixed $c\in\R$,
\begin{equation}
 p_N(c)\longrightarrow\mathcal F(\mu_{\alpha,c})
\end{equation}
in probability and in $L^1$, and hence in expectation. The subsequent
zero-temperature limits
\begin{equation}
 e_\pm(\alpha):=
 \lim_{\beta\to\infty}\frac{\mathcal F(\mu_{\alpha,\pm\beta})}{\beta}
\end{equation}
exist, with $e_+(\alpha)\ge0$ and $e_-(\alpha)\le0$. If
$g_{N,1},\ldots,g_{N,N}\in\R^{m_N}$ are the columns of $G_N$, then
\begin{align}
 \frac{\|G_N\|_{\infty\to2}}N
 &=\frac{\|G_N^{\mathsf T}\|_{2\to1}}N
 \longrightarrow\sqrt{2e_+(\alpha)}, \\
 \frac1N\min_{\sigma\in\{-1,1\}^N}
 \left\|\sum_{i=1}^N\sigma_i g_{N,i}\right\|_2
 &\longrightarrow\sqrt{-2e_-(\alpha)}. 
\end{align}
Both limits hold in probability and in $L^1$. The operator norms are
from $\ell_\infty^N$ to $\ell_2^{m_N}$ and from $\ell_2^{m_N}$ to
$\ell_1^N$, respectively.

Under the hypotheses of \Cref{lemma:compression}, there is a finite sequence
of context refinements from empty context to $W$, and an index $j$, such that
\begin{equation}
 \begin{split}
 G_1(\varnothing)-G_1(W)&\le\frac{CD_*^2}{Eh^2},\\
 K_{m_{j,1}}(W;r_j)&\le K_{m_{j,0}}(W;r_j)+E.
 \end{split}

\end{equation}
The constant $C$ is numerical, and every context produced is finite-valued.

There are absolute constants $C$ and $d_*$ such that, whenever $d\ge d_*$
and $\rho$ is a nonnegative periodic function with
$\int_0^1\rho=1$ and $\rho\le e^d$ almost everywhere,
\begin{equation}
       \int_{G_\rho}\sup_{N\ge0}|S_N\rho(x)|\,dx\le Cd.
\end{equation}

Either the support lies on $S$ in a neighborhood of $0$, or there
exist $r_0>0$, $c,C>0$, and a finite $J_0$ such that, for every
$0<r<r_0$,
\begin{equation}

 0<\delta(r)\le Cr,
 \qquad c\delta(r)^{J_0}\le\frac{H(r)}{r^2}
                         \le C\delta(r)^2.
\end{equation}
In the latter alternative, throughout $\rho<r$ one also has
\begin{equation}

 |H_S|+|\nabla H_S|\le C\delta(r)r,
\end{equation}
and
\begin{equation}

 r^{-m}\int\phi_r\bigl(|H_S|^2+|\nabla H_S|^2\bigr)\,\dd\mu
       \le C r^{-m}\int\phi_r|z|^2\,\dd\mu.
\end{equation}
The constants may depend on the fixed center construction.  One may
take any fixed $J_0\ge2+(m+p-1)/k_0$ after changing $c$.

There are real-coefficient weighted homogeneous polynomials
$p_1,p_2$, each in an even number $s_0$ of variables, such that:
\begin{enumerate}
\item both are sums, in disjoint variables, of chains with exponents
      at least $2$, and both have isolated critical points;
\item $\ord_0p_1=2$ and $\ord_0p_2=3$;
\item their spectral multisets are equal modulo $2$;
\item their real Seifert forms are isomorphic, and, separately, their
      integral monodromy modules are isomorphic;
\item both monodromy operators have order dividing $D=3^{12}$.
\end{enumerate}

The total true cost of bad nodes satisfies
\begin{equation}
 \sum_{\mathrm{bad}}c
 \le10000FH^{1/4}(1+J/P+J/T)D.
\end{equation}

Condition on the complete child tables at such a comparison node.
Then
\begin{equation}
\begin{split}
 \E\left[\sum_{t=1}^S\mathcal R_t
       \,\middle|\,\text{child tables}\right]
 \le {}&h_\Sigma\left(
       \frac{\ln d_{\mathcal C}}{\eta}
       +2\kappa+SH^{-3}\right)\\
       &+2\delta c+2SH^{-4}Fc.
\end{split}
\end{equation}
Here $h_\Sigma\le64Fb$ and
$\ln d_{\mathcal C}\le4(p_*+21)\ell$.

There is no geometric action of \(T\) such that, for every
\((u,v)\in\mathcal E\),
\begin{equation}
 \frac{\ell(z_{uv})}{3\ell(u^2)}
 =\frac{\ell(z_{uv})}{3\ell(v^2)}>\frac12.
\end{equation}

For $p\in V_k$, $1\le k\le m$, define
\begin{equation}
 D_{Q_p}=\sum_{c\in\mathcal C}
       \sum_{q\in\mathcal R(Q_p)}
       \sum_{l=k}^m2^{-\alpha(l-k)}
       \sum_{s\in V_l}\lambda_{qs}d_s^c,
 \qquad \alpha=\frac1{100}.

\end{equation}
These nonnegative prices satisfy
\begin{equation}
 \sum_{k=1}^m\sum_{p\in V_k}D_{Q_p}
 \le\frac{41^2}{2(1-2^{-\alpha})}
           \sum_{c\in\mathcal C}\|c(\nabla g)\|_{L^1}
 \le C V.

\end{equation}
For every such cell $Q$ and every $n\in\mathcal N$,
\begin{equation}
\begin{aligned}
 &\int_Q\sup_{t\in\mathcal I_k(x)}
       \sum_{\varepsilon\in\{+,-\}}
       (-e_\varepsilon(n)\cdot\nabla u_t(x))_+\,\dd x
   \le C\left(D_Q+
       \sum_{\substack{q\in\mathcal R(Q)\\(q,n)\text{ bad}}}a_q\right),
 \\
 &\int_Q\left[\sup_{t\in\mathcal J_k(x)}|\nabla u_t(x)|
                  +r_k^{-1}v_k(x)\right]\dd x
   \le C\left(D_Q+\sum_{q\in\mathcal R(Q)}a_q\right).
\end{aligned}

\end{equation}
All constants are absolute: the direction palette, support radius
factor and cone aperture are fixed, and there is no dependence
on $m$.

For $(X,Z,y)\in\mathbb S^4\times\mathbb S^4\times\mathbb R^3$, the
following are equivalent:
\begin{enumerate}
  \item $(X,Z,y)\in K$;
  \item there is a real linear functional $\Lambda:\mathcal E\to\mathbb R$
  satisfying~\eqref{eq:output} and $H(\Lambda)\succeq0$.
\end{enumerate}

Suppose the multipliers satisfy~\eqref{eq:good-multipliers}.
For every real function $g$ on $\mathcal X$,
\begin{equation}
    C\Var_\mu(g)\leq C_{\mathrm p}\mathfrak D(g).

\end{equation}

Suppose the multipliers satisfy~\eqref{eq:good-multipliers}.
For every real $g$ on $\mathcal X$,
\begin{equation}
 \Var_\pi(\mathcal Qg)
 \leq(9C_{\mathrm p}+2C_{\mathrm d})\frac{\mathfrak D(g)}{C}
 \leq K_{\mathrm{obs}}\mathcal E(g).

\end{equation}

The expanded common-base count satisfies
\begin{equation}
 Z\le Z^+\le e^{20N^{-8}}Z.
\end{equation}

With probability at least $1-1/50$, this experiment does not abort,
every stored multiplier collection is good at its own phase, and
\begin{equation}
 \left|\log\frac{Y_{\rm ref}}{C_{H_o}}\right|\leq4H_o\eta.

\end{equation}

There exists a projection $b_0\in C_r^*(\Gsur)$ such that, for every
$\omega\in\Omega$, $\pi_\omega(b_0)$ is the orthogonal projection
onto $\ker\pi_\omega(T)$.  Explicitly, it is projection onto constants
on each valid copy and is zero on $\ell^2(U_\omega)$.  In particular,
\begin{equation}
 \langle\pi_\omega(b_0)\delta_1,\delta_1\rangle
 =
 \begin{cases}
  1/n_i,&\text{if $1$ belongs to a valid copy of type $i$},\\
  0,&\text{if $1\in U_\omega$}.
 \end{cases}

\end{equation}
The valid copy in the first case is unique.

The projection \(b_0\in C_r^*(\Gsur)\) satisfies
\begin{equation}
\tau_{\Gsur}(b_0)=\sum_{i\ge1}p^{-k_i}\notin\Q.
\end{equation}

On the even subspace perpendicular to the vacuum,
\begin{equation}
          \bigl\|T\big|_{\mathrm{even}\cap\Omega^\perp}\bigr\|
                         \le\tau^2.
\end{equation}
There is a real unit $\tau$-eigenfunction $\psi$ that is odd under
simultaneous spin inversion and, after a component permutation, odd under
the reflection of component $3$ alone. It satisfies
\begin{equation}
                    \inner{\Omega}{|\psi|}^2\ge\frac{\tau}{1+\tau}.
\end{equation}

Along the prescribed circumferences $w_k=M_0 2^k$,
\begin{equation}
 \liminf_{k\to\infty}\;\liminf_{N\to\infty} e_N(w_k)\ge m_*.
\end{equation}

There is a constant $C$ such that, for every sufficiently large dyadic
circumference $w=w_k$,
\begin{equation}
 \limsup_{N\to\infty}\mathcal N_{N,w}(u_0)\le Cw,
 \qquad u_0=\frac32m_*.
\end{equation}

After constant rescaling, the metrics in \eqref{eq:sequence} satisfy
\begin{equation}
 \frac1V\int_M R\dd=12,\qquad
 \norm{R-12}_2\le4\norm E_2,\qquad
 \norm{\Ric-3g}_2\longrightarrow0,
\end{equation}
where $V=\Vol(M,g)$. There are uniform positive constants
$v_0,V_0,D_0$ such that
\begin{equation}
 v_0\le V\le V_0,\qquad \diam(M,g)\le D_0.
\end{equation}

The normalized metrics of Proposition~\ref{prop:initial} satisfy
\begin{equation}
 \norm f_4^2\le S\int_M(|\nabla f|^2+f^2)\dd
\end{equation}
for all Lipschitz functions $f$, with a uniform constant $S$.

There is a uniform $S_1$ such that, whenever
$0\le t<\min\{1,\mathcal T_j\}$,
\begin{equation}
 \norm f_4^2\le S_1\int_M\bigl(4|\nabla f|^2+(R+1)f^2\bigr)\dd
\end{equation}
for every Lipschitz function $f$ on $(M_j,g_j(t))$.

For all sufficiently large $j$, the flow $g_j(t)$ exists on $[0,T]$.
There is a uniform constant $A$ such that
\begin{equation}
 \max_{M_j}|\Rm_{g_j(t)}|\le\frac At,
 \qquad 0<t<T.
\end{equation}

Set $\lambda(t)=3/(1-6t)$. Along the flows above,
\begin{equation}
 \sup_{0\le t<T}
 \norm{\Ric_{g_j(t)}-\lambda(t)g_j(t)}_{L^2(g_j(t))}
 \longrightarrow0.
\end{equation}

There is a uniform constant $C$ such that
\begin{equation}
 \int_{M_j}F(\Rm_{g_j(t)})\,d\mu_{g_j(t)}\le Ct,
 \qquad 0\le t<T.
\end{equation}

For every finite \(S\subset\Z\) and all real bounded compactly
supported measurable functions \(F_0,F_1,F_2\) on \(\R_+^2\),
\begin{equation}
 \sum_{k\in S}\sum_{\mathbf I\in\cA_k}
       \abs{L_{\mathbf I}(F_0,F_1,F_2)}
 \le 40\prod_{v=0}^2\norm{F_v}_{L^3(\R_+^2)}.
\end{equation}

If \(T\ge0\) and \(U=U^*\) satisfy \(-T\le U\le T\), then \(U\) is
supported on \(T\) and
\begin{equation}
 \frac{\Phi(T+U)+\Phi(T-U)}2-\Phi(T)
       \ge\frac{1}{2\sqrt2}b_T(U).
\end{equation}

For the maps in \eqref{eq:row-star}, let \(D_v:H_v\to H_v\) be
symmetric with \(\norm{D_v}_{\op}\le1\), and put
\(U_v=R_v^*D_vR_v\). Then \(U_v\) is supported on \(T_v\), and
\begin{equation}
 \abs{\tr(D_0W_0D_1W_1D_2W_2)}
       \le\frac53\sum_{v=0}^2 b_{T_v}(U_v).
\end{equation}
The constant is independent of all three dimensions.

For \(\mathbf I\in\cA_k\), \(k\ge m+1\), define
\[
 \delta(\mathbf I)
 =\frac14\sum_{\mathbf I'\in\operatorname{ch}(\mathbf I)}
                     e(\mathbf I')-e(\mathbf I).
\]
Then \(\delta(\mathbf I)\ge0\), and
\begin{equation}
 \abs{\tau(\mathbf I)}
       \le\frac{10\sqrt2}{3}\,\delta(\mathbf I).
\end{equation}

There is an absolute $p_0\in(0,1)$ such that, for the preceding
data and some
$L_0\leq P^C(1+\log(\nu/\mu))^C$, one has
\begin{equation*}
 \begin{split}
 \sum_sN_s^G
     &\leq L_0\min_{i\ne j}M_i^GM_j^G,\\
 \sum_s(N_s^G)^{p_0}
     &\leq P^C(1+\nu+\mu^{-1}+\Lambda)^C(M')^{2p_0}.
 \end{split}
 \tag{34}
\end{equation*}
All exponents are absolute.  They do not depend on the path,
the group, the horizontal dimension, or the number of depths.

For each fixed $c>1$, both $t=x$ and $t=x/c$ satisfy
\begin{equation}
 V(t)=\frac{t}{\log x}
 \bigl(M_1(x;H)+E_H(t;x)G_m\bigr),
 \qquad
 \lim_{H\to\infty}\limsup_{x\to\infty}
 \max_{t\in\{x,x/c\}}|E_H(t;x)|=0.

\end{equation}
All parameters in the two formulas are formed from the same $x$.

There are numbers $\varepsilon_H\to0$ such that, for every
$f:[1,\infty)\to[0,1]$,
\begin{equation}
 \limsup_{x\to\infty}
 \left|\frac{M_f(x;H)}{G_m}-A_H(f;\theta(x))\right|
 \le\varepsilon_H.

\end{equation}
The bound is independent of $f$ and of phase.  Each $A_H(f;s)$ is a finite sum involving values of $f$ at explicitly
bounded rational arguments and absolutely convergent series in its
exponential weights, and $A_H(f;s)\ge0$.

Let $f$ be a real even Schwartz function on $\mathbb R^2$ with
$\widehat f\ge0$, and let $\mathcal C$ be locally finite with
$N_R/(\pi R^2)\to1$. Then
\begin{equation}
 \liminf_{R\to\infty}\frac1{N_R}
 \sum_{\substack{x,y\in\mathcal C_R\\x\ne y}}f(x-y)
 \ge\widehat f(0)-f(0).

\end{equation}
The same lower bound holds if the summands are replaced by
$\Phi(x-y)$, where $\Phi(z)\ge f(z)$ for every $z\ne0$.

Under the consistent centered laws,
$T^*(x)=\lim_{s\to\infty}\tau_s(x)$ is finite almost surely.
For every finite deterministic $t$ and bounded raw
$\mathcal F_t$-measurable random variable $H$,
\begin{equation}
 \EE[H G_t(x)]
 =G_0(x)\EE_x^*[H\ind_{\{t<T^*(x)\}}].

\end{equation}
On the right, $H$ is evaluated only on stopped data extending beyond
$t$. Thus
\begin{equation}
 \EE G_t(x)=G_0(x)\PP_x^*(T^*(x)>t)\longrightarrow0
 \quad(t\to\infty).

\end{equation}
For every stopping time $S$,
\begin{equation}
 \EE[G_S(x)\ind_{\{S<\infty\}}]\le G_0(x).

\end{equation}

Put $v(x)=\inf\{t\ge0:\gamma(t)=x\}$, with value infinity if the set is
empty.  Almost surely $v(x)<\infty$ for $\mu_\infty$-almost every $x$, and
simultaneously for every finite $t$,
\begin{equation}
 \mu_t(\dd x)=\ind_{\{v(x)\le t\}}\mu_\infty(\dd x).

\end{equation}

For every integer $n\ge1$, the deterministic numbers
\begin{equation}
 m_n(\ell):=\EE_{\mathrm{mix}}^*L_\ell^n,
 \qquad
 m_n:=\EE_{\mathrm{mix}}^*L^n
       =\lim_{\ell\to\infty}m_n(\ell)
       \quad\text{satisfy}\quad 0<m_n<\infty.

\end{equation}
Moreover $L>0$ almost surely, and, for each fixed angle,
\begin{equation}
 \sup_{\ell>0}\EE_\theta^*L_\ell^n
                  \le C_{n,a}\sin^{-p}\theta.

\end{equation}

The moments in \eqref{coef:moments} are given by
\begin{equation}
 \begin{aligned}
 m_n(\ell)
   &=\lim_{u\to\infty}\lim_{h\to\infty}
       \int_0^\pi\int P_\ell(\theta,b)
       \bigl([D_h(\theta,b;\ell)]_0^u\bigr)^n
       \,\dd W(b)\,\pi_a(\dd\theta),\\
 m_n&=\lim_{\ell\to\infty}m_n(\ell).
 \end{aligned}

\end{equation}
All limit indices may be restricted to positive integers.  Thus these
coefficients depend only on $\kappa$ and the specified Gaussian, angle
and area integrals.

For every deterministic $J=[s,t]$ with $0\le s<t<\infty$,
\begin{equation}
 \lim_{a\downarrow0}\limsup_{e\downarrow0}
 \mathbb P\{X_e(J)<a\}=0.

\end{equation}
Equivalently, for every $\varepsilon>0$ there are $a,e_0>0$ such
that $\mathbb P\{X_e(J)<a\}<\varepsilon$ for all $0<e<e_0$.
The same conclusion can be required simultaneously for any fixed
finite list of such intervals, with total exceptional probability
as small as desired.

There is a single deterministic algorithm which, for every positive integer $n$ and every $x\in\C^n$, computes $F_nx$ exactly. In the model above, including scalar preparation, schedule construction, and index work, its running time is
\begin{equation}
 O\!\left(n(\log n)^\theta(\log\log n)^{4-\theta}\right)
\end{equation}
as $n\to\infty$. It suffices to supply the specified root $\zeta_{D_*}$ for an explicitly computable integer $D_*<1024n^3$.

Let $m\geq1$, let $H$ be a finite set of cardinality $h\geq2$, and let
$S_0$ be a submonoid of $\mathcal T_m$.  Suppose that a surjective
multiplicative map $\phi_0:S_0\to\mathcal R_H$ satisfies
\begin{equation}
 z\sqsubseteq w\quad\Longrightarrow\quad
 \phi_0(w)\subseteq\phi_0(z)
 \qquad(z,w\in S_0).

\end{equation}
Then
\begin{equation}
 2m\geq 2^{\lfloor(h-2)/127\rfloor}.

\end{equation}
The map need not initially be assumed to preserve identities.

Under the hypotheses of Lemma~\ref{lem:relocation},
\begin{equation}
 W_z(C_L)=z^L.
\end{equation}

Degree truncations detect the stable Steinberg group:
\begin{equation}
 \bigcap_{d\ge1}
 \ker\bigl(\St(R)\longrightarrow\St(R/R_{\ge d})\bigr)=1.
\end{equation}

abstract:
We prove the integral scalar-curvature inequality proposed by Gromov. For every dimension <i>n</i> ≥ 3, there is a constant \(a_n\gt 0\), depending only on <i>n</i>, such that \(\displaystyle \int_M(\mathop{\mathrm{Scal}}
olimits _g^-)^{n/2}\,dV_g\ge a_n\|M\|\) for every closed connected oriented smooth <i>n</i>-manifold <i>M</i> and every smooth Riemannian metric <i>g</i>. Here \(\mathop{\mathrm{Scal}}
olimits _g^-:=\max\{0,-\mathop{\mathrm{Scal}}
olimits _g\}\), and \(\|M\|\) is real simplicial volume. The proof uses the nonnegative-scalar-curvature vanishing theorem of the companion paper on rational inessentiality.

statements.text:
Fix \(n\ge3\). Suppose that a constant \(C_n<\infty\) has the following
property: every closed connected oriented \(n\)-manifold with a smooth
metric \(h\) of constant scalar curvature \(-1\) satisfies
\begin{equation}
  \|M\|\le C_n\Vol_h(M).

\end{equation}
Then every smooth Riemannian metric \(g\) on every such manifold
satisfies
\begin{equation}
  \|M\|\le C_n\int_M(\Scal_g^-)^{n/2}\,dV_g .

\end{equation}

There are absolute constants $C_0,C_1>0$ with the following property.
Let $q\ge2$, let $d$ be an integer with $0\le d\le q$, and let $\tau>0$.
For $0\le r\le d$ set
\begin{equation}
 T_r=2\tau+\frac{r\tau}{q},\qquad
 b_r=\tau\left(1+\frac1{2q}+\frac r{4q^2}\right).
\end{equation}
Suppose $(X,h,\phi,G)$ is a controlled measured $d$-band over $Q_{T_d}^d$
in the sense of Definition~\ref{def:degree-band}.  Let $B\ge1$ and
$L_1,\ldots,L_d>0$.  Suppose throughout $X$ that
\begin{equation}
             L_i|dG_i|_h\le B-\frac dq\qquad(1\le i\le d),
\end{equation}
and suppose that
\begin{equation}
       \frac{C_0(1+B)^{2/3}}{L_i}<\frac{\tau}{10q}
                       \qquad(1\le i\le d).
\end{equation}
Define $H_i(G)=2(L_i|dG_i|_h-1)_+$.  Then
\begin{equation}
 |\mathcal D_X(G)|(2\tau)^d
 \le \frac{\exp(C_1d/q)}{\prod_{i=1}^dL_i}
     \int_{\{|G|_\infty<b_d\}}
       \exp\left(\frac{-\wscal(h,\phi)+\sum_{i=1}^dH_i(G)}2\right)dV_h.
\end{equation}
For $d=0$ the product is one, the sum is zero, and
$\wscal(h,\phi)=0$; the assertion is the bound of a signed count by the
unsigned count.

As $X\longrightarrow\infty$,
\begin{equation}
 \sum_{\substack{N\pi\le X\\\pi\equiv1\pmod3\ \mathrm{prime}}}G(\pi)
 =\frac65c_*\frac{X^{5/6}}{\log X}
   +o\!\left(\frac{X^{5/6}}{\log X}\right).
\end{equation}
The sum is over all primary primes in $\mathcal O$.

Suppose $RU\asymp X$, and let $(a_r)$ be divisor-bounded on
$Nr\asymp R$. Suppose the smooth compactly supported weights $W_r$
have fixed support ratios and uniformly bounded derivatives,
independently of $X$. For $T\ge2$ and every fixed $D>0$,
\begin{align}
 &\int_{|t|\asymp T}\sum_{Nr\asymp R}|a_r|
       \left|\sum_uG(ru)(Nu)^{it}W_r(Nu/U)\right|\frac{dt}{T}
 \notag\\
 &\hspace{12mm}\ll_\epsilon
       X^{1/2+\epsilon}R^{3/4}T^{1/2}
       +O_D\bigl(X^{5/6}L^{C}T^{-D}\bigr),

\end{align}
where $C$ depends only on the coefficient bounds.

Let \(X_0\asymp X\), and let \(h_T\) be smooth, supported where
\(T\le |t|\le2T\), with
\(h_T^{(j)}(t)\ll_jT^{-j}\). Suppose
\[
 L^{C_t}\le T\ll X^{1/6+\rho},\qquad B\ll\sqrt X,
\]
and suppose that either
\begin{align*}
 T\ll X^{.01},&\qquad cX^{1/3}\le B,\quad c>0\text{ fixed},\tag{a}\\
 T\gg X^{.01},&\qquad X^{1/3-3\kappa}\le B.\tag{b}
\end{align*}
Assume the structural hypotheses of Proposition~\ref{prop:dispersion},
but impose neither roughness nor Siegel--Walfisz conditions.
For every fixed \(D>0\), by taking \(C_t\) sufficiently large,
\begin{equation}
 \sum_{a,b}\alpha_a\beta_bG(ab)V\!\left(\frac{N(ab)}X\right)
 \int h_T(t)\left(\frac{N(ab)}{X_0}\right)^{it}\frac{dt}{T}
       \ll X^{5/6}L^{-D}.

\end{equation}

For every fixed integer $\ell$,
\begin{equation}
 \sum_{\substack{N\pi\le X\\\pi\equiv1\pmod3\ \mathrm{prime}}}
 \theta_\ell(\pi)\bigl(G(\pi)-c_*N(\pi)^{-1/6}\bigr)
 =o_\ell\!\left(\frac{X^{5/6}}{\log X}\right).

\end{equation}
In particular, for every fixed nonzero integer $\ell$,
\begin{equation}
 \sum_{\substack{N\pi\le X\\\pi\equiv1\pmod3\ \mathrm{prime}}}
       \theta_\ell(\pi)G(\pi)
 =o_\ell\!\left(\frac{X^{5/6}}{\log X}\right).

\end{equation}

For every real $r>2$ there is a finite constant $C_r$ such that
\[
 \|V_r(F,G)\|_{L^{3/2}(\R^2)}
 \le C_r\|F\|_{L^3(\R^2)}\|G\|_{L^3(\R^2)}
\]
for all complex $F,G\in L^3(\R^2)$.

There is an absolute constant $C$ such that, for every integer $n\ge1$
and every complex $F,G\in L^3(\R^2)$,
\begin{equation}
 \|\mathcal S_n(F,G)\|_{3/2}
 \le C\sqrt n\log(2+n)\|F\|_3\|G\|_3.
\end{equation}

Let $\mathcal I\subset\mathbb Z$ be finite and nonempty, and set
$L_k=2^k$.  Let $A_0,A_1,A_2$ be finite arrays on the lattice
$u_i=ih$, with the norms $n_v$ defined in the heat-flow preliminaries.
Suppose that measurable coefficients $\mu_{ij,k}:\Xi_D\to\C$ satisfy
\begin{equation}
 |\mu_{ij,k}(\xi)|\leq C_1,
 \qquad
 \sum_{k\in\mathcal I}\int_{\Xi_D}
           |\mu_{ij,k}(\xi)|^2\,\dd\gamma(\xi)\leq C_1^2
\end{equation}
for every output index pair $(i,j)$, with the first inequality holding
almost everywhere.  If
\begin{equation}
 h^2\leq\frac{q\min_{k\in\mathcal I}L_k^2}{16D^2},
\end{equation}
then
\begin{equation}
 \left|h^3\int_{\Xi_D}\sum_{k\in\mathcal I}\sum_{i,j,l}
 A_0(i,j)\mu_{ij,k}(\xi)A_1(j,l)A_2(l,i)
 \Dil_{L_k}H_\xi(u_i+u_j+u_l)\,\dd\gamma(\xi)\right|
 \leq C(q,C_1)\prod_{v=0}^2n_v.
\end{equation}

Let $q,D,\Xi_D,\mathcal I$ be as in
Proposition~\ref{prop:frequency-block}.  Suppose that
$\mu_{a,b,k}(\xi)$ is constant in $(a,b)$ on every cell of one
finite rectangular partition, independent of $\xi$ and common to
all $k$.  Suppose its values on these cells are bounded measurable
functions of $\xi$, and that
\begin{equation}
 |\mu_{a,b,k}(\xi)|\leq C_1,
 \qquad
 \sum_k\int_{\Xi_D}|\mu_{a,b,k}(\xi)|^2\,\dd\gamma(\xi)
 \leq C_1^2.
\end{equation}
Define
\begin{equation}
 \mathcal K_{a,b}(t)
   =\int_{\Xi_D}\sum_{k\in\mathcal I}
          \mu_{a,b,k}(\xi)\Dil_{L_k}H_\xi(t)\,\dd\gamma(\xi).
\end{equation}
Then, for complex $G_v\in L^3(\R^2)$,
\begin{equation}
 |\Lambda_{\mathcal K}(G_0,G_1,G_2)|
       \leq C(q,C_1)\prod_{v=0}^2\|G_v\|_3.
\end{equation}

Let $X$ be a smooth connected projective complex variety whose
anticanonical bundle has a smooth Hermitian metric of semipositive
Chern curvature.  There are a connected finite \'etale cover
$\nu:S\to X$, an integer $a\geq0$, and smooth connected projective
varieties $F$ and $Z$ with the following properties.
\begin{enumerate}
\item For a suitable K\"ahler metric on $X$, the common universal cover
of $X$ and $S$ has a holomorphic isometric decomposition
\begin{equation}
             \widetilde X=\mathbb C^a\times F\times Z.
\end{equation}
The compact factors are simply connected.  The induced metric on $F$
is Ricci-flat, and $K_F$ has a nowhere-zero parallel holomorphic section.
The anticanonical bundle of $Z$ is smoothly semipositive, and
\begin{equation}
 H^0(Z,\Omega_Z^p)=0\quad(p>0),\qquad
 H^q(Z,\mathcal O_Z)=0\quad(q>0).
\end{equation}
The variety $Z$ is rationally connected when it has positive dimension.

\item There are a full lattice $\Lambda\subset\mathbb C^a$ and a
homomorphism $\rho:\Lambda\to\operatorname{Aut}(Z)$ for which
\begin{equation}
 S=(\mathbb C^a\times F\times Z)/\Lambda,\qquad
 \lambda\cdot(z,f,v)=(z+\lambda,f,\rho(\lambda)v).
\end{equation}
The closure $T$ of $\rho(\Lambda)$ in the holomorphic isometry group
of $Z$ is a compact connected real torus.  The trivial torus is allowed.

\item The action of $T$ extends to an algebraic action of a complex
algebraic torus $G$ on $Z$, with $T$ Zariski dense in $G$.
On $K_Z^{-1}=\det T_Z$ the action is the natural one induced by the
differential.  For every $m\geq0$, its representation on sections satisfies
\begin{equation}
       H^0(Z,K_Z^{-m})^T=H^0(Z,K_Z^{-m})^G.
\end{equation}

\item The canonical bundles of $\mathbb C^a$ and $F$ have nowhere-zero
holomorphic frames $\eta_0$ and $\eta_F$ invariant under $\Lambda$.
For every integer $m\geq0$, the product projections
$\operatorname{pr}_0$, $\operatorname{pr}_F$, and $\operatorname{pr}_Z$
give the natural, $\Lambda$-equivariant identification
\begin{equation}
 K_{\widetilde X}^{-m}
 =\operatorname{pr}_0^*K_{\mathbb C^a}^{-m}
   \otimes\operatorname{pr}_F^*K_F^{-m}
   \otimes\operatorname{pr}_Z^*K_Z^{-m},
\end{equation}
in which the first two factors have the invariant frame
$\eta_0^{-m}\otimes\eta_F^{-m}$.
\end{enumerate}
Any of the factors may be a point.  A point contributes the canonical
frame $1$; if $a=0$, the lattice is the zero group.

For good multipliers and every $H:\Om\to\R$,
\begin{equation}
 \Var_\pi(\Qproj H)\le K_{\rm obs}\calE(H),
 \qquad K_{\rm obs}=2000n^6.
\end{equation}

There is a universal constant $K\geq1$ with the following property.
Suppose $T$, $\mathcal R$, $\mathcal G$, and $\omega$ satisfy the preceding
assumptions. Let $b>0$, and choose a positive integer $r$ such that
\begin{equation}
 2\sqrt{2/r}+2/r<b.

\end{equation}
For every $\sigma>0$ and $\rho>0$, there is a measurable coloring of $V$
with $r+1$ colors for which
\begin{equation}
 \int_V \bigl((T_{\mathrm{pav}}-(Kb+\sigma)\one)_+^2\bigr)_{vv}
 \,d\mu(v)<\rho.

\end{equation}

For every $n\geq2$, there are sequences of $n$-partitions in $A$
whose quotient partition $\mathcal P$ satisfies
\begin{equation}
 \norm{C_{\mathcal P}[Z]}\leq\frac4{\sqrt n}.
\end{equation}

All roots of \(p\) are simple. Its roots outside the unit circle are
\(\beta,\alpha,\overline\alpha\), where \(\beta\) is real,
\(\operatorname{Im}\alpha>0\), and
\begin{equation}
 \begin{gathered}
  1.8392<\beta<1.8393,\qquad
  1.0002089<|\alpha|^2<1.0002094,\\
  |\alpha|^{-1}<0.9999.
 \end{gathered}

\end{equation}
The remaining roots are fourteen nonreal conjugate pairs, each of modulus
less than \(0.994\).

There exist weights \(w_{ks}\in10^{-9}\Z\), indexed by
\(30\le k\le2000\) and \(s\in\{0,1\}\), such that
\begin{equation}
 0.001+0.0055+\sum_{k,s}|w_{ks}|
   =\frac{198442946}{10^9}<x_*:=0.199

\end{equation}
and, in the stationary model,
\begin{equation}
 \begin{gathered}
 \E\mathcal L_i>0.000210,\qquad
 \E|\mathcal G_i|^2<0.000145,\\
 \left|\E\bigl[(\mathcal Z_i^{(0)})^2\mathcal G_i^2\bigr]\right|
     <0.000007.
 \end{gathered}

\end{equation}
In particular, \(|G_i^{(N)}(x)|\le x_*\) for every \(N,i,x\), and
\(|\mathcal G_i|\le x_*\) for every bit sequence.

For uniformly distributed words \(a\in\{0,1\}^N\),
\begin{equation}
 \Pr\left\{\sum_{i\in J_N}\log F_i(x(a))>0.000220N\right\}
 \longrightarrow1.

\end{equation}

For every compact open subgroup $U<T$, the algebra $D_*^U$ is a
countable product of finite matrix algebras.  Moreover,
\begin{equation}
 D_*^T=\mathbb C1,

\end{equation}
and the source action $\beta$ is nontrivial.

Let \(R_n\to\infty\), let \(\Theta_n\) be admissible for \(T\), and suppose
\eqref{eq:ray-short-fixed} holds.  Fix an isolated source
factor and a positive split axis in it.  For any \(t_n,u_n\ge0\),
if the individual spherical laws converge weakly to \(P_t,P_u\),
then
\begin{equation}
 P_{\Theta_n,R_n}(t_n+u_n)\longrightarrow P_t*P_u .
\end{equation}
The same statement permits pre- and post-translations in fixed
compact subsets of \(G\).

There is a dense linear subspace $\mathscr E\subset\mathcal H$ such
that, for each fixed set of mask controls and each $\xi\in\mathscr E$,
there is a finite constant $C_\xi$ with
\begin{equation}
 \int_{B_S^{(2)}}
  \langle\xi,p_\delta(x,y)\xi\rangle\,dm(x,y)
 \le C_\xi\delta^{-Q_T}

\end{equation}
for all controlled families and $0<\delta\le\delta_0$.
The subspace can be chosen invariant under the source and target
actions and under every bounded operator commuting with all
$P_x(f)$.  Constants may change with the vector and the fixed
controls, but not with $\delta$ or the chosen masks.

For opposite tuples $Y,F$, on transverse tuple patches,
\begin{equation}
 \begin{split}
 b_{Y,i^*}^{\mathrm i\theta}P_Y(dw)\,
 b_{F,i}^{\mathrm i\theta}P_F(dv)\,
 k_T(w,v)^{\mathrm i\theta}
 &=C(Y,F)^{\mathrm i\theta}P_Y(dw)P_F(dv),\\
 C(Y,F)&=c\,k_S(y_{i^*},x_i),\qquad c>0.
 \end{split}
\end{equation}
The statement also holds on the conjugate slot, with conjugation and the
corresponding sign change.  At an isolated position only the vertex-pair
transversality is needed.

On a full lexicographic path,
\begin{equation}
 E(e^{\mathrm i\theta_n r_i})J
 =J\!\left(C(F^-,F)^{-\mathrm i\theta}
   \bar b_{F^-,i^*}^{\mathrm i\theta}\otimes b_{F,i}^{\mathrm i\theta}\right)
 \qquad(\theta_n\to\theta).
\end{equation}
There is an invertible linear map $A_*$ on the split-coordinate spaces
satisfying
\begin{equation}
 \lambda_{p(i)}^T A_*=\lambda_i^S,\qquad
 A_*e_i=s_i e_{p(i)},\qquad 2\rho_TA_*=2\rho_S.
\end{equation}
The centered Cartan vector $\Delta=\mu(h^{-1})-A_*L$ has a tight sharp
commuting law on input.

Let $B_S,B_T$ be the source and target chamber spaces with their compact
probabilities.  There is a constant $0<c_0<\infty$ and an isometry
\begin{equation}
 \begin{split}
 V:L^2(B_T;\mathcal H)&\longrightarrow L^2(B_S;\mathcal H),\\
 (V(f\otimes\xi))(Z)&=c_0^{-1/2}D_Z^{-1/2}P_Z(f)\xi.
 \end{split}
\end{equation}
The expression on the second line is initially interpreted through positive
form integrals and then extended by the stated isometry.

Fix $F,i$.  For generic source chamber $Z$, let $Y(Z)\subset Z$ have the
tuple type opposite to $F$.  If $v$ is an ordinary target chamber, with
the relevant dual vertex used in the pairing, then
\begin{equation}
 V\bigl[k_T(v,P_{x_i})^{\mathrm i\theta}
              b_{F,i}^{\mathrm i\theta}\bigr]
 =\bigl[C(Y(Z),F)^{\mathrm i\theta}
              b_{Y(Z),i^*}^{-\mathrm i\theta}\bigr]V.
\end{equation}
Both bracketed operators are unitary.  Moreover $D_Z$ strongly commutes
with each such own-coordinate height $b_{Y(Z),i^*}$.

abstract:
We prove the compact log-smooth Kähler case of b-semiampleness. Let \(f:Y	o X\) be a surjective holomorphic map with connected fibers between smooth compact connected Kähler manifolds, and let Δ be an effective rational divisor with simple normal crossing support and coefficients in \([0,1]\), with \(K_Y+\Delta\sim_{\mathbb Q}f^*L\) for \(L\in\mathop{\mathrm{Pic}}
olimits (X)_{\mathbb Q}\). There is a smooth compact Kähler modification \(S	o X\) for which the threshold-moduli line satisfies \(M_{S_1}=
u^*M_S\) in \(\mathop{\mathrm{Pic}}
olimits (S_1)_{\mathbb Q}\) for every smooth compact Kähler modification \(
u:S_1	o S\), and some positive multiple of <i>M</i><sub><i>S</i></sub> is represented by a holomorphic line bundle generated by global sections. Horizontal components of coefficient one are allowed; neither projectivity nor a Campana orbifold Iitaka hypothesis is assumed.

statements.text:
For every admissible $J$, the threshold in
Equation~\eqref{main:physical-threshold} satisfies $0<\bc(J)<\infty$.
The supremum there is finite when $0<\beta<\bc(J)$ and infinite when
$\beta\ge\bc(J)$, including equality.

There are an integer $L=L(J)\ge2$ and a unique positive function
$\beff(J,\beta)$, defined for $\beta\ge\bc(J)$, such that along the
full sequence $N\to\infty$
\begin{equation}
 H_N\ \Longrightarrow\
       \sqrt{\frac{\beff(J,\beta)}{v_J^2}}\,\Phi_{\T}
       \quad\hbox{in }H^{-3}(\T^2).
\end{equation}
For every smooth real mean-zero $f$,
\begin{equation}
 \lim_{N\to\infty}\log\E e^{H_N(f)}
 =\frac{\beff(J,\beta)}{2v_J^2}
           (f,(-\Delta_{\T})^{-1}f).
\end{equation}
Furthermore,
\begin{align}
 \beff(J,\bc(J))&=8\pi v_J^2,\\
 \lim_{\beta\downarrow\bc(J)}
 \frac{\beff(J,\beta)-\beff(J,\bc(J))}{\beta-\bc(J)}
    &=+\infty.
\end{align}
The function $\beff(J,\cdot)$ is differentiable on $(\bc(J),\infty)$,
and for some $c_J>0$,
\begin{equation}
 \beff(J,\beta)=\beta+O_J(e^{-c_J\beta})\qquad(\beta\to\infty).
\end{equation}
For $J_\rho=\{x\in\Z^2\setminus\{0\}:|x|_\infty\le\rho\}$,
\begin{equation}
 \frac{\bc(J_\rho)}{8\pi v_{J_\rho}^2}\longrightarrow1
      \qquad(\rho\to\infty).
\end{equation}
In particular $v_{J_{\nn}}^2=1/4$ and the nearest-neighbor effective
temperature at roughening is $2\pi$.

The choices in Theorem~\ref{main:spins} can be made so that
$\pi^2b\ge\bc(J_{\nn})$ throughout the asserted Villain range and
\begin{equation}
 K_{\mathrm{Villain}}(b)
       =\frac{\beff(J_{\nn},\pi^2b)}{\pi^2}.
\end{equation}

There is a number $a=a(k)\in[0,k]$ such that $a_m(k)\to a$.
Let $B_n$ be discrete axis rectangles at mesh $n^{-1}$ whose endpoints
converge to those of a fixed nondegenerate rectangle $B$. For every finite
collection of smooth shifts $g$ on a neighborhood of $\overline B$,
\begin{equation}
 \log\E_{B_n,k}\exp\{(h,A_{B_n}g(\cdot/n))\}
 \longrightarrow \frac a2\int_B|\nabla g|^2.
\end{equation}
The corresponding tests converge jointly to centered Gaussian variables
with covariance $a\int_B\nabla g\cdot\nabla g'$; all joint moments converge.
For zero-total profiles $f_n$ whose scaled piecewise constant densities
$n^2f_n$ converge in $L^2(B)$ to a bounded piecewise continuous $f$ of
integral zero, the corresponding assertion is
\begin{equation}
 \log\E_{B_n,k}e^{(h,f_n)}
 \longrightarrow \frac a2(f,(-\Delta_{B,N})^{-1}f)_{L^2(B)}.
\end{equation}
Here the inverse Neumann Laplacian is on integral-zero functions. These
statements hold along every such sequence of rectangles and jointly for
mixed finite lists of the displayed tests.

For every admissible $J$ and $k>0$,
\begin{equation}
 a(k)=0\quad\hbox{or}\quad 8\pi\le a(k)\le k.
\end{equation}

For every fixed $J$ and $k>0$,
\begin{equation}
 a(k)>0\quad\Longleftrightarrow\quad
 \sup_{R\ge1}\E_{\mu^0_{J,v_J^2k,R}}h_0^2=\infty.

\end{equation}

There exist $b_0<\infty$, $\rho\in(0,1)$, and, for each $b\ge b_0$, a
choice $s=s(b)=O(e^{-cb})$ independent of the domain, sources, and
translation of the block hierarchy, such that the plane activities obey
\begin{equation}
 \mathcal K_j^b(X)=\ind_{X=\{B\}}\frac{t_j}2 e_B+
                        \mathcal P_j(X),\qquad
 u_j:=|t_j|+\norm{\mathcal P_j}_{\kappa,A_U,j}
                       \le C z\rho^j .                  
\end{equation}

Put $K=K_{\mathrm V}(b)=b/(1+s(b))$ and $A_{\mathrm V}(b)=c(b)^{-1}$,
and write
\[
 Z_{n,x}=A_{\mathrm V}(b)e^{G_n(x,x)/(2K)}e^{i\theta_x},\qquad
 Z_{n,x}^{(+)}=Z_{n,x},\quad Z_{n,x}^{(-)}=\overline{Z_{n,x}}.
\]
For distinct limiting interior locations and any signs,
\begin{equation}
 \E\prod_{i=1}^kZ_{n,x_i}^{(\varsigma_i)}
 \longrightarrow
 \exp\!\left\{-\frac1K\sum_{i<j}\varsigma_i\varsigma_j
                        G_D(x_i,x_j)\right\}.            
\end{equation}
All signed lattice expectations in this display are nonnegative.  For
some $Q<2$ and every compact interior set, uniformly in $n,x,y$ there,
\begin{equation}
 0\le\E Z_{n,x}^{(\varsigma)}Z_{n,y}^{(\tau)}
           \le C(|x-y|+n^{-1})^{-Q}.                     
\end{equation}
These conclusions hold along the full sequence of integers $n$.

There is \(b_0(\mathrm{XY})<\infty\) such that for every fixed
\(b\ge b_0(\mathrm{XY})\), the choices
\begin{equation}
 K_{\mathrm{XY}}(b)=\frac{b}{s+d_c^2/\mu},
 \qquad A_{\mathrm{XY}}(b)=c_b^{-1}

\end{equation}
satisfy \(K_{\mathrm{XY}}(b)>1/(4\pi)\),
\(A_{\mathrm{XY}}(b)>0\), and \(K_{\mathrm{XY}}(b)/b\to1\).
Along every integer sequence \(n\to\infty\),
\[
 n^{-2}\sum_{x\in D_n^\circ}
  A_{\mathrm{XY}}(b)e^{G_n(x,x)/(2K_{\mathrm{XY}}(b))}
       e^{i\theta_x}\delta_x
       \ \Longrightarrow\ V_{K_{\mathrm{XY}}(b),D}
\]
in \(H^{-3}_{\mathrm{loc}}(D)\), and jointly on any finite
collection of complex smooth compactly supported test functions.
The limit uses the full Dirichlet-variance Wick convention.

If $a(k_h)>8\pi$, then $k_h$ has an open neighborhood on
which $a>8\pi$ and $a$ is continuously differentiable.
Consequently
\begin{equation}
 a(k_c)=8\pi .
\end{equation}

As $k\downarrow k_c$,
\begin{equation}
 \frac{d}{dk}a(k)\longrightarrow+\infty ,
 \qquad
 \frac{a(k)-a(k_c)}{k-k_c}\longrightarrow+\infty .
\end{equation}

In either setting~\textup{(i)} or~\textup{(ii)}, the enhancement
$\mathfrak B$ induces a perfect obstruction theory
$E_B\to L_B$, with virtual tangent
\begin{equation}
E_B^\vee\simeq
\fib\left\{
\RHom(S',Q)\xrightarrow{d\det^o}
\RGamma(\mathcal I_o)[1]\otimes\mathcal O_B
\right\}.
\end{equation}
It is $G$-equivariant.  Its virtual dimension is
\begin{equation}
v=2n+(A-K)D.
\end{equation}

The enhancement $\mathfrak W$ induces a perfect obstruction theory
$E_W\to L_W$.  For $k:W\hookrightarrow B$, there is a natural
isomorphism of obstruction theories
\begin{equation}
(Lk^*E_B)^{\mathrm{fix}}\xrightarrow{\sim}E_W,
\end{equation}
compatible with their maps to $L_W$.  Its virtual tangent is
\begin{equation}
E_W^\vee\simeq
\fib\left\{
\bigoplus_{i=1}^2\RHom(S'_i,Q_i)
\longrightarrow\RGamma(\mathcal I_o)[1]\otimes\mathcal O_W
\right\}.
\end{equation}
The moving virtual normal complex is
\begin{equation}
N_W^{\vir}=\bigoplus_{i\ne j}\RHom(S'_i,Q_j),
\end{equation}
where the $(i,j)$ summand has the difference between the characters on
$L_j$ and $L_i$, or evaluated weight $w_j-w_i$.

For every fixed $S\in\{\tfrac12,1,\tfrac32,\ldots\}$ and every
interaction satisfying \eqref{eq:interaction},
\begin{equation}
 \lim_{\beta\to\infty}\beta^{3/2}\bigl(S-m_{S,J}(\beta)\bigr)
   =\frac{\zeta(3/2)}{8\pi^{3/2}\sqrt{\det D_{S,J}}}.

\end{equation}

For every finite cube, every $\beta>0$, and every real $h$,
\begin{equation}
 Z_\Lambda(h):=\Tr e^{-\beta(H^J_{S,N}-hM_{S,N})}
   =e^{\beta w_\Lambda/4}\,
           \mathbb E_{\rm b}\sum_\sigma e^{\beta hM(\sigma)}.
\end{equation}
At zero field the Gibbs spectral law of total magnetization is obtained
by weighting each picture by $2^{\#\{\text{cycles}\}}$, coloring its
cycles independently and fairly, and evaluating $M(\sigma)$.  More
precisely, for every function $\Phi$ on the finite spectrum of
$M_{S,N}$,
\begin{equation}
 \frac{\Tr\bigl(e^{-\beta H^J_{S,N}}\Phi(M_{S,N})\bigr)}{Z_\Lambda(0)}
   =\frac{\mathbb E_{\rm b}\sum_\sigma\Phi(M(\sigma))}
           {\mathbb E_{\rm b}2^{\#\{\text{cycles}\}}}.
\end{equation}

For $E,T$ as above,
\begin{equation}
 d_E(i)=\frac{r(E,\{i\})}{1+r(E,\{i\})}\quad(i\notin E),
 \qquad
 \mathbb P_E(T\subseteq\mathcal B_E)\le(2r(E,T))^{m_T}.
\end{equation}

There is \(\beta_1<\infty\), independent of the cube and pins,
such that for every \(\beta\ge\beta_1\), every allowed pin set
\(E\), and every nonempty sparse set \(T\) at one deterministic
time, disjoint from \(E\),
\begin{equation}
 \mathbb P_E(T\subseteq\mathcal B_E)
 \le\beta^{-9|T|/10}.
\end{equation}
Consequently \eqref{eq:irregularity} and \eqref{eq:good-exposure}
hold under every allowed pin law, with no induction hypothesis.

For every sufficiently large \(\beta\), uniformly in all allowed
pin sets \(E\), cubes, cuts, and slot-time points \(i\notin E\),
\begin{equation}
 r(E,\{i\})\le C\beta^{-3/2}.
\end{equation}
Consequently, for every allowed pin set \(D\) and every slot-time
point \(j\) at a deterministic time,
\begin{equation}
 \mathbb P_D(j\in\mathcal B_D)\le C\beta^{-3/2}.
\end{equation}

There is a constant \(C<\infty\), independent of \(K\), with the
following property. For every integer \(K\ge1\) there are
\(\beta_K<\infty\) and a nonnegative function
\(\epsilon_K(\beta)\to0\) as \(\beta\to\infty\), such that for
\(\beta\ge\beta_K\), every finite cube, every allowed pin set
\(E\), and every deterministic slot-time point \(i\),
\begin{equation}
 d_E(i)\le\beta^{-3/2}
 \left(\frac\kappa\ell\sum_{n=1}^{2K-1}n^{-3/2}
                  +CK^{-1/2}+\epsilon_K(\beta)\right).
\end{equation}
If the site \(x\) of \(i\) additionally satisfies
\begin{equation}
 \mathfrak B_{R_K}(\bar x)\subseteq\Lambda^\circ,
 \qquad E\text{ has no pin over }\mathfrak B_{R_K}(\bar x),
\end{equation}
then
\begin{equation}
 d_E(i)\ge\beta^{-3/2}
 \left(\frac\kappa\ell\sum_{n=1}^{K}n^{-3/2}
                                      -\epsilon_K(\beta)\right).
\end{equation}
For \(i\notin E\), the same two bounds hold for \(r(E,\{i\})\),
with the same choice of error function. The threshold and error
function are independent of the cube, cut, slot, and number, locations,
and times of all finite extra pins. Only the fixed model and geometric
choices, and \(K\), may affect them.

For every fixed $\beta>0$ and $h\ge0$,
\begin{equation}
 \lim_{N\to\infty}p_N^+(h)=p_\beta(h).

\end{equation}

For every $\delta>0$, there is a finite constant $C_\delta$ such that
\begin{equation}
 \norm{T_\delta f}_{L^3(\RR^3)}
