There are a smooth function $u$ and a smooth vector field $X$ on $\Omega$,
smooth up to its one-sided boundary, with the following properties.
\begin{enumerate}[label=\textup{(\roman*)}]
\item They satisfy $u\ge |X|_g$, $u>0$ in $\operatorname{int}\Omega$, and
\begin{equation}
 u\mu+J(X)=0.

\end{equation}
With symmetric indices denoting averaging, their equations are
\begin{align}
 \nabla_{(i}X_{j)}&=-uK_{ij},
 \\
 \Delta u&=-\operatorname{div}_g\bigl(K(X,\cdot)^\sharp\bigr),
 \\
 \nabla^2u
 &=u(\Ric_g+\tau K-2K^2)-\mathcal L_XK+X_{(i}J_{j)}.

\end{align}
Here $X_i=g_{ij}X^j$ and $(K^2)_{ij}=K_{ik}K^k{}_j$.
\item On the chosen asymptotically flat end,
\begin{equation}
 (u,X)=(b^0,b)+O_2(r^{-q_0}).

\end{equation}
\item At the boundary, for the unit normal $\nu$ pointing into $\Omega$,
\begin{equation}
 X=u\nu,\qquad
 \partial_\nu u+K(X,\nu)=\kappa.

\end{equation}
Either $u>0$ everywhere on $S$ or $u=0$ everywhere on $S$.
\item On $\mathbb R\times\operatorname{int}\Omega$, set
\begin{equation}
 \mathbf g=-u^2\,\mathrm dt^2
   +g_{ij}(\mathrm dx^i+X^i\,\mathrm dt)
          (\mathrm dx^j+X^j\,\mathrm dt),
 \qquad \xi=\partial_t,\qquad N=u^2-|X|_g^2.

\end{equation}
For the future normal $n=u^{-1}(\xi-X)$, the slice $t=0$ has exactly the
original induced metric $g$ and second fundamental form $K$, with the convention
of Theorem~\ref{q4:thm:rigidity}.  Moreover,
\begin{equation}
 \Ric_{\mathbf g}(\xi,\cdot)=0,
 \qquad \Ric_{\mathbf g}=0\quad\hbox{on }\{N>0\}.

\end{equation}
\item We have $N\ge0$, $N\to1$ at infinity, and $N>0$ in a full collar just
outside $S$.  More precisely, in the positive boundary-lapse case,
\begin{equation}
 N|_S=0,\qquad
 \mathrm dN|_S=2u\kappa\,\nu^\flat=2\kappa X^\flat.

\end{equation}
In the zero boundary-lapse case, if $s\ge0$ is the original $g$-normal distance
from $S$, there are smooth one-sided fields $d,Y_2$ such that
\begin{equation}
 u=sd,\qquad X=s^2Y_2,\qquad d|_S=\kappa,\qquad
 N=s^2\bigl(d^2-s^2|Y_2|_g^2\bigr).

\end{equation}
Consequently all zeros of $N$ in $\operatorname{int}\Omega$ lie in a compact
subset of that interior.
\end{enumerate}

Under these assumptions, there are rows $a_i\in H^1(\R;\R^m)$,
$i\in\mathcal I$, each a linear combination of eigenfunctions with
eigenvalue $-k_i^2$, such that
\begin{equation}
 -a_i''-a_iW=-k_i^2a_i
 \quad\text{in distributions.}

\end{equation}
The rows $a_i$ are allowed to vanish.  On a common set of full measure, they
define a Hilbert--Schmidt operator $A(x):\R^m\to\mathscr H$, and there exists
a bounded self-adjoint operator $B$ on $\mathscr H$ with
$\|B\|_{\op}\leq\kappa$ such that
\begin{equation}
 [B,\Lambda^2]=0,\qquad
 \Lambda^2-B^2=(AA^T)^r,\qquad
 a_i'(x)=(BA)_{i,\cdot}\quad(i\in\mathcal I).

\end{equation}
Moreover,
\begin{equation}
 W(x)=q\bigl(A(x)^TA(x)\bigr)^r
 \quad\text{almost everywhere.}

\end{equation}
The operator $B$ is asserted to exist separately at each such point $x$;
no measurable choice is required.

Let $n\geq1$ and let $B,V\in\C^{n\times n}$ be Hermitian.
Suppose that
\begin{equation}
 Y_s=(sI-B)^2,\qquad X_s=Y_s+V\geq bI
 \quad(s\in\R)
\end{equation}
for some $b>0$.  Set
\begin{equation}
 R(t)=\frac1\pi\int_\R(X_s+tI)^{-1}\,ds,
 \qquad P(t)=t^{-1/2}I-R(t),\qquad t>0,
\end{equation}
and
\begin{equation}
 N=c_\sigma\int_0^\infty t^\beta P(t)\,dt.
\end{equation}
These integrals converge absolutely in matrix norm, and $R(t)>0$.
There are continuous Hermitian matrices $L(t)=R(t)^{-1}>0$ and
$Z(t)$ satisfying
\begin{equation}
 V+tI=L^2+Z^2+i[B,Z],\qquad
 LZ+ZL+i[B,L]=0.
\end{equation}
If $N\geq0$, then
\begin{equation}
 \begin{split}
 \tr(NV)-\tr(N^q)
 =c_\sigma\int_0^\infty t^\beta\Bigl(
    \tr(RZ^2)
    +q\bigl\|R^{-1/2}-R^{1/2}(tI+N^r)^{1/2}\bigr\|_{\HS}^2
    \Bigr)\,dt.
 \end{split}
\end{equation}
In particular, $\tr(NV)\geq\tr(N^q)$.

The limit in \eqref{field:definition} exists locally uniformly, and
$M_\delta:\Sym_n\to\Sym_n$ is locally Lipschitz.  There is a
$C^1$ function $J_\delta:\Sym_n\to\R$, normalized by
$J_\delta(0)=0$, such that
\begin{equation}
 dJ_\delta(B)[H]=-\tr(M_\delta(B)H).
\end{equation}
The scalar function $\mu_\delta$ is locally Lipschitz and strictly
increasing, with $\mu_\delta(0)=0$, and
\begin{equation}
       \mu_\delta(z)=(z+\delta)^\sigma-\delta^\sigma
       \qquad(z\geq0).
\end{equation}
For every real unit vector $e$, and for every standard basis vector
$e_i$, respectively,
\begin{align}
 e^{\mathsf T}M_\delta(B)e
  &\leq\mu_\delta\bigl(e^{\mathsf T}K^2e
                         -(e^{\mathsf T}Be)^2\bigr),
       \\
 Be_i=ye_i\quad&\Longrightarrow\quad
 M_\delta(B)e_i=\mu_\delta(k_i^2-y^2)e_i.

\end{align}
For each diagonal sign matrix $S$,
\begin{equation}
                 M_\delta(SBS)=SM_\delta(B)S.
\end{equation}
Finally,
\begin{equation}
 \begin{split}
 J_\delta(-K)-J_\delta(K)
 &=\sum_{i=1}^n\int_{-k_i}^{k_i}\mu_\delta(k_i^2-s^2)\,ds\\
 &\longrightarrow b_\sigma\sum_{i=1}^n k_i^{2\sigma+1}
       \qquad(\delta\downarrow0).
 \end{split}
\end{equation}

If $M=M_\delta(B)\geq0$, then
\begin{equation}
 Q_s(B)\geq0\quad(s\in\R),\qquad
             0\leq M\leq\kappa^{2\sigma}I.
\end{equation}
Set $V=K^2-B^2+\delta I$ and use $B,V$ in
\eqref{trace:resolvents} and \eqref{trace:N}.  Then the symbol
$(sI-B)^2+V=Q_s(B)+\delta I$ is bounded below by $\delta I$, and
\begin{equation}
                         N=M+\delta^\sigma I.
\end{equation}
In particular, the hypotheses of Theorem~\ref{trace:deficit} hold.

Writing $\mu_*=\mu_{K,M,\sigma}$, one has
\begin{equation}
 \int_{X_n}E_f\dd\mu_*
 =\frac1{\sqrt D\,\kappaK}
       \sum_{\mathfrak a\subset R,\ \mathfrak a\ne0}
           P(\mathfrak a)\cV_f(\N\mathfrak a/Q).
\end{equation}
The identity holds for nonnegative extended integrals.

Fix $A_0\ge1$ and $0<\eta\le1$. For $Q$ sufficiently large in terms
of $n,A_0,\eta$,
\begin{equation}
 \sum_{x-y<\N\mathfrak a\le x}P(\mathfrak a)
 \ll_n \frac{\kappaK y}{q}
 \qquad
 (Q^{3/4}\le x\le A_0Q,\quad \eta x\le y\le x).
\end{equation}
The implied constant is independent of $A_0$ and $\eta$.

Every sequence of the packet probabilities with $Q\to\infty$
is tight. More precisely, for $0<\theta<1$,
\begin{equation}
 \limsup_{Q\to\infty}\mu_*
 \{\Lambda:\exists\,0\ne v\in\Lambda,\ \|v\|_\infty<\theta\}
       \le C_n\theta^n.
\end{equation}
Every subsequential probability limit is $A_n$-invariant.

For every nonnegative Borel \(f\) on \(\R^4\),
\begin{equation}
 \int_{X_4}E_f\,d\mu_*
 =\frac1{\sqrt D\,\kappa}
   \sum_{\substack{\mathfrak a\subset R\\\mathfrak a\ne0}}
       P(\mathfrak a)\,
       \mathcal V_f\bigl(\Nm\mathfrak a/X\bigr).
\end{equation}
Both sides are allowed to be infinite.

For \(z\in F\) with \(\Tr z=m\ne0\), a positive value of \(M(z)\)
requires \(z\) to be integral outside \(S\).  For such integral \(z\),
\begin{equation}
 M(z)\le32
 \prod_{p\in S}
 \left(
 |D|_p^{-1/2}
 \frac{1-p^{-1}}
      {\displaystyle\prod_{\mathfrak p\mid p,\ \mathfrak p\subset R}
                         (1-\Nm(\mathfrak p)^{-1})}
 f_p^*(z)\right)
 \prod_{p\notin S}b_p(z).

\end{equation}
All products in this assertion are finite at every contributing \(z\).

For every fixed $m\in\Z\setminus\{0\}$ and $L>1$, there are constants
$r_0>0$ and $C_{m,L}>0$ with the following property.  For every sequence
of the fields, orders, and embedding orderings in Theorem~\ref{thm:main}
