 C^+(x_i,y_j)\leq f/q,
 \qquad |\mathcal A(C^+)|\leq2|\mathcal A(C)|.
\]
If $P^r$ is the matrix from $V^+$ to $V$ defined by
\begin{equation}
 P^r(x_i,x)=r_i(x),\qquad
 P^r(x_i,z)=0\quad(z\ne x),

\end{equation}
then
\begin{equation}
 C^+P^r=P^rD.

\end{equation}

For every stage,
\begin{equation}
 C_lP_l^c=P_l^c-B_l(I-S).

\end{equation}
The vectors $W_l=B_le$ satisfy
\begin{equation}
 0\leq W_l\leq1,\qquad
 W_l=P_l^cp_0-C_lP_l^cp_0,

\end{equation}
and their updates are
\begin{equation}
 W_{l+1}(x_i)=r_i(x)\bigl(W_l(x)+(E_lW_l)(x)\bigr).

\end{equation}
If $\bar x_l$ is the all-primary copy of a base vertex $x$, then
\begin{equation}
 0\leq p_0(x)-W_l(\bar x_l)
       \leq |V_0|\,2^{-(H-1)l}.

\end{equation}
Consequently there is $L=O(B)$ for which the last upper bound is
strictly less than $1/16$ for every base vertex $x$.
In particular, $p_0(x)=0$ implies $W_L(\bar x_L)=0$, and
$p_0(x)\ge1/2$ implies $W_L(\bar x_L)>7/16$.
Every full stage domain has size $2^{O(B)}$ and admits $O(B)$-bit
addresses.

For every $6\times6$ Hadamard matrix $H$, at least one of the following
conditions holds:
\begin{enumerate}[label=\textup{(\Alph*)},ref=\Alph*]
  \item[(M)] $g_{H^\pi}(\alpha)=0$ for every row permutation $\pi$;
  \item[(C)] the entrywise square $H^{\circ2}$ is a Hadamard matrix.
\end{enumerate}

Each matrix $Z_\lambda$ specified above is positive definite. Under the
mixed-moment identities of Lemma~\ref{lem:mixed-reductions}, the forms
\eqref{eq:Young-functions} satisfy
\begin{align}
 5\sum_\lambda 10^{15-e_\lambda}
       \E\bigl(Y_\lambda^*Z_\lambda Y_\lambda\bigr)
 &\le
       \frac{-613302797399911+179721388988719}{6480}
       \\
 &=-\frac{2007321335237}{30}<0.\notag
\end{align}

The masses satisfy
\begin{equation}
 0<Z_0\le\Lambda\le(1+d^2)Z_0,
 \qquad \pi_{\min}\ge(C+1)^{-2d}.
\end{equation}
Draw $X$ with law $\pi$ and then a uniform $A\in\mathcal F_X$.
Declare success if $X$ is a transversal and every large entry of $A$
is at least $L$.  Subtracting $L$ from these entries gives a uniform
original table conditional on success, and
\begin{equation}
 \Pp\{\text{success}\}\ge\frac{1}{2(1+d^2)}.
\end{equation}

For the measures \eqref{eq:gibbs}, the full transfer gap
\eqref{eq:mass-definition} satisfies
\begin{equation}
 \lim_{\beta\to\infty}
    \frac{\exp(\pi\beta)}{\sqrt\beta}\,m_{\mathrm{lat}}(\beta)
       =32\exp\!\left(\frac\pi4-\frac12\right).
\end{equation}

For every $\beta>0$, in the periodic plane state,
\begin{equation}
 m(\beta)=-\log r_*(\beta)
 =-\log\lim_{n\to\infty}
       \bigl(\mathbb E_{\mu_\beta}q_0^1q_{(n,0)}^1\bigr)^{1/n}.

\end{equation}
The transfer norm on the even subspace orthogonal to the vacuum
is at most $r_*(\beta)^2$. Its gap is therefore at least
$2m(\beta)$. The logarithms can be read in the extended sense;
the imported upper bound below makes them finite throughout
the large-$\beta$ regime.

For all admitted trajectories of Proposition~\ref{prop:wilson-input}
with $N\ge N_0$ and terminal coupling $h\in I_H$, there are
constants $C_H,w_H<\infty$, independent of the trajectory,
such that every dyadic $w\ge w_H$ satisfies
\begin{equation}
 \left|E(w)-\frac{m(\beta)}a\right|\le C_Hw^{-1/4}

\end{equation}
and
\begin{equation}
 \left|-\frac{\log\Delta(w)}w-\frac{m(\beta)}a\right|
       \le C_Hw^{-1/4}.

\end{equation}

As $B\to\infty$, with $b=b(B)$ and $m_*$ defined above,
\begin{equation}
 \begin{aligned}
 b(B)&=\frac B2+\frac{\log(4\pi B)+1}{\pi}+o(1),\\
 m_*&\sim\frac{8}{\pi e\sqrt B}\,e^{-\pi B/2},\\
 2\int_{-B}^B\rho_B(x)\,dx
       &=\frac{B^2}{4}+\frac B\pi\log B+O(B).
 \end{aligned}

\end{equation}
There are positive constants $c_1,C_1$ such that, for all sufficiently
large $B$, $\rho_B\ge c_1\sqrt B$ within distance one of either endpoint,
and $\rho_B\le C_1B$ throughout the interval.  For every $B>0$, the
solution also satisfies $\sup_{y\in\mathbb R}|\epsilon'(y)|\le\pi/2$.

Fix the blocking factor $L$ and the admission constants as in
Sections~\ref{sec:rg}--\ref{sec:comparison}. For every sufficiently large
$\beta$, choose any matched trajectory satisfying \eqref{eq:R15}, with its
parameters $b,r,c_x,c_t$. For $i=x,t$,
\begin{equation}
 \lim_{m\to\infty}\limsup_{s\to\infty}\limsup_{\beta\to\infty}
 \left|h_i^B(mL^s)-h_i^F(mL^s)\right|=0,

\end{equation}
where $m$ tends to infinity through sufficiently large dyadic integers.
The inner limit is taken with $m$ and $s$ fixed.

For every choice of matched parameters satisfying \eqref{eq:R15},
\begin{equation}
 \beta-b=\frac14-\frac{1+\log 2}{2\pi}+o(1)
 \qquad (\beta\to\infty).

\end{equation}

The implemented preparation just described has success probability exactly
\begin{equation}
 p_*=(1-2^{-n})^{n^{10}}.
\end{equation}
Every successful branch outputs the correct prime factorization of $N$. The preparation has polynomial worst-case time and workspace, and $p_*>1/2$ is an initially known dyadic with polynomial bit length.

For the algebra in Equation~\eqref{eq:quotient-algebra}, over every
commutative ring $S$ with identity,
\begin{equation}
 \operatorname{tr}(M_v)=\mathcal L(vJ)
 \qquad(v\in S[x]).
\end{equation}

Let $t,r\ge1$ be integers.  For each $1\le i\le t$, let $X_i$ and
$\mathcal M_i$ be nonempty finite sets with uniform probability, and
let $Y_i$ be a specified copy of $(\mathbb F_2)^a$, where $a\ge1$ and
$L=2^a$.  For $m\in\mathcal M_i$ and $y\in Y_i$, let
$\pi_{i,y}^m$ be a probability distribution on $X_i$.
Suppose that, for some $\theta\ge0$, these distributions satisfy
\begin{equation}
  \E_{m\in\mathcal M_i}\pi_{i,y}^m(x)=\frac1{|X_i|}
  \qquad(x\in X_i, y\in Y_i)
\end{equation}
and, for every real function $g:X_i\to\R$ and every $y\in Y_i$,
\begin{equation}
  \E_{m\in\mathcal M_i}
  \left(\sum_{x\in X_i}\pi_{i,y}^m(x)g(x)-\E_{x\in X_i}g(x)\right)^2
  \le\theta\E_{x\in X_i}g(x)^2.
\end{equation}
Let $F:\prod_iX_i\to\mathbb S_+^r$ satisfy $\tr F(x)\le B$ for all
$x$, where $B>0$ and $\mathbb S_+^r$ is the cone of real symmetric
positive semidefinite $r$-by-$r$ matrices.  Fix $\lambda>1$ such that
\begin{equation}
  L\lambda^2C_L\theta\le1,
\end{equation}
where $C_L=2^{L-1}$ is the constant of Lemma~\ref{lem:splitting}.
For $m=(m_1,\ldots,m_t)\in\prod_i\mathcal M_i$, define
\begin{equation}
  \overline F_m(y)
  =\sum_{x\in\prod_iX_i}
     \left(\prod_{i=1}^t\pi_{i,y_i}^{m_i}(x_i)\right)F(x).
\end{equation}

There is a finite integer $R$ and a family of functions
$H_q^m:\prod_iY_i\to\R^{R\times r}$, indexed by
$m\in\prod_i\mathcal M_i$ and $q\in\Lambda^t$, such that
\begin{equation}
  \overline F_m(y)=\sum_{q\in\Lambda^t}H_q^m(y)^{\mathsf T}H_q^m(y).
\end{equation}
For each $m,q$, form the horizontal concatenation and its Gram matrix
\begin{equation}
  U_q^m=
    \left[\lambda^{\operatorname{dist}(q,p)/2}
           \widehat H_{q,p}^m\right]_{p\in\Lambda^t},
  \qquad C_q^m=U_q^m(U_q^m)^{\mathsf T},
\end{equation}
where $\widehat H_{q,p}^m$ is the Fourier coefficient of $H_q^m$ at $p$.
The family can be chosen so that, for independent uniform $m_i$,
\begin{equation}
  \E_m\sum_{q\in\Lambda^t}\normF{C_q^m}^2\le2^tB^2.
\end{equation}
Consequently, at least one $m$ satisfies
\begin{equation}
  \sum_{q,p\in\Lambda^t}
    \lambda^{\operatorname{dist}(q,p)}\normF{\widehat H_{q,p}^m}^2
  \le L^t\sqrt r\,B\,2^{t/2}.
\end{equation}

For every integer $n\ge3$ and every finite $\beta>0$, there are constants
$A=A(n,\beta)<\infty$ and $m=m(n,\beta)>0$ such that, for every finite
nearest-neighbor square-lattice subgraph $G$, every strength array
$b\in[0,\beta]^E$, and all $x,y\in V$,
\begin{equation}
 0\le \langle\sigma_x\cdot\sigma_y\rangle_{G,b}^{(n)}
 \le A\exp(-m\|x-y\|_2).

\end{equation}

Let $\Lambda_L=[-L,L]^2\cap\Z^2$, with all its nearest-neighbor edges,
free boundary conditions, and constant strength $\beta>0$. For every
$n\ge3$ and $x\in\Z^2$,
\begin{equation}
 \limsup_{L\to\infty}
 \left|\langle\sigma_0\cdot\sigma_x\rangle_{\Lambda_L,\beta}^{(n)}\right|
 \le A e^{-m\|x\|_2},

\end{equation}
with the constants of Theorem~\ref{thm:main}. Every subsequential local
weak limit of these laws satisfies the same two-point bound.

Let \((f_i)_{i\in I}\) be a finite family of complex vertex functions
vanishing on \(P\), and put
\[
u_i=df_i,\qquad
T_{el}=\sum_{i\in I}u_i(e)\overline{u_i(l)},\qquad
Q=\sum_{i\in I}S(f_i,\bar f_i).
\]
Then
\begin{equation}

\begin{split}
R(Q,\bar Q)
&\le K_{\mathrm{rot}}(\beta)\|T\|_{\mathrm{HS}}^2\\
&\quad+\beta\sum_{i,j\in I}
\min\bigl\{\|f_i\|_\infty^2\|df_j\|_2^2,
             \|f_j\|_\infty^2\|df_i\|_2^2\bigr\},
\end{split}
\end{equation}
where
\begin{equation}

K_{\mathrm{rot}}(\beta)=6\beta^2+4\beta^{3/2}+\beta.
\end{equation}
In particular, the constants are independent of the graph, the family
size, and the values of the fixed spins.

For every finite $\beta>0$ there is a finite constant $C_\beta$ such that,
for all $N\geq2$ and all graphs and strengths just described,
\begin{equation}
 \frac{\min_{t\in\R}Z(t)}{\max_{t\in\R}Z(t)}
 \geq 1-\frac{C_\beta}{\log N}.
\end{equation}
In particular,
\begin{equation}
 \frac{Z(\pi)}{Z(0)}\geq1-\frac{C_\beta}{\log N}.
\end{equation}
The constant is independent of the subgraph, the strength array, and
the twist parameter.

Let \(n\geq1\) and let \(p>n+1\) be prime. There exist an
enumeration \(I_1,\ldots,I_{2^n}\) of the subsets of
\(\{1,\ldots,n\}\), a filtration \(F_\bullet\), and a family of
classes \(y_i\in\pi_{1-2i}D\), \(1\leq i\leq n\), with the
following properties.
\begin{enumerate}[label=(\alph*)]
\item \textbf{Filtration and unit.}
The enumeration has \(I_1=\varnothing\) and \(\max I_j\)
nondecreasing for \(j\geq2\). The filtration is
\[
 0=F_0\longrightarrow F_1\longrightarrow\cdots
 \longrightarrow F_{2^n}\xrightarrow{\simeq}X_{n,p}
\]
with \(\operatorname{cofib}(F_{j-1}\to F_j)\simeq C_{I_j}\), where
\begin{equation}
 \begin{aligned}
 C_\varnothing&=L_{n-1}S,\\
 C_I&=\Sigma^{-d(I)}L_{n-\max I}S
       \quad(I\ne\varnothing).
 \end{aligned}
\end{equation}
Under \(F_1=C_\varnothing\), the composite \(F_1\to X_{n,p}\) is the
canonical localization unit.
\item \textbf{Simultaneous product bases.}
For this one family, set \(y_\varnothing=1\) and
\(y_I=y_{i_1}\cdots y_{i_r}\) for \(I=\{i_1<\cdots<i_r\}\).
For every \(1\leq t<n\), the specified map
\begin{equation}
 L_{K(t)}
 \left(\bigvee_{I\subseteq\{1,\ldots,n-t\}}
       \Sigma^{-d(I)}S\xrightarrow{(y_I)}D\right)
 \quad\text{is an equivalence}.
\end{equation}
\end{enumerate}

The common classes of Proposition~\ref{spec:global-classes} satisfy,
for every \(1\leq t<n\),
\begin{equation}
L_{K(t)}\left(
\bigvee_{I\subseteq\{1,\ldots,n-t\}}
 \Sigma^{-d(I)}S\xrightarrow{(y_I)}D
\right)
\quad\text{is an equivalence},

\end{equation}
where \(d(I)=\sum_{i\in I}(2i-1)\), and the empty component is the
unit.

Fix a prime $p$, and let $R$ be either $MU_{(p)}$ or the
Brown--Peterson spectrum $BP$ at that prime.
For $k\geq1$, let $f_R(k)$ be the least integer $n\geq0$ for which
\begin{equation}

I_R^{\wedge n}\wedge\tau_{<k}\mathbb S_{(p)}
 \xrightarrow{\varphi_{R,n}\wedge\operatorname{id}}
\tau_{<k}\mathbb S_{(p)}
\end{equation}
is nullhomotopic.  These integers exist and satisfy
\[
\lim_{k\to\infty}\frac{f_R(k)}{k}=0.
\]
Equivalently, $f_R(k)$ is the least $n$ such that, for every connective
$p$-local spectrum $X$ and every $i<k$, a class in $\pi_iX$ of
$R$-Adams filtration at least $n$ is zero.

Let $\mathcal A$ be a finite alphabet with $A\geq2$ letters. Each of the two
constructions below gives an integer width $w\geq1$ with $w=O(\log(2A))$, an absolute constant
$a>0$, and a map $c:\mathcal A\to\{0,1\}^w$ such that, simultaneously for
every integer $L\geq0$ and all $x,y\in\mathcal A^L$,
\begin{equation}
 a w r_L(x,y)\leq r_{wL}(c(x),c(y))\leq w r_L(x,y).
\end{equation}
Here $c$ extends to words by concatenation. For arbitrary finite words,
\begin{equation}
 \ED(c(x),c(y))\leq w\ED(x,y).
\end{equation}
The code and its width depend only on $\mathcal A$, not on $L$.

In the prepared forward-test configuration, the prime-field and exchanged-pair
failures are impossible.  The nuisance planes of \Cref{fb:nuisance-planes}
are therefore impossible as well, completing the ordered-factor exclusion.

Fix $0\leq r\leq n$. Suppose cycles $b_h$ of chain degree zero and
weight $w_h$, for $0\leq h\leq r$, have been chosen successively
in the strict algebras
\begin{equation}
 \begin{gathered}
 A[e_0,\ldots,e_{j-1}],\qquad
 |e_h|_{\mathrm{chain}}=1,\quad \wt(e_h)=w_h,\\
 \partial e_h=b_h\in A[e_0,\ldots,e_{h-1}],
 \qquad b_0=\varpi u_0.
 \end{gathered}
\end{equation}
For $0\leq j\leq r+1$, these algebras determine commutative
algebras $Y_j\in\cC$, with $Y_0=\one$. For $0\leq j\leq r$,
the cycle $b_j$ represents a map
$S(w_j)\to Y_j$, and there is a cofiber sequence
\begin{equation}
 S(w_j)\otimes Y_j\xrightarrow{\,b_j\cdot-\,}Y_j
                    \longrightarrow Y_{j+1},
\end{equation}
whose second map is the algebra map adjoining the null $e_j$.
For $M=[(\MU_{(p)})_p]$ and $0\leq j\leq r+1$, there are
compatible equivalences
\begin{equation}
 h_\Omega(M\otimes Y_j)
   \simeq h_\Omega(M)\otimes_A A[e_0,\ldots,e_{j-1}].
\end{equation}

On one $\U$-large set of primes there is an equivalence of whole
$(\text{weight},\text{order})$-graded $\gr R_p^a$-modules
\begin{equation}
 \gr K_p^a\simeq
 \bigotimes_{j\leq a}^{\gr R_p^a}
 \cofib\bigl(\text{multiplication by }z_{j,\emptyset}
                         \text{ on }\gr R_p^a\bigr).
\end{equation}
Each multiplication map has source the free module whose
generator has weight $w_j$, order one, and ordinary degree
$d_j$. On the right, $\gr R_p^a$ is the free graded algebra
of all the generator spheres, with the splittings constructed
in Proposition~\ref{universal:primewise-models}.

For every $\lambda\in\Lambda$ and every integer
$m>-\nu(\lambda)$, there is a vanishing of
$\delta$-graded modules
\begin{equation}
 K^a\otimes_{R^a}
       \big(B(R_p^a)/t\big)_{\lambda,*,m}=0.
\end{equation}
The tensor product uses the $R^a$-action in the
$\delta$-grading. The notation $/t$ denotes the underlying
module cofiber of multiplication by $t$.

For each integer $a\geq 0$ there are homogeneous coefficients in
 $H_G^*$ and units $C,C'\in(H_G^0)^\times$ such that
 \begin{equation}

  \begin{split}
   C\Pi_p(x_a)={}&C'\epsilon x_{a+1}+\epsilon^2D_*
      +\sum_{0\leq j,k\leq a}D_{jk}x_jx_k\\
      &+\sum_{0\leq j<a}H_j\Pi_p(x_j)+T_*,
      \qquad T_*\in\mathfrak t_G.
  \end{split}
 \end{equation}
 All terms have cohomological degree $-p d_a$; coefficients in the
 two sums and $D_*$ are in the complementary degrees.

\label[proposition]{prop:trans-volume}
After one finite marking shrink to a pro-$p$ subgroup,
$\widehat\Omega^1_{R/\kk}$ has a
$G$-invariant frame.  In particular it has a $G$-invariant volume
generator $\eta\in\widehat\Omega^r_{R/\kk}$.

For a finite root order $h$ fixing $\kk$, the normalized Cartier
functional
\begin{equation}
 T_{\eta,h}:R^{1/h}\longrightarrow R,
 \qquad T_{\eta,h}(z)=\frac{\Cartier^{\log_p h}(z^h\eta)}{\eta}

\end{equation}
is $R$-linear and generates $\Hom_R(R^{1/h},R)$ as a module over
$R^{1/h}$.  A nonzero translation augmentation at the corresponding
finite torsor level induces a scalar multiple of this functional;
the scalar belongs to the chosen finite constant field.

\label[corollary]{cor:sphere-ranks}
For every prime $p$, every $n\geq1$, and every $j\in\mathbb Z$, the free
rank is
\begin{equation}
 r_{p,n,j}
   =\#\left\{I\subseteq\{1,\ldots,n\}:
            \sum_{i\in I}(1-2i)=j\right\}.
\end{equation}
Equivalently, these ranks are the graded dimensions of the exterior
$\Qp$-algebra on generators in degrees $-1,-3,\ldots,-(2n-1)$.

For the extracted data of Proposition~\ref{prop:terminal-limit} and the
model $W$ of Proposition~\ref{prop:limiting-nef}, take $i$ sufficiently
large.  There is a finite generalized $Q_{i,W}$-program
$W\dashrightarrow W_i$ consisting only of flips, with the following
properties:
\begin{enumerate}
 \item $Q_{i,W_i}$ is nef;
 \item every step is trivial for the transformed class $P$ and for
       each $P^j$ in \eqref{eq:nef-decomposition};
 \item the transformed $P^j$ are nef adjoints of ordinary rational
       klt pairs, and the fixed multiples $\ell_jP^j$ are line bundles;
 \item every $Q_{i,W_i}$-trivial curve is $P_{W_i}$-trivial.
\end{enumerate}

The set $A$ is a nonempty compact semigroup of nonexpansive selfmaps
of $K$ and contains an idempotent $P$.  There is a point $x\in K$ with
$P(x)=x$ such that the nonempty weakly compact set
\begin{equation}

 D_x=\bigcap_{m\geq1}
       \overline{\{h(x):h\in\mathcal H_m\}}^{\,\mathrm{weak}}
\end{equation}
satisfies
\begin{equation}

 x\in\overline{\conv D_x}^{\,\norm{\cdot}}.
\end{equation}

There is an infinite ordered tree with the maps, points, and positive
weights described above.  Each nonroot node $v$ also has a budget
$e_v>0$, a functional $f_v\in X^*$ with $\norm{f_v}\le1$, and the
finite earlier-candidate list and predictions just defined.  These
data have the following properties:
\begin{enumerate}
 \item The budgets satisfy
 \begin{equation}
   \sum_{v\ne r}e_v\le\frac1{128}.

 \end{equation}
 Define
 \begin{equation}
  \tau_0=\frac12,\qquad
  \tau_k=2^{-k-1}
       \min\{e_u:u\in L_i,\ 1\le i\le k\}\quad(k\ge1).

 \end{equation}
 Every node $u\in L_k$ satisfies
 \begin{equation}
  \norm{\sum_{\widehat v=u}\alpha_v y_v-x}\le\tau_k.

 \end{equation}
 \item For every nonroot node $v$,
 \begin{equation}
  \sum_{p\prec v}\norm{G_p(y_v)-y_v}\le e_v,
  \qquad
  f_v(y_v-z)\ge1-e_v\quad(z\in E_v).

 \end{equation}
 In particular, the second inequality holds at every $z_i$ with
 $i\le k$ when $v\in L_k$.
\end{enumerate}
The budgets, functionals, and prediction sets assigned to retained
nodes remain fixed when the remaining weights at their level and all
later levels are chosen.

There are $c,C>0$ and $y_0<\infty$ such that, for $y=n\eta\ge y_0$,
\begin{equation}
 \PP\left\{
 W_2(P_H,Q_\zeta)+W_2(P_H^0,Q_\zeta^0)>y^{-c}
 \right\}\le Cy^{-c}.
\end{equation}
Here $W_2$ is transportation distance for the Euclidean metric on the
disk.  The estimate is uniform in $e\in J$ and $0<\eta\le h$.

For almost every empirical law \(\mathcal L\) with \(m\ge1\) colors,
and for every fixed height in any prescribed countable set of
positive heights,
\begin{equation}
 \begin{split}
 &\mathcal H(F^\eta_{\rm star}\mid\omega)
       -\frac d2\mathcal H(F^\eta_{\rm edge}\mid\omega)\\
 &\hspace{1cm}\ge
 m\left[\frac12\log(2\pi\mathrm e\,\eta)
       -\int\log|t-E-i\eta|\,d\nu_{d,w}(t)\right].
 \end{split}
\end{equation}

Almost surely, for every finite $k$ and every $z\in\HH$,
\begin{equation}
 M_k(z)=A_k+\PV\sum_j\frac{b_jb_j^{\mathsf T}}{x_j-z}.
\end{equation}
The principal values converge locally uniformly. Moreover,
$\Im M_k(z)$ is positive definite, simultaneously for all these $k,z$.

On $N_{\eta,\infty}$ the sequence
$\varpi,V_1,\ldots,V_h$ is regular.  Moreover
\begin{align}
 \dim\Supp_{R_{\eta,\infty}}N_{\eta,\infty}
       &\geq2d+4s+h,                                  \\
 N_{\eta,\infty}/(V_1,\ldots,V_h)N_{\eta,\infty}
       &\simeq (N_\eta^{\oplus2^h})^*.                
\end{align}

abstract:
We prove the sixth-symmetric-power case of Foulkes' conjecture. For every integer <i>b</i> ≥ 6 and every finite-dimensional complex vector space <i>V</i>, there is a \(\mathop{\mathrm{GL}}
olimits (V)\)-equivariant injection \(\mathop{\mathrm{Sym}}
olimits ^6(\mathop{\mathrm{Sym}}
olimits ^b V)\hookrightarrow\mathop{\mathrm{Sym}}
olimits ^b(\mathop{\mathrm{Sym}}
olimits ^6 V)\).

statements.text:
\label[proposition]{prop:reduction}
If \Cref{thm:nonvanishing} fails, there is a projective
$\Q$-factorial terminal fourfold $Y$, with $K=K_Y$, such that
\begin{enumerate}[label=\textup{(\roman*)}]
\item $K$ is nef, $\kappa(Y,K)=-\infty$, and $K^4=0$;
\item $q(Y)=0$ and the nef dimension of $K$ is four;
\item for some integer $\iota>0$, $\iota K$ is Cartier and
\begin{equation}
 K\cdot C\ge \frac1\iota
\end{equation}
for every integral curve $C$ through a point of a fixed very general
locus in $Y$.
\end{enumerate}

\label[proposition]{prop:scalar-orders}
For all sufficiently small positive rational \(t\), a very general
point \(x\in Y_{\mathrm{sm}}\) has the following property. For every
positive integer \(k\) for which \(kP_{\mathrm s}\) is Cartier and every
nonzero section
\(s\in H^0(Y,\cO_Y(kP_{\mathrm s}))\), one has
\begin{equation}
 \ord_x(s)\le4k\rho_t\le32k\epsilon .
\end{equation}

For every fixed bounded Jordan quad $Q=(D;a,b,c,d)$, the annealed
probability of $C_Q$ in fair-colored full-plane Poisson--Voronoi
percolation converges, as $\varepsilon\downarrow0$, to
\begin{equation}
 F(x)=\frac{\displaystyle\int_0^x [u(1-u)]^{-2/3}\,du}
 {\displaystyle\int_0^1 [u(1-u)]^{-2/3}\,du},

\end{equation}
where a conformal map from $D$ to the upper half-plane sends
$(a,b,c,d)$ to $(0,x,1,\infty)$.

Partition $X$ into $b$ nonempty sets $M_1,\ldots,M_b$. Put $H_i=H_{M_i}$. Suppose $f$ is a nonnegative measure on $G$ of mass at most one and, for every $g\in G$ and $i$,
\begin{equation}
 f(gH_i)\le \frac{B}{[G:H_i]}.
\end{equation}
For every $u>0$ and every irreducible $\rho$ of degree $D$,
\begin{equation}
 \|\widehat f(\rho)\|_{\HS}^2
 \le bBC_uD^{-1+(u+2)/b}.
\end{equation}
There is also an independent orbit-span proof of the bound
\begin{equation}
 \|\widehat f(\rho)\|_{\op}^2
 \le bBC_uD^{-1+(u+2)/b}.
\end{equation}
No restriction is imposed on block sizes or on the multiplicities in $\rho|_{H_1\times\cdots\times H_b}$.

For the disjoint-block data of this section and every $u>0$,
\begin{align}
 \|\widehat f(\rho)\|_{\HS}^2&\le B^2bC_uD^{-1+(u+2)/b},\\
 \|\widehat f(\rho)\|_{\HS}^2&\le B^2bC_uD^{-1+(u+4)/b}.
\end{align}

For every fixed real $u>0$,
\begin{equation}
 C_u:=\sup_{n\ge1}\sum_{\lambda\vdash n}D_\lambda^{-u}<\infty,
 \qquad Z_u(n)\longrightarrow0.
\end{equation}
Moreover there are absolute constants $c_1,c_2>0$ such that, for all
sufficiently large $n$ and every $\lambda\vdash n$,
\begin{equation}
 D_\lambda\ge c_1e^{c_2k(\lambda)}.
\end{equation}
For each fixed positive $k$, these dimensions tend uniformly to infinity
among shapes with $k(\lambda)=k$.

Let $f\ge0$ be a mass function on $S_n$, of total mass $z\le1$,
such that $f(gH_i)\le B/[S_n:H_i]$ for every $g,i$.  With
$K_\lambda$ as in \eqref{l:joint-decomposition},
\begin{equation}
 \|\widehat f(\lambda)\|_{\op}
       \le\sqrt{BzK_\lambda}\,D_\lambda^{-1/2+1/b}.
\end{equation}

Let $H_1,\ldots,H_b$ be the disjoint symmetric block subgroups
above.  Let $\alpha,\beta\ge0$ have masses $a,c\le1$ and satisfy
\begin{equation}
 \alpha(H_i g)\le\frac{B_L}{[S_n:H_i]},\qquad
 \beta(gH_i)\le\frac{B_R}{[S_n:H_i]}
       \quad(g\in S_n,\ 1\le i\le b).
\end{equation}
Then every irreducible $\lambda\vdash n$ satisfies
\begin{equation}
 D_\lambda\|\widehat\beta(\lambda)
                     \widehat\alpha(\lambda)\|_{\HS}^2
 \le B_LB_Rac\,K_\lambda^2D_\lambda^{-1+4/b}.
\end{equation}
In particular, for eight blocks and $B_L=B_R=2$, the bound is
$4K_\lambda^2D_\lambda^{-1/2}$.

Let $128$ divide $n$, let $\mathcal G\in\mathcal F$, and suppose
$a=\mathbb P(\mathcal G)>0$. Assume that \emph{every} probability
law $\sigma$ on $(\Omega,\mathcal F)$ supported on $\mathcal G$
($\sigma(\mathcal G)=1$)
satisfies
\begin{equation}
 D(\sigma\|\mathbb P)\ge
 \E_{X:\,|X|=n-n/128}D(\sigma_X\|U_X)-n^{-2}.

\end{equation}
There is an absolute $C$ such that, for every irreducible unitary
representation $\rho$ of $S_n$ of degree $D$ and all unit vectors $u,z$,
\begin{equation}
 \mathbb P\{\mathcal G,
       |\langle z,\rho(g)u\rangle|\ge D^{-1/8}\}
 \le CD^{-1/256}.

\end{equation}
If $\eta$ is the endpoint law conditioned on $\mathcal G$, then
\begin{equation}
 \|\widehat\eta(\rho)\|_{\op}
 \le D^{-1/8}+\frac C aD^{-1/256}.

\end{equation}
In particular, when $a\ge1/2$, this is at most $C'D^{-1/256}$
for an absolute $C'$. The statement therefore applies uniformly to a
sequence with $\mathbb P(\mathcal G)=1-o(1)$.

Let $\nu$ be any probability on $S_n$ satisfying the sixteen coset
caps in \eqref{l:forest-caps}.  Uniformly over all partitions with
\[
 k=n-\lambda_1>n^{1/20},\qquad \lambda'_1\le n/2,
\]
one has, for sufficiently large $n$,
\begin{equation}
 \|\widehat\nu(\lambda)\|_{\mathrm{op}}
 \le D_\lambda^{-1/3}.

\end{equation}

If $P$ is not generated by its global sections at $x$, then
\begin{equation}

 \liminf_{j\longrightarrow\infty}
   \frac{1}{jN_j}\sum_{\gamma\in H_j}|\gamma|_1
       >\frac{n}{n+1}.
\end{equation}

Let $\gamma\in\mathcal U$ minimize $\mathcal P$, and let $X$ be its
controlled diffusion. Then $\gamma(0)=0$ and $\gamma$ is smooth on
$[0,1)$, with derivatives at zero understood from the right. Moreover,
\begin{equation}
 \gamma(t)=
 \frac{\E[\Phi_{\gamma,xxx}(t,X_t)^2]}
      {2\E[\Phi_{\gamma,xx}(t,X_t)^3]},
 \qquad 0\leq t<1.
\end{equation}
Consequently $\mu_\gamma(\dd t)=\gamma'(t)\,\dd t$ on $[0,1)$,
where $\gamma'$ is smooth and nonnegative. In fact, for $0<t<1$,
\begin{equation}
 2\gamma'(t)\E[\Phi_{\gamma,xx}(t,X_t)^3]
 \geq \frac{\gamma(t)^2}{1000}
                \E[\Phi_{\gamma,xx}(t,X_t)^4]>0.
\end{equation}
In particular $\gamma'(t)>0$ on $(0,1)$.

Let $\gamma$ be a minimizer, let $X$ be its diffusion, and write
$u=\Phi_{\gamma,x}$ and $a=\Phi_{\gamma,xx}$. There is a bounded
martingale terminal value $U_1$ such that $u(t,X_t)\to U_1$ almost surely
and in $L^2$ as $t\uparrow1$, with $U_1^2=1$ almost surely. Moreover,
\begin{equation}
 \begin{aligned}
 P_*&=\E|X_1|-\int_0^1t\gamma(t)\,\dd t\\
    &=\E[U_1 B_1]
     =\int_0^1\E a(t,X_t)\,\dd t.
 \end{aligned}
\end{equation}
The last integral is finite.

For every fixed $j<\infty$, after reducing the fixed upper scale if needed,
\begin{equation}
 \mathbf E\bigl(\|m_p\|/M_p\bigr)^j
 +\mathbf E\bigl(\|m_p^{\mathrm{sp}}\|/M_p\bigr)^j\le C_j.
\end{equation}
At the smallest scale,
\begin{equation}
 \mathbf E\frac{\|m_r-m_r^{\mathrm{sp}}\|^2}{M_r^2}
 \le Cn^{-1/20},\qquad
 \mathbf E\|\nabla_{u_r}\log L_r\|^4=o(1).
\end{equation}

For Gaussian disorder and every $z>0$,
\begin{equation}
 B_n^{[2]}(z)\longrightarrow0
 \quad\text{in probability}.

\end{equation}

There is a constant $v=v(x)\in(0,\infty)$, depending only on the fixed
weight $x$, such that for every pair of real zero-integral tests
$f,g\in C_c^\infty(\R^2)$,
\begin{align}
 \lim_{\delta\downarrow0}\E[H_\delta(f)H_\delta(g)]
 &=\frac{v}{(2\pi)^2}
       \int_{\R^2}\frac{\widehat f(p)\overline{\widehat g(p)}}{|p|^2}
                  \dd p                                      \\
 &=\frac{v}{2\pi}\iint_{\R^2\times\R^2}
          f(z)\log\frac1{|z-w|}\,g(w)\dd z\dd w.              \notag
\end{align}
The conclusion also holds for zero-integral tests converging in
$C_c^\infty$ with a common compact support.

Fix a finite regular grid as in Definition~\ref{def:brackets}.
For every $f\in C_c^\infty(D)$, the upper and lower bracket fields
satisfy
\begin{equation}
 \lim_{\epsilon\downarrow0}\ \limsup_{\delta\downarrow0}
 \left|\E H_\delta^{\pm,\epsilon}(f)\right|=0.

\end{equation}

In \eqref{eq:limit-puncture},
\begin{equation}
              L(y,\mathbf z)=\frac{v}{2\pi}T_{j-2}(\mathbf z).

\end{equation}
The convention \(T_0=1\) applies when \(j=2\).

For every fixed $C\geq3$ there is $\delta=\delta(x,C)>0$ such that,
for all sufficiently large $n$,
\begin{equation}
 P_Y\bigl(\mathsf H_Y^+([-2n,2n]\times[3n,4n])\bigr)\geq\delta
\end{equation}
on the mixed cylinder $\mathrm{Cyl}_{Cn,5n}$ of
\cite[Appendix~A]{GL2025}, with the same lattice rounding convention.

