statements.text:
For each $v\in(0,|B|)$ there is a minimizer $E$ in
\eqref{eq:confined-profile}.  It has a regular representative for which
$\Gamma=\partial E$ is the support of its perimeter measure and is
contained in $\overline B$.  There is a compact set $S\subset B$ such
that
\begin{enumerate}
 \item $\dim_{\mathcal H}S\le n-8$, with $S=\varnothing$ if $n<8$;
 \item $\Sigma=\Gamma\setminus S$ is a boundaryless
 $C^{1,1}_{\mathrm{loc}}$ hypersurface, smooth on $\Sigma\cap B$;
 \item $\Gamma$ is $C^{1,1}$ in an ambient neighborhood of
 $\partial B$, and $S$ is disjoint from a collar of $\partial B$;
 \item with $d\sigma$ denoting area on $\Sigma$, for every Borel set
 $A\subset M$ one has
 \begin{equation}

  |D\chi_E|(A)=\int_{A\cap\Sigma}d\sigma,
  \qquad P(E)=\int_\Sigma d\sigma=I(v).
 \end{equation}
\end{enumerate}
The unit normal on $\Sigma$ is the outward normal of $E$.

For almost every $v\in(0,\vol(B))$,
\begin{equation}

 I'(v)\ge m\sqrt{b^2+\left(\frac{s_m}{I(v)}\right)^{2/m}}.
\end{equation}

For the updates $G_e$ on $D$, the languages
$\widetilde P_x,\widetilde Q_y$ satisfy:
\begin{enumerate}
\item on a word in $D^*$, every match of
      $\widetilde P_x\widetilde Q_y$ from its beginning consumes
      exactly the first episode $e$ and has $G_e(x)=y$;
\item every $e\in D$ admits such a split for every input $x\in U$.
\end{enumerate}
Thus this split has empty skip domain.

For full nonrelativistic Coulomb atoms with two electron spin states,
\begin{equation}
 \frac{I_m(Z)}{m^{7/3}}\longrightarrow a_{\TF}>0
 \quad\text{whenever}\quad m\longrightarrow\infty,
 \qquad \frac Zm\longrightarrow\infty,
\end{equation}
where $Z>m\ge1$ are integers. In particular,
\begin{align}
 \lim_{m\to\infty}
  \frac{\limsup_{Z\to\infty} I_m(Z)}{m^{7/3}}
   &=a_{\TF},\\
 \lim_{m\to\infty}
  \frac{\liminf_{Z\to\infty} I_m(Z)}{m^{7/3}}
   &=a_{\TF}.
\end{align}
The inner limits are taken over integer $Z$ with $m$ fixed. No convergence
of $I_m(Z)$ at a fixed $m$ is asserted or assumed.

Let $q$ be the deficit coefficient in \cref{thm:priced-deficit}.  For every
sequence of integers $Z>m\ge1$ such that $m\to\infty$ and $Z/m\to\infty$,
\begin{equation}
 \frac{E_Z(Z-m)-E_Z(Z)}{m^{7/3}}
       \longrightarrow\frac37q^{-4/3}.
\end{equation}

Set $b_{\mathrm{TF}}=(81\pi^2/2)^{1/3}$.  For every choice of normalized
neutral ground states $(\Psi_Z)_{Z\ge1}$ of \eqref{intro:hamiltonian},
\begin{align}
 \lim_{m\to\infty}m^{1/3}
       \left[\limsup_{\substack{Z\to\infty\\ Z>m}}R_m(\Psi_Z)\right]
       &=b_{\mathrm{TF}},\\
 \lim_{m\to\infty}m^{1/3}
       \left[\liminf_{\substack{Z\to\infty\\ Z>m}}R_m(\Psi_Z)\right]
       &=b_{\mathrm{TF}}.
\end{align}
All limits are over integers.  The inner limits hold $m$ fixed; no
convergence in $Z$ at a fixed $m$ is assumed.

There are constants $D_0,Z_0<\infty$ such that every normalized neutral
ground state with $Z\ge Z_0$ has offset at most $D_0$.
For every fixed $0<\alpha<\beta<\infty$ and every $u>0$, its raw
electron configuration satisfies
\begin{equation}
 \begin{aligned}
 \left\|\#\{i:\alpha u<|x_i|<\beta u\}\right\|_{L^2(\Prob)}
 &\le C_{\alpha,\beta}
       \bigl(\max\{u^{-3},1\}+\sqrt{D_0u}\bigr),\\
 \E\#\{i:|x_i|>1\}&\le C(1+\sqrt{D_0}).
 \end{aligned}
\end{equation}

There is a universal $C_{\mathrm{cap}}$ with the following property.
Fix $L_1\ge2$, $0<h_l<h_h<\infty$, and $0<\xi<h_l/16$.
For all sufficiently small $s>0$, depending on these parameters and
$D_0$, and each $j<J$, there is an event in $\mathcal F_j$ whose
complement has probability at most $Cr_j^{25}$, on which, simultaneously
for $r_j\le |y|\le4L_1r_j$ and $h_l\le h\le h_h$,
\begin{equation}
 \begin{gathered}
 H_j(y)\le C_{\mathrm{cap}}|y|^{-4},\\
 |y|^6\mu_j(y)>kh^{3/2}
       \quad\Longrightarrow\quad |y|^4H_j(y)\ge h-\xi,\\
 |y|^6\mu_j(y)<kh^{3/2}
       \quad\Longrightarrow\quad |y|^4H_j(y)\le h+\xi.
 \end{gathered}
\end{equation}
The probability constant may depend on the fixed comparison
parameters, but $C_{\mathrm{cap}}$ does not.
The estimates are uniform in $Z$, the ground state, $j$, and $J$.

There are deterministic integers $q_\ell\to\infty$ and $j_\ell<J_\ell$,
and events $G_\ell\in\mathcal F_{j_\ell}$ with
$\Prob(G_\ell)\to1$, such that
\begin{equation}
 a_\ell:=\frac{r_{j_\ell}}{s_\ell}
 \in\left[\frac1{2q_\ell},\frac1{q_\ell}\right].

\end{equation}
Put $\lambda_\ell=Z_\ell s_\ell^3$ and, on each retained datum, define
\begin{equation}
 \begin{aligned}
 F_\ell(x)&=s_\ell^4H_{j_\ell}(s_\ell x),&
 \sigma_\ell(x)&=s_\ell^6\mu_{j_\ell}(s_\ell x),\\
 U_\ell(x)&=s_\ell^4u_{j_\ell}(s_\ell x),&
 p_\ell(x)&=s_\ell^6p_{j_\ell}(s_\ell x).
 \end{aligned}

\end{equation}
These fields satisfy the exact identities
\begin{equation}
 \begin{gathered}
 \sigma_\ell\ge0,\qquad \int_{\R^3}\sigma_\ell\,\dd x=\lambda_\ell,
 \qquad F_\ell=\lambda_\ell K-K*\sigma_\ell,\\
 \Delta F_\ell=-4\pi\lambda_\ell\delta_0+4\pi\sigma_\ell,
 \end{gathered}

\end{equation}
and, simultaneously on $a_\ell\le|x|\le q_\ell$,
\begin{equation}
 F_\ell(x)\le C_{\mathrm{cap}}|x|^{-4},\qquad
 \bigl|\sigma_\ell(x)-k(F_\ell(x)_+)^{3/2}\bigr|
 \le q_\ell^{-8}|x|^{-6}.

\end{equation}
The scaled subsolution obeys, in distributions on $\R^3$,
\begin{equation}
 \Delta U_\ell\ge
 -4\pi\lambda_\ell\delta_0
 +4\pi\mathbf1_{\{|x|<a_\ell\}}\sigma_\ell
 -4\pi p_\ell
 +\mathbf1_{\{|x|\ge a_\ell\}}f(U_\ell),

\end{equation}
with
\begin{equation}
 B|x|^{-4}\left(1-\frac{a_\ell}{8|x|}\right)
 \le U_\ell(x)\le C_{\mathrm{inv}}|x|^{-4}
 \qquad (|x|\ge a_\ell),

\end{equation}
and
\begin{equation}
 p_\ell\ge0,\qquad
 \operatorname{supp}p_\ell\subset\{|x|\le a_\ell\},\qquad
 \int_{\R^3}p_\ell\,\dd x\le s_\ell^3.

\end{equation}
For each finite system, $\sigma_\ell$ is a bounded smooth density,
$p_\ell$ is a bounded density, and both
$F_\ell-\lambda_\ell K$ and $U_\ell-\lambda_\ell K$ extend continuously
and locally Lipschitz through the origin.  All these assertions hold for every
datum in $G_\ell$, so they may be used along arbitrary selections of retained
data.

Along every admissible sequence, with arbitrary normalized neutral
ground states, for each fixed $a>0$,
\begin{equation}
 s_\ell^3\int_{|y|>as_\ell}\rho_{\Psi_\ell}(y)\dd y
       \longrightarrow \frac{b_{\mathrm{TF}}^3}{a^3}.
\end{equation}

Fix any finite list of output derivative orders, including an
exterior base buffer $N_b$.  For every fixed $\zeta>0$ and every
subsequently prescribed inverse accuracy $M_1$, sufficiently high
finite transport and Taylor orders yield a real interior tensor
$h_T^p$ and a real exterior tensor $h_T^B$ with the following
properties.  Put
\begin{equation}
       A_T=e^{-\alpha T},\qquad \alpha=7\kappa/8,
       \qquad\lambda_T=e^{\zeta T}.
\end{equation}
The interior field has the form
\begin{equation}
 h_T^p=A_T\operatorname{tr.rev.}_g\operatorname{Re}
       \left(e^{i\lambda_Tv}\sum_{j=0}^{J}\lambda_T^{-j}p_j\right).
\end{equation}
Every fixed normalized coefficient jet of $p_j$ is $e^{o(T)}$.
The field is supported in a fixed-width neighborhood of $v=T$,
with angular support in the transported launch patch.  Its relative
array $q_T=(h_T^p(\hat e_\alpha,\hat e_\beta))$ satisfies
\begin{equation}
              \|q_T\|_{C^N(\mathcal D_T)}
                    \le A_T\lambda_T^N e^{o(T)}
\end{equation}
at each specified order.  The tensor $p_0$ is trace-free and
$p_0(L_0,\cdot)=0$.  There is a purely angular $\gamma$-unit vector
$X$ at $p_T$ for which
\begin{equation}
 \sigma_T:=\left|\operatorname{Re}
        \bigl(e^{i\lambda_TT}p_0(X,X)\bigr)\right|
\end{equation}
has two-sided subexponential size.  The $a$-scaled linear wave
residual and $\sqrt a$-scaled linear gauge residual, in normalized
slots and with all prescribed ordinary derivatives, are bounded
by $A_T\lambda_T^{-M_1}e^{o(T)}$.

In regular exterior lab components,
\begin{equation}
 \|h_T^B\|_{C^{N_b}}\le A_T\lambda_T^{N_b+3/2}e^{o(T)}.
\end{equation}
Its linear wave and gauge residuals, and its difference from
$h_T^p$ on the entry collar, have size
$A_T\lambda_T^{-M_1}e^{o(T)}$ at all the prescribed finite orders.
The latter assertion includes normal spacetime jets.  On the
original bridge its support lies in Equation~\eqref{bg:arrival-shell}
with arbitrarily thin tube margins.  Increasing $M_1$ and the
finite formal degrees does not increase the positive frequency
powers in Equations~\eqref{bg:packet-size} and
\eqref{bg:beam-estimates}.  Thresholds and subexponential constants
may depend on those degrees.

Fix \(0<\delta<\kappa/32\) and the prescribed finite data seminorm.
Use Proposition~\ref{bg:packet} and Proposition~\ref{prep:signed-entry}
with sufficiently high fixed orders, sufficiently small losses and late
support parameter, and sufficiently accurate linear residuals. For
sufficiently small fixed \(\zeta>0\) and sufficiently large \(T\), the
two entry data have smooth vacuum evolutions \(g_T^\pm\) on the strict
domain \eqref{energy:domain}, in wave-map gauge with target \(g\).
Let \(H_T^\pm\) be the relative arrays of \(g_T^\pm-g\), and put
\[
 F_T^\pm=H_T^\pm\mp q_T,\qquad
 F_T^{\mathrm{odd}}=F_T^+-F_T^-.
\]
Then
\begin{equation}
 \begin{aligned}
 \lVert F_T^\pm\rVert_{C^{30}_{\mathrm{mix}}(\Omega_T)}
   &\le e^{(\kappa-2\alpha+\delta)T},\\
 \lVert F_T^{\mathrm{odd}}\rVert_{C^2_{\mathrm{mix}}(\Omega_T)}
   &\le e^{(\kappa-3\alpha+\delta)T}
            +e^{(2\kappa-4\alpha+\delta)T}.
 \end{aligned}
\end{equation}
The exact changes and all three error fields have support in
\(v\ge(1-\nu_0)T-o(1)\). The time slices remain spacelike and the two
moving side faces remain strict future exits. Moreover, for some
\(c>0\),
\begin{equation}
 \lVert H_T^\pm\rVert_{C^{30}_{\mathrm{mix}}}
       \le e^{-(\kappa/2+c)T},\qquad
 e^{o(T)}\left(\lVert F_T^{\mathrm{odd}}\rVert_{C^2_{\mathrm{mix}}}
          +\sum_\pm\lVert H_T^\pm\rVert_{C^2_{\mathrm{mix}}}^2\right)
       =o(A_T).
\end{equation}
Here every subexponential factor is at a fixed finite order. No higher
seminorm of the fixed smooth background is required to be small.

For every $d\in\Ueps$, the comparison geometry has the following
properties.
\begin{enumerate}[label=\textup{(\roman*)}]
\item The metrics $\gamma^{\pm1}$ and $\mathcal A^{\pm1}$ are
bounded in angular $H^6$, and $\xi_i,a^{-1}\partial_vb$ are
bounded in angular $H^5$. There are nonnegative measurable functions
$g_i:\R\to[0,\infty)$ with
\begin{equation}
 \sum_{n\in\Z}\sup_{[n,n+1]}g_i<\infty
\end{equation}
such that
\begin{equation}
 \norm{\chi_i}_{H^4}+\norm{\ell_i+\kappa}_{H^4}
       +\norm{B_i}_{H^5}
 \le C\bigl(q+g_i(y_i)\bigr).
\end{equation}
The corresponding first pure longitudinal derivatives
$\mathfrak L_i\chi_i,L_i\ell_i$, and $\partial_u b$ in direction
$0$, have directional summable bounds through angular $H^2$,
after enlarging the $g_i$.
\item The first ordinary longitudinal jets satisfy
\begin{equation}
\begin{gathered}
 \norm b_{H^5}+\sum_i\norm{(\chi_i,\ell_i+\kappa)}_{H^4}\to0,\\
 \sum_{k=0}^1\left(\norm{\partial_{y_k}b}_{H^2}
       +\sum_i\norm{\partial_{y_k}(\chi_i,\ell_i)}_{H^2}\right)\to0,\\
 \sum_{k=0}^1\left(\norm{\partial_{y_k}\gamma}_{H^4}
       +\norm{\partial_{y_k}\log a+\kappa}_{H^4}\right)\to0
\end{gathered}
\end{equation}
as $t\to\infty$ and $|u|,|v|\to\infty$. The displayed norms
are bounded everywhere in the wedge.
\item For fixed $U\in\R$, $C>0$, and each fixed ordinary
coordinate derivative order, the fields
\begin{equation}
 \gamma^{\pm1},\quad\log\mathcal A,\quad b,
       \quad a^{-1}\partial_vb
\end{equation}
have $e^{o(T)}$ bounds on
\begin{equation}
 u\le U,\qquad v\le CT,\qquad t\ge0.
\end{equation}
The assertion holds for either optical ordering and on restricted
coordinate-path segments. Fixed derivatives of $a$, $\sqrt a$,
and $\partial_vb$ retain respectively the factors $a$, $\sqrt a$,
and $a$, with subexponential coefficient bounds.
\end{enumerate}

For every $\eta_2>0$, the input loss $\eta$ and the support fraction
$\nu$ may be chosen sufficiently small, with the finite base orders
fixed, so that on every existing bootstrap subslab
\begin{equation}
 \sup_{0\le t\le L_T}
 \| (\Delta\gamma,\Delta\log\mathcal A,\Delta b,
                   \Delta\chi_i,\Delta\ell_i,\Delta\xi_i)
                         \|_{L^2(I_T(t)\times\Sph)}
 \le \amp^2e^{\eta_2T}.
\end{equation}
The supremum is restricted to available slices. At the same times,
\begin{equation}
 \sum_i\|Y_i+Z_i+z_i\|_{L^2(I_T(t))}
 +\|(\nabla\Delta\gamma,\nabla\Delta b)
                  \|_{L^2(I_T(t)\times\Sph)}
 \le \amp^2e^{\eta_2T}.
\end{equation}

For every \(U,V\in\mathcal G\) and every nonnegative compactly
supported Lipschitz \(f\),
\begin{equation}

 R(U,V,V,U)(f)\geq\kappa\int f|U\wedge V|^2.
\end{equation}

There are morphisms
\begin{equation}
 \lambda_i:[\Spec R/A]\longrightarrow[Y_i/H_i^\natural]
\end{equation}
whose field-valued images have unipotent residual holonomy and a vector
in $E_i$ outside its open $H_i$-orbit.  For every $n\geq1$, the product
morphism $\lambda=(\lambda_1,\ldots,\lambda_n)$ is affine.  Write $R_n$
for the $H^\natural$-equivariant $B$-algebra representing
$\lambda_*\cO$ on $Y$.  There is an equivariant $B$-module map
\begin{equation}
 R_n\longrightarrow H^0(F_n^{\mathrm{qc}})
\end{equation}
that sends $1$ to the class of $f$ in the spherical summand.  In
particular, the composite
\begin{equation}
 B\longrightarrow R_n\longrightarrow H^0(F_n^{\mathrm{qc}})
       \longrightarrow F_n^{\mathrm{qc}}
\end{equation}
is the section defined by $f$.

Let $B$ be a bounded ball. For $U\in C_c^\infty(B;\C^4)$ and all
sufficiently small $h>0$,
\begin{equation}

 \norm{E_\tau^{-1}U}_{H_h^1}
 \le Ch\norm{E_\tau^{-1}\Lcal U}_{H_h^{-1}}.
\end{equation}

For the same $B$ and $\theta$, and all sufficiently large $\tau$,
every $w\in C_c^\infty(B;\C^3)$
satisfies
\begin{equation}

