       \left\{\mathcal S(p)+\frac12\int_0^1q(s)p(s)\,\dd s\right\}\\
 &=\frac12\left\{\log(1-q_*)+
                       \int_0^{q_*}\frac{\dd t}{\chi_q(t)}\right\},
 \qquad \chi_q(t)=\int_t^1m_q(v)\,\dd v.
 \end{split}

