$\|x\pm y\|\le R$, one has
\begin{equation}
 \|Q_Hy\|\le(\sqrt2+\sqrt6)\sqrt{R(R-\|x\|)}.
\end{equation}

Let $A$ be a finite random represented atom, and let $\nu$ be a real
random variable on the same probability space with $|\nu|\le1$.
Set $x=\mathbb EA$, $u=\mathbb E(\nu A)$,
$\delta=1-x(p)$, and $\eta=\|Q_Hx\|$.  Then
\begin{equation}
 \|Q_Hu\|
 \le\sqrt{(\eta+\sqrt{2\delta})^2+4\delta}+\sqrt{2\delta}
 \le\eta+(2+2\sqrt2)\sqrt\delta.
\end{equation}
Consequently, whenever $x,u\in Z$ satisfy $x\pm u\in B_Z$,
\begin{equation}
 \|Q_Hu\|\le\|Q_Hx\|+(2+2\sqrt2)\sqrt{1-x(p)}.
\end{equation}

Let $z_+,z_-\in B_Z$.  If $z=(z_++z_-)/2$ is supported on $H$
and $\|z\|\ge1-\varepsilon$, where $0<\varepsilon<1$, then
\begin{equation}
 \|Q_Hz_\pm\|\le(2+2\sqrt6)\sqrt\varepsilon.
\end{equation}
More generally, let $R>0$, $d\ge0$, and $h_+,h_-\in Z$ satisfy
$\|h_\pm\|\le R$, with $h_++h_-$ supported on $H$.
If a common head test $p$, $\rho(p)=1$, satisfies
$h_\pm(p)\ge(1-d)R$, then
\begin{equation}
 \|Q_Hh_\pm\|\le R(2\sqrt{6d}+\sqrt{2d}).
\end{equation}

Let $z_1,z_2\in B_Z$, $z=(z_1+z_2)/2$, and let $H$ be finite
ancestral.  For a head test $p$, put $\delta=1-z(p)$ and
$\kappa=\|(z(e_g))_{g\in G_H}\|_2$.  Then
\begin{equation}
 \|Q_Hz_i\|\le2\kappa+(6\sqrt2+6)\sqrt\delta.
\end{equation}
In particular, choosing a norming head test gives
\begin{equation}
 \|Q_Hz_i\|
 \le2\|Q_Hz\|+(6\sqrt2+6)\sqrt{1-\|P_Hz\|}
 \le2\|Q_Hz\|+15\sqrt{1-\|P_Hz\|}.
\end{equation}

Let $\delta>0$ and $x\in X$ satisfy $\|x\|=1$. There are a finite
ancestral head $H$ and a test $p=P_Hp\in J$ such that
\begin{equation}
 \rho(p)\le1,\qquad x(p)\ge1-\delta,\qquad
 \|Q_Hx\|\le\delta.
\end{equation}
For this same head and every $y\in X$ satisfying
$\|x+y\|,\|x-y\|\le1+\delta$, put $h=6\delta+\delta^2$. Then
\begin{equation}
 \max\{\|Q_H(x+y)\|,\|Q_H(x-y)\|,\|Q_Hy\|\}
 \le F(\delta):=
 \delta+\sqrt{2h}+2\sqrt{(2\delta+\sqrt h)^2+2h}.
\end{equation}
In particular, for every $\varepsilon>0$ one can choose $\delta>0$
independently of $x$ so that this head satisfies
$\|Q_Hy\|<\varepsilon$ for every such $y$.

If $x=P_Hx$ has norm one, $P_Hy=0$, and $\|x\pm y\|\le R$
for $R\ge1$, then
\begin{equation}
 \|y\|\le(\sqrt{12}+2\sqrt2)\sqrt{R(R-1)}.
\end{equation}

Let $H$ be finite and ancestral, $x=P_Hx$ have norm one, and
$P_Hy=0$. For $d>0$, the assumptions $\|x\pm y\|\le1+d$ imply
\begin{equation}
 \|y\|\le(1+d)(7\sqrt2+4)\sqrt d.
\end{equation}
In particular, $\|y\|\le32\sqrt d$ when $0<d\le1$.

For $0<\lambda<1$ and $x\in B_X$ with $\|x\|\ge1-\lambda$,
there is a finite ancestral set $H$, depending only on $x$ and
$\lambda$, such that every $y\in X$ with $x\pm y\in B_X$ satisfies
\begin{equation}
 \|Q_Hy\|\le G_{\mathrm{orig}}(\lambda)
 :=\lambda+2\sqrt{6\lambda}
 +2\sqrt{(2\lambda+\sqrt{6\lambda})^2
                  +12\lambda+4\sqrt{6\lambda}}.
\end{equation}
In particular $G_{\mathrm{orig}}(\lambda)\to0$ as $\lambda\downarrow0$.

For $0<t<1$, set $\delta=(t/25)^2$. If $x_0=P_Hx_0$ and $y$
are unit vectors, $P_Hy=0$, and both are finitely supported, then
\begin{equation}
 \max\{\|x_0+ty\|,\|x_0-ty\|\}>1+\delta.
\end{equation}
For general unit $y\in\ker P_H$, the same inequality holds with
$\ge$ in place of $>$. Moreover,
\begin{equation}
 \widehat\delta_Z(t)\ge t^2/2500.
\end{equation}

Suppose \(Px=x\), \(Qy=y\), and \(\|x\pm y\|\le1\).  Then
\begin{equation}
 \|y\|\le(2\sqrt2+2\sqrt6)\sqrt{1-\|x\|}
                         \le8\sqrt{1-\|x\|}.
\end{equation}
Consequently, if \(\|p\pm u_j\|\le1\) and
\(\|u_i-u_j\|\ge\varepsilon>0\) for all distinct \(i,j\) in an
infinite sequence, then
\begin{equation}
 \|p\|\le1-\varepsilon^2/256.
\end{equation}

Let $H$ be finite and ancestral, $x=P_Hx$ with $\|x\|=1$, and
$u\in\ker P_H$. For every $L>1$,
\begin{equation}
 \max\{\|x+u\|,\|x-u\|\}<L
 \quad\Longrightarrow\quad
 \|u\|\le
 3\left(\sqrt{L^2-1}
            +2\sqrt{\frac{1-L^{-2}}2}\right).
\end{equation}

In the forest space $X$, let $h=P_Hh$, $P_Hu=0$, and
$h+u,h-u\in B_X$.  Then
\begin{equation}
 \|u\|\le3(\sqrt2+2)\sqrt{1-\|h\|}.
\end{equation}

For the preceding choices, every nonzero homogeneous $h_I\in R_I$ of
positive degree satisfies
\begin{equation}
 \lct_o(C_0;h_I)\geq\frac{1}{2n(I/a)}.
\end{equation}
Every nonzero regular local function $g$ on $V$ and every divisorial or
real quasi-monomial valuation $w$ centred at $o$ satisfy
\begin{equation}
 w(g)\leq 2n A_{\theta_V}(w)\,v(g).
\end{equation}
Moreover, for every valuation $w$ centred at $o$,
\begin{equation}
 w(g)\geq s(w)v(g)\quad(g\in\cO_{V,o}),
 \qquad s(w)=\min_i\frac{w(h_i)}{v(h_i)}.
\end{equation}
In particular each positive normalized homogeneous degree is at least
$1/(2n)$.

After passage to a subsequence there is a uniform constant $C$ such that
\begin{equation}
 h\,d_1\cdots d_n\leq C,
 \qquad h=\vol(v).
\end{equation}

For every parameter map allowed above and every nonzero
divisorial base valuation \(u\), the barred reference
discrepancy is
\begin{equation}
 \bar A_\sigma(u)=A_\zeta(u)+\mu(b).
 \tag{T}
\end{equation}
For a divisorial \(w\) over \(u\), with labelled monomial
retraction \(w_x\), there is an excess satisfying
\begin{equation}
 A_\sigma(w)=A_\zeta(u)+\phi(x)+E(w),\qquad
 E(w)\ge0,\qquad E(w_x)=0.
 \tag{TE}
\end{equation}
Let \(\omega\) be any other form with effective boundary
on \(G\), and compare it to \(\sigma\) at a common tensor
index \(p\), writing
\[
 A_\omega(v)=A_\sigma(v)+\frac{v(H)}p.
\]
There is a uniform constant \(C_2\) such that
\begin{equation}
 \begin{split}
 |w(H)-w_x(H)|&\le C_2pE(w),\\
 |w_x(H)-w_{x'}(H)|&\le C_2p\|x-x'\|.
 \end{split}
 \tag{TV}
\end{equation}
The second inequality holds along every segment in one
labelled slice cell, including incident endpoints, in
fixed cone coordinates.  The rational monomial valuations
in these assertions are the compatible algebraic labelled
ray orders constructed above.  Formulae \eqref{trait:T}
and \eqref{trait:TE} do not require absolute log
canonicity of \(\sigma\).

Under the hypotheses of Theorem~\ref{main:theorem}, the same
\(\mathbb Q\)-factorial terminal endpoint \(Y\) has semiample \(K_Y\);
hence \(Y\) is a good minimal model of \(X\).

Assume \eqref{num:approximation}.  If, for one very ample Cartier
divisor \(H\) on \(Y\),
\begin{equation}
L^2\cdot H^{n-2}=0,
\end{equation}
then \(L\) is nef.

For every place $v_0\mid 3p$ of $K$, there is a nonempty open subset
$\Omega_{v_0}\subset U(K_{v_0})$ with the following property.
Suppose that $t\in U(K)$ belongs to $\Omega_{v_0}$ for all $v_0\mid3p$,
and set $J_t=\Jac(C_{n,t})$.  At each place $v\mid3p$ of $F$,
$J_t$ has the same one of the following potential reduction types
as $E^n$:
\begin{enumerate}
\item good ordinary reduction;
\item good reduction with all Newton slopes $1/2$;
\item semistable reduction of toric rank $n$.
\end{enumerate}
For each $v$, the extensions giving these properties may be chosen
in advance, independently of $t$ in the indicated open subsets.

Under the hypotheses of Lemma~\ref{lem:adapted-factorization}, retain the
subsequence and its data.  Define probability measures
\begin{equation}
 m_{\beta,r}^{[q]}
 =\text{Haar image on }
 h(\beta)^{\mathrm{diag}} C^q(H_\bullet)
 \sigma_r^{\mathrm{diag}}\Lambda^{\{0,1\}^q}/
              \Lambda^{\{0,1\}^q}.

\end{equation}
The empirical point laws satisfy
\begin{equation}
 \frac1{\lfloor L\rfloor}\sum_{0\leq b<\lfloor L\rfloor}
       \delta_{P_L(b)\Lambda}
 \ \Longrightarrow
 \frac1{d_0}\sum_{r=0}^{d_0-1}\int_0^1 m_{\beta,r}^{[0]}\,d\beta.

\end{equation}
For every fixed cube dimension $q$, every $\beta\in(0,1)$, every residue
$r\bmod d_0$, and every bounded Lipschitz test $F$ on
$(K/\Lambda)^{\{0,1\}^q}$,
\begin{equation}
 \lim_{\alpha\downarrow0}\limsup_{L\to\infty}
 \left|
 \E_{\substack{b_0/L\in[\beta,\beta+\alpha),\ b_0\equiv r\ (d_0)\\
                 b_j/L\in[0,\alpha),\ b_j\equiv0\ (d_0),\ 1\leq j\leq q}}
 F\bigl((P_L(b_0+\sum_{j=1}^q e_jb_j)\Lambda)_e\bigr)
 -\int F\,dm_{\beta,r}^{[q]}
 \right|=0.

\end{equation}
The inputs in this average are independent and uniform on the specified
integer progressions.  The same assertion holds for boxes with side
lengths between $c\alpha L$ and $C\alpha L$, whose base coordinates
are within $C\alpha L$ of $\beta L$ and whose increments have
absolute value at most $C\alpha L$, where $c,C>0$ are fixed before
either limit.
For fixed bounds the assertions are uniform over the tests and these
boxes.  In particular, arbitrary fixed-modulus progression restrictions
are permitted if the base has residue $r$ and all increments have residue
zero modulo $d_0$.  Every progression modulus is fixed before the
length limit, which always precedes the locality limit.
The same factorization supplies these conclusions for every fixed $q$.

Almost every spectral function on $\mathcal D$ is either $1$ or a
finite Blaschke product with
\begin{equation}
 f(0)=f(\infty)=1,
 \qquad f(\overline w)=\overline{f(w)}.
\end{equation}
There is a spectral vector $\mathsf h$, not necessarily of finite
norm, such that
\begin{equation}
 J(w)\Omega=(1-f(w))\mathsf h.
\end{equation}
The measure $\mu$ given by the squared fiber norm of $\mathsf h$
is invariant under dilation.  On the cross-section of products whose
smallest zero has modulus one, it decomposes as
\begin{equation}
 \mu=\dd s\,\nu(\dd F),\qquad f(w)=F(e^s w),
 \qquad \nu(1)<\infty.
\end{equation}
If $\mathcal W(F)$ is the difference between the largest and smallest
logarithmic zero moduli, and $2n_F$ is the degree, then, for some
$\eta_0>0$,
\begin{equation}
 \nu\{\mathcal W>t\}\le C e^{-2\eta_0t},\qquad
 \int n_F\,\nu(\dd F)<\infty.
\end{equation}
The physical plane height has logarithmic variance.  More precisely,
after an axial symmetry, write a nonzero displacement as $(k,j)$ with
$k\ge1$ and $|j|\le k$.  Then
\begin{equation}
 \begin{split}
 \E\bigl(h(k,j)-h(0,0)\bigr)^2
 &=2\Re\int\bigl(1-f(1)^k f(\pm i)^{|j|}\bigr)\,\mu(\dd f)\\
 &=4\nu(1)\log k+O(1),
 \end{split}
\end{equation}
where the sign agrees with the direction of the second coordinate.
The error is uniform over these displacements.

For the neutral small-charge experiments of
Equation~\eqref{eq:electric-characteristic}, there are $c_1>0$ and
$C<\infty$ such that
\begin{equation}
 |\Delta_2H(z)|\le C n^{Cb}
       \left(1+\min_j|z-u_j|\right)^{-2-c_1}
 \qquad(z\in\Z^2).
\end{equation}
The constants are uniform over the stated geometry and charges.

For the fixed remote experiment there exists $c_*\ne0$ such that
\begin{equation}
 C_e(n)=c_*n^{B_*-x}(1+O(n^{-c_3})).
\end{equation}
In particular this limit holds through all positive integers $n$.

For every real $f\in C_c(D)$,
\begin{equation}
 \lim_{\epsilon\downarrow0}\limsup_{n\to\infty}
 \E\bigl[|X_n(f)-X_{n,\epsilon}(f)|^2\bigr]=0,

\end{equation}
where $\epsilon$ tends to zero through the sequence in
Proposition~\ref{prop:disk-calibration}.  The same approximation holds
for every finite vector of such tests.

For the algebras in \eqref{eq:algebras},
\begin{equation}
 \gamma(M,N)\leq C\|UV-VU\|,
 \qquad
 C:=\sum_{k,m,p,h\in\mathbb Z}
       c_kc_mc_pc_h|m-p|\,|h|<\infty.
\end{equation}
Moreover, for every $g\in G$,
\begin{equation}
 \bigl\|W(\lambda(g)\otimes I_L)W^*
            -\lambda(g)\otimes f(g)\bigr\|
 \leq C\|UV-VU\|.
\end{equation}
The constant is independent of $D,U,V$.

For every sufficiently large integer $m$, the vertex set $V$ in
\eqref{ker:vertices} admits a negative-type semimetric $d$ with the
following properties. Its chart maps $v_s(\theta)$, defined almost
everywhere on $U=(-2,2)^m$, satisfy
\begin{equation}
\left|d(v_s(\theta),v_t(\eta))
-c_*\sqrt m\,|\theta-\eta|\right|\le Cr
\qquad(\theta,\eta\in U)
\end{equation}
whenever the labels are defined, where $r=m^{-8}$.
For labels in the same chart,
\begin{equation}
\|x-x'\|_1=\tau
\quad\Longrightarrow\quad
d((s,x),(s,x'))\le C\tau\frac mN(\log m)^2.
\end{equation}
Moreover,
\begin{equation}
|V|\le\exp(Cm\log m),\qquad
\operatorname{diam}(V,d)\le Cm,
\end{equation}
and, for independent uniform $\theta,\eta\in T=(-1,1)^m$,
\begin{equation}
\E d(v_1(\theta),v_1(\eta))\ge cm.
\end{equation}
Here $N=m^6$, $\tau=m^{-2000}$, and all constants are absolute.

There is a finite constant $C$, depending only on the chart and the weight
law, such that for every lattice edge $e$ and every $H\ge1$,
\begin{equation}
 \EE N_e(H)\le C(H+1).
\end{equation}

Inside $\Out(\Pi)$,
\begin{equation}
 N_{\Out(\Pi)}(\mathsf A)
   =\mathsf A\times\langle\delta\rangle.
\end{equation}

For the cut pieces of Lemma~\ref{for:cuts}, there are a
characteristic-zero field $K$, coordinate blocks
$h_e=(h_{e,1},\ldots,h_{e,N_e})$, and algebraic power-series germs
$F_e(h_e),b_e(h_e)$ over $K$, with $F_e(0)=b_e(0)=0$, as follows.
For each vertex set
\begin{equation}

 \begin{split}
 T_v&=K[t_e:e\in E_+(v)]/(t_e^2:e\in E_+(v)),\\
 \mathcal S_v&=\sum_{e\in E_+(v)}(F_e+t_eb_e)
                  -\sum_{e\in E_-(v)}F_e.
 \end{split}
\end{equation}
There are smooth formal graph parametrizations $M_v(y_v,t)$ in the
incident $h_e$ blocks over $T_v$, centered modulo $(t)$, such that:
\begin{enumerate}
\item their central tangent maps are injective, and the difference map
from the sum of the vertex tangent spaces to the sum of the edge blocks
is an isomorphism;
\item $\mathcal S_v(M_v)=0$;
\item for $L\in\mathcal L_v$, with $I=L\cap E_+(v)$ and
$J=L\cap E_-(v)$,
\begin{equation}

 \left(\prod_{i\in I}t_i\right)
 \left(\prod_{j\in J}b_j\right)(M_v)
 \in\bigl((\partial_h\mathcal S_v)(M_v)\bigr)
       \subset T_v[[y_v]].
\end{equation}
\end{enumerate}
Empty products equal one.  In every parameter ring, only the individual
squares $t_e^2$ vanish; mixed products are retained.  One can take
$K=\mathbb C((\sigma))$.

There exist real scalar functions $\gamma_0,\gamma_1\in
L^\infty(B(0,3);\R)$ and constants $0<c<C<\infty$ such that
\begin{enumerate}[label=\textup{(\roman*)},itemsep=2pt]
\item $c\leq\gamma_j\leq C$ almost everywhere, for $j=0,1$;
\item both conductivities equal $1$ in a neighborhood of the boundary;
\item $\abs{\{x:\gamma_0(x)\ne\gamma_1(x)\}}>0$;
\item $\Lambda_{\gamma_0}=\Lambda_{\gamma_1}$ as bounded operators
from $H^{1/2}(\partial B(0,3))$ to $H^{-1/2}(\partial B(0,3))$.
\end{enumerate}

Let $G$ be an infinite connected locally finite quasi-transitive graph
with $h_V(G)>0$. For Bernoulli bond percolation on $G$,
\begin{equation}
 \nabla_{\pc}(v)\le\norm{T_{\pc}}_{2\to2}^{3}<\infty
 \qquad\text{for every }v\in V.
\end{equation}
For every $v\in V$,
\begin{align}
 \chi_v(p)&\asymp(\pc-p)^{-1} &&(p\uparrow\pc), \\
 \theta_v(p)&\asymp p-\pc &&(p\downarrow\pc), \\
 \Prob_{\pc}(|C_v|\ge n)&\asymp n^{-1/2} &&(n\to\infty), \\
 \Prob_{\pc}\bigl(\operatorname{rad}_{\mathrm{int}}(C_v)\ge n\bigr)
    &\asymp n^{-1} &&(n\to\infty), \\
 \Prob_{\pc}\bigl(\operatorname{rad}_{\mathrm{ext}}(C_v)\ge n\bigr)
    &\asymp n^{-1} &&(n\to\infty). 
\end{align}
Here $n$ tends through positive integers. The comparison constants
and the one-sided neighborhoods of $\pc$ may depend on $G$ and $v$.
Moreover,
\begin{equation}
 \pc(G)<\ptwo(G)\le\pexp(G).
\end{equation}
For each fixed $p\in[0,\ptwo(G))$, there are constants
$0<A_{G,p}<\infty$ and $a_{G,p}>0$ such that
\begin{equation}
 T_p(x,y)\le A_{G,p}e^{-a_{G,p}\dist_G(x,y)}
 \qquad\text{for every }x,y\in V.
\end{equation}

For every $0<\alpha<1/2$,
\begin{equation}
 \sup_{v\in V}\E_{\pc}s_v^\alpha<\infty.

\end{equation}

For every $\eta>0$ there is $C_\eta<\infty$ such that
\begin{equation}
 \chi_{\max}(p)\le C_\eta(\pc-p)^{-1-\eta},
 \qquad 0\le p<\pc.

\end{equation}

For every $\eta>0$ there is $C_\eta<\infty$ such that
\begin{equation}
 a_3(p)\le C_\eta(\pc-p)^{-\eta},
 \qquad \pc/2\le p<\pc.

\end{equation}

For every $t\ge0$,
\begin{equation}
 0\le T_0-T_t\le 2t\,T_0P^kT_0\quad\text{entrywise},\qquad
 m_t\ge m_0-2t\rho^km_0^2.
\end{equation}

Let $A$ be a separable nuclear complex $C^*$-algebra with no nonzero
elementary ideal subquotients. The following conditions are equivalent:
\begin{enumerate}
\item $\nucdim(A)<\infty$;
\item $A\cong A\otimes\Z$;
\item $\nucdim(A)\le1$.
\end{enumerate}

Let $F$ have characteristic zero, and let
$0\ne f\in F\langle x_1,\ldots,x_n\rangle$ have a formula of size at
most $s$.  There are $m\le2s$, a nonzero constant row $u$, a constant
column $v$, and an invertible matrix $G\in F[[z]]^{m\times m}$ such that
\begin{equation}

 G'=AG,\qquad G(0)=I_m,\qquad
 A(z)=\frac{P(z)}{q(z)},\qquad
 q(z)=\prod_{i=1}^n(z+i),\quad \deg P\le n-1,
\end{equation}
where $P$ is a polynomial matrix.  Moreover,
\begin{equation}

 h_f(z)=\sum_w f_wh_w(z)=uG(z)v\ne0.
\end{equation}

Let $M/\Q$ be a finite, totally imaginary Galois extension, put
$R=\Gal(M/\Q)$, and let $c\in R$ be a complex conjugation.
For every rational prime $\ell$, there are $R$-equivariant embeddings
\begin{equation}
 W_M:=\Ind_{\langle c\rangle}^{R}(\mathrm{sign})
 \lhook\joinrel\longrightarrow\X{\ell}{M}
 \lhook\joinrel\longrightarrow\Q_\ell[R],
\end{equation}
where $\mathrm{sign}(c)=-1$.  In particular, the action of $R$ on
$\X{\ell}{M}$ is faithful.

The extension $\beta:G_k\to P$ is surjective. Put
\[
 m_0=[k:\Q]!,\qquad
 \mathcal L=\{\ell:\ell\text{ is an odd prime and }
                    \ell\equiv1\pmod{m_0}\}.
\]
The set $\mathcal L$ is infinite, and for every $\ell\in\mathcal L$,
\begin{equation}
 \log\chi_\ell\circ\beta=\log\chi_{k,\ell}
 \quad\text{as additive characters on }G_k.
\end{equation}
Here $\chi_\ell$ is the $\ell$-adic cyclotomic character on $P$,
and $\chi_{k,\ell}$ is the ordinary cyclotomic character on $G_k$.

Let \(n=2^d\), \(T=200d\), and \(1\le k\le7n/8\). Choose an ordered list \(C=(c_1,\ldots,c_k)\) uniformly among all lists of distinct labels, independently of the shuffle. Then
\begin{equation}
 \begin{aligned}
 \mathbb E_C
 \left\|\mathcal L\bigl((\Pi_T(c_1),\ldots,\Pi_T(c_k))\mid C\bigr)
       -U_{\mathrm{inj}}\right\|_{\mathrm{TV}}
 &\le\varepsilon_n,\\
 \varepsilon_n:=\frac{n^{3/2}}2
  \sqrt{(31/32)^{198d}+32e^{-n/256}}
 &=O(n^{-5/2}).
 \end{aligned}
\end{equation}

Let \(n\) be a positive multiple of eight, and partition the labels of \(G=S_n\) into sets \(M_1,\ldots,M_8\) of size \(n/8\). For each \(a\), let \(H_a\) be the subgroup fixing every label outside \(M_a\). Suppose a probability measure \(\nu\) on \(G\) satisfies
\[
 \nu(gH_a)\le4\frac{|H_a|}{|G|}
 \qquad(g\in G,\ 1\le a\le8).
\]
Then every irreducible unitary representation \(\rho\) of \(G\), of degree \(D\), satisfies
\begin{equation}
 \|\widehat\nu(\rho)\|_{\mathrm{op}}
 \le A D^{-5/16},\qquad A=\sqrt{32C_1}.
\end{equation}

For every bin $j$ and all sufficiently large $X$,
\begin{equation}
 |C_j^\circ|\ll \frac{S K(C_3\sqrt W)^J}{L}+e^{-L}.
\end{equation}
The threshold may depend on the fixed $h,l,W$, while $C_3$ is the
absolute constant in \eqref{q:C3-choice}.

Let $X\ge D\ge10$ and let $b\colon\N\to\C$ be a $1$-bounded
multiplicative function. With
$Q=\min((\log X)^{1/125},(\log D)^5)$, one has
\begin{equation}
 \begin{split}
 \sup_{\alpha\in\T}\int_0^X
 \left|\sum_{y<m\le y+D}b(m)\mathrm e(\alpha m)\right|\,dy
 \ll DX\left(
 e^{-\mathcal M(b;X,Q)/20}
 +\frac{\log\log D}{\log D}
 +\frac1{(\log X)^{1/700}}\right).
 \end{split}
\end{equation}
The implied constant is absolute.

For each closed line there is a predicate
$R_{\boldsymbol d}(n_{\mathcal F})\in\{0,1\}$ with the following
properties.  Whenever it equals one:
\begin{enumerate}
\item all core line occurrences are lit; no primitive specification
with support contained in $\mathcal F$ qualifies at a trace vertex;
and fewer than $t_0$ repeated center occurrences are unlit;
\item every fixed tree prime has $O(B^\rho)$ active components;
fewer than $B^{1-2\rho}$ fixed tree primes have more than one
active component;
\item fewer than $B^{1-2\rho}$ nonfixed tree primes are corrupted.
\end{enumerate}
The implicit constant is uniform in the line.  Moreover,
\begin{equation}
 \sum_{\boldsymbol d}
  \E\left[|K_{\boldsymbol d}(n)|
       \prod_{j=0}^{\ell}\1_Y(n+b_j)
       (1-R_{\boldsymbol d}(n_{\mathcal F}))\right]
 \ll \exp(-B^{1+\eps/2}).
\end{equation}
The same exceptional estimates used in this proof remain valid
after adding the qualification indicators of at most $2t_0$
specifications and summing their recorded data, for the classes
discarded by an arithmetic saving.  Configurations excluded because
of a fixed forbidden specification instead vanish with the original
$Y$ factors.

For the retained line and fixed-coordinate data of
\Cref{prop:retained-lines}, there is a factor
$\mathfrak C_B=\exp(O(M_0\log B))$ such that
\begin{align}
 &\sum_{\boldsymbol d}\E_{\mathcal F}
   \left[R_{\boldsymbol d}
     \left|\E_{\mathcal S\setminus\mathcal F}
          K_{\boldsymbol d}(n)\prod_{j=0}^{\ell}\1_Y(n+b_j)\right|\right]
       \notag\\
 &\quad\le \mathfrak C_B\sum_{\boldsymbol d}\E_{\mathcal F}
   \left[R_{\boldsymbol d}
     \sum_{\mathfrak L\in\mathscr L_{<t_0}(\boldsymbol d)}
       \left|\E_{\mathcal S\setminus\mathcal F}
                      K_{\boldsymbol d}(n)I_{\mathfrak L}(n)\right|\right]
       +O\!\left(e^{-B^{1+\eps/2}}\right).

\end{align}
Here each sum runs over numerical closed lines, $\mathcal F$ is the
fixed prime set of that line, and every list indicator imposes full
qualification of its specifications.

Let $f_1,f_2\colon\N\to\mathbb D$ be multiplicative, with at least
one uniformly nonpretentious. For fixed distinct nonnegative integers
$h_1,h_2$, an integer $l\ge1$, and any integer $b$,
\begin{equation}
 \frac1X\sum_{1\le n\le X}
 f_1(n+h_1)f_2(n+h_2)\1_{n\equiv b\pmod l}
 \longrightarrow0
 \qquad(X\longrightarrow\infty).

\end{equation}
The limit holds through all real $X$, including nonunit residue classes.

Cup product by $e$ sends $P_kH^m(X)$ into $P_{k+2}H^{m+2}(X)$.
For every $i\ge0$ and every $m$, it induces an isomorphism
\begin{equation}
 e^i:\operatorname{Gr}^P_{R-i}H^m(X)
 \xrightarrow{\ \sim\ }
 \operatorname{Gr}^P_{R+i}H^{m+2i}(X).
\end{equation}

Let $\delta=\deg(x:S\to C)$.  The operator $f'$ of
\eqref{trans:fprime} satisfies
\begin{equation}
 [[f',e],e]=8(-1)^b n(n-2)!\delta\,e.
\end{equation}
Consequently
\begin{equation}
 f=\frac{(-1)^{b+1}}{4n(n-2)!\delta}\,f'
\end{equation}
has cohomological degree $-2$, lowers perversity by two and Betti weights
by four, and satisfies $[[f,e],e]=-2e$.

Let \(Y\subseteq S\) be spherical and \(x\in A\).
For the family stabilizer
\[
 H(Y,x)=\{s\in A_Y:E_L(sx)\simeq E_L(x)
                         \text{ for every }L\},
\]
one of the following holds:
\begin{enumerate}
