 \mathcal R_f(z)=a_n^I(R_0,L)
 \frac{\EE_{\mu_{\rm in}}
   [R_*\sigma(\operatorname{col}(V(z)))D_{V(z)}(2/d)^{N(z)}]}
 {\EE_{\mu_{\rm in}}U_z}.

