There are a smooth function $u$ and a smooth vector field $X$ on $\Omega$,
smooth up to its one-sided boundary, with the following properties.
\begin{enumerate}[label=\textup{(\roman*)}]
\item They satisfy $u\ge |X|_g$, $u>0$ in $\operatorname{int}\Omega$, and
\begin{equation}
 u\mu+J(X)=0.

\end{equation}
With symmetric indices denoting averaging, their equations are
\begin{align}
 \nabla_{(i}X_{j)}&=-uK_{ij},
 \\
 \Delta u&=-\operatorname{div}_g\bigl(K(X,\cdot)^\sharp\bigr),
 \\
 \nabla^2u
 &=u(\Ric_g+\tau K-2K^2)-\mathcal L_XK+X_{(i}J_{j)}.

\end{align}
Here $X_i=g_{ij}X^j$ and $(K^2)_{ij}=K_{ik}K^k{}_j$.
\item On the chosen asymptotically flat end,
\begin{equation}
 (u,X)=(b^0,b)+O_2(r^{-q_0}).

\end{equation}
\item At the boundary, for the unit normal $\nu$ pointing into $\Omega$,
\begin{equation}
 X=u\nu,\qquad
 \partial_\nu u+K(X,\nu)=\kappa.

\end{equation}
Either $u>0$ everywhere on $S$ or $u=0$ everywhere on $S$.
\item On $\mathbb R\times\operatorname{int}\Omega$, set
\begin{equation}
 \mathbf g=-u^2\,\mathrm dt^2
   +g_{ij}(\mathrm dx^i+X^i\,\mathrm dt)
          (\mathrm dx^j+X^j\,\mathrm dt),
 \qquad \xi=\partial_t,\qquad N=u^2-|X|_g^2.

\end{equation}
For the future normal $n=u^{-1}(\xi-X)$, the slice $t=0$ has exactly the
original induced metric $g$ and second fundamental form $K$, with the convention
of Theorem~\ref{rig4:thm:rigidity}.  Moreover,
\begin{equation}
 \Ric_{\mathbf g}(\xi,\cdot)=0,
 \qquad \Ric_{\mathbf g}=0\quad\hbox{on }\{N>0\}.

\end{equation}
\item We have $N\ge0$, $N\to1$ at infinity, and $N>0$ in a full collar just
outside $S$.  More precisely, in the positive boundary-lapse case,
\begin{equation}
 N|_S=0,\qquad
 \mathrm dN|_S=2u\kappa\,\nu^\flat=2\kappa X^\flat.

\end{equation}
In the zero boundary-lapse case, if $s\ge0$ is the original $g$-normal distance
from $S$, there are smooth one-sided fields $d,Y_2$ such that
\begin{equation}
 u=sd,\qquad X=s^2Y_2,\qquad d|_S=\kappa,\qquad
 N=s^2\bigl(d^2-s^2|Y_2|_g^2\bigr).

\end{equation}
Consequently all zeros of $N$ in $\operatorname{int}\Omega$ lie in a compact
subset of that interior.
\end{enumerate}

On the real linear space of all smooth TT seeds with the prescribed
decay, the first deficit coefficient is zero and the second coefficient
$c_2[q]$ is a continuous, rotation-invariant, nonnegative quadratic form.
For a finite-angular-type seed it is given by
\begin{equation}
 \begin{gathered}
 c_2[q]=\frac1{16\pi}\int_M N\left(
 |q-Q(v)|^2+|U|^2+2FJ_s^0F\right)\,\dd V_0,\\
 J_s^0=-\Delta_{r^2\sigma}-\frac2{r^2}+\frac{6m_0}{r^3}.
 \end{gathered}

\end{equation}
The last term is integrated on the spheres before radial integration.
For every actual branch in Theorem~\ref{ads:thm:main},
\begin{equation}
 \mathfrak D_q(\eps)=c_2[q]\eps^2+o(\eps^2).

\end{equation}
In particular, $c_2[q]>0$ implies a strictly positive deficit for all
sufficiently small positive $\eps$.

For every finite cube $\Lambda$, spin $S$, and $0<\beta<\infty$ as
above, the partition function is
\begin{equation}
 Z_\Lambda(\beta):=\Tr_{\mathcal H_\Lambda}e^{-\beta H_\Lambda}
       =e^{\beta q_\Lambda/4}\,
                     \mathbb E_{\mathrm b}2^{c(\omega)}.
\end{equation}
More generally, for every function $\Phi$ on the finite spectrum of
$M_\Lambda$,
\begin{equation}
 \frac{\Tr_{\mathcal H_\Lambda}
          \bigl(e^{-\beta H_\Lambda}\Phi(M_\Lambda)\bigr)}
      {Z_\Lambda(\beta)}
 =\frac{\displaystyle\mathbb E_{\mathrm b}
          \sum_{\varepsilon\in\{-1,1\}^{\{\text{cycles of }\omega\}}}
          \Phi\!\left(\frac12\sum_C\varepsilon_C a_C\right)}
        {\displaystyle\mathbb E_{\mathrm b}2^{c(\omega)}}.
\end{equation}
Thus the spectral law of $M_\Lambda$ is obtained by weighting the base
picture by $2^{c(\omega)}$, then coloring each cycle independently
up or down with equal probabilities, and summing the corresponding
$+1/2$ or $-1/2$ over its slots at time $0$.

For \(P\) as above, the conditional law of the unexposed picture given
\(\mathcal H\) under \(\mathbb P_P\) is
\(\mathbb Q_{\mathbf a}(\,\cdot\mid G_P)\), and
\(g_P(\mathbf a)>0\) for almost every exposure under this pin law.

More precisely, fix a deterministic initial label set
\(A\subseteq V_\Lambda\), and let \(\mu_A\) be the distribution under
\(\mathbb P_{\mathrm b}\) of the histories and endpoint mappings of
these labels.  Let \(F_A\) mean that their endpoint set is \(A\) and
their paths avoid \(P\).  On \(F_A\), let \(c_A(\mathbf a)\) be the
number of cycles in their endpoint permutation.  If \(Z_P\) is the
normalizer defining \(\mathbb P_P\), then for every bounded measurable
function \(\Phi\) of the exposure and remaining picture,
\begin{align}
 &\mathbb E_P\Phi(\mathbf a,\omega_{\mathrm h}) \notag\\
 &\quad=\frac1{Z_P}\sum_{A\subseteq V_\Lambda}
 \int_{F_A}2^{c_A(\mathbf a)}\,
 \mathbb E_{\mathbb Q_{\mathbf a}}
       [\1_{G_P}\Phi(\mathbf a,\omega_{\mathrm h})]\,
                         \mu_A(\dd\mathbf a).

\end{align}
Consequently, the exposure marginal on the \(A\)-branch is
\begin{equation}
 \frac1{Z_P}\1_{F_A}(\mathbf a)2^{c_A(\mathbf a)}
                       g_P(\mathbf a)\,\mu_A(\dd\mathbf a).

\end{equation}
The same conclusions hold with \(P\) any finite deterministic pin set.

Let $\psi:D\to\H$ send $a,c,d$ to $0,1,\infty$, and put
