On every compact capacity interval, the Dobrushin driving functions
converge in law, uniformly, to $\sqrt\kappa B_t$, where $B$ is standard
Brownian motion and
\begin{equation}
 \kappa=\frac{8}{1+h}
        =\frac{4\pi}{\arccos(-\sqrt q/2)}.
\end{equation}

In its own radial clock, the limiting gap is the unique instantaneous
reflected diffusion on $[0,2\pi]$ with interior generator
\begin{equation}
 \mathcal A f(\theta)=\frac\kappa2 f''(\theta)
       +\frac{\kappa-4}{2}\cot(\theta/2)f'(\theta).
\end{equation}
The forcepoint has no singular push:
\begin{equation}
 O_t=O_0+\int_0^t\cot(\theta_s/2)\,ds.
\end{equation}
Equation~\eqref{tree:sde} consequently holds globally, including
collisions, with locally integrable drift.

There is an absolute \(a<\infty\) with the following property. For every
finite metric \(Y\) of positive diameter, every \(k\ge2\), and every
start \(s\in Y^k\), there is a finite \(D_0=D_0(Y,k,s)\) such that,
for every finite horizon \(H\) and every probability law on \(Y^H\),
there is a causal strongly lazy policy satisfying
\begin{equation}
             \E\,\cost\le a\ell^2\E\,\OPT+D_0 .
\end{equation}
The policy may depend on the law and horizon. The number \(D_0\)
does not.

There are absolute constants $C_0,C_1$ and $\tau_0$ with the following
property.  For $\tau\ge\tau_0$, the observed histories determine amounts
$q_v(t)$ satisfying
\begin{equation}
 q_{\mathrm{root}}=k,\qquad
 0\le q_v\le C_0m_v,\qquad
 \sum_{i\prec v}q_i\le q_v,\qquad q_{x_t}\ge1.
\end{equation}
Moreover, with $\ell=1+\log(k+1)$,
\begin{equation}
 V:=\E\sum_{t\ge1}\sum_{v\ne\mathrm{root}}
       r_{|v|-1}|q_v(t)-q_v(t-1)|
 \le C_1\ell P+D_{\mathcal T}.
\end{equation}
Here sums stop at the chosen finite horizon.  The finite constant
$D_{\mathcal T}$ depends only on the fixed tree, radii, and $k$;
it can be chosen independently of the input law, horizon, and number of
histories.  No initial allocation is prescribed.

With $\epsilon_0=10^{-6}$, there exists $\delta_0>0$ such that
\[
 \#\{n\in\Z:N\le n\le2N,\ p^2\mid n^4+1\text{ for some prime }
       N^{1-\epsilon_0}\le p\le N^{3/2+\epsilon_0}\}
 \ll N^{1-\delta_0}.
\]

For each parameter $y$ in the height-at-least-$h$ polydisc, the formula
\begin{equation}
 \Theta_y(z)=\lim_{j\to\infty}
       P_y^{\circ j}\bigl(z^{1/Q^j}\bigr)

\end{equation}
defines a continuous natural homomorphism
\[
 \Theta_y:\mathcal H_n(R)\longrightarrow H_y(R^{\circ\circ}).
\]
Here the roots are unique because $R$ is perfect, and $P_y^{\circ j}$
denotes composition.  The map
\begin{equation}
 \Phi_y:z\longmapsto
       \bigl(\Theta_y(p^{-m}z)\bigr)_{m\ge0}

\end{equation}
is a natural isomorphism
\[
 \mathcal H_n(R)\xrightarrow{\ \sim\ }
     \varprojlim_{[p]_{H_y}} H_y(R^{\circ\circ}),
\]
and $\Theta_y$ is its zeroth projection.  For each fixed
$z\in\mathcal H_n(C)$, the function $y\mapsto\Theta_y(z)$ is analytic
on the parameter polydisc.

For a $\Zp$-basis $z_1,\ldots,z_r$ of $T_x$, the analytic map
\begin{equation}
 \theta(y)=\bigl(\Theta_y(z_1),\ldots,\Theta_y(z_r)\bigr)

\end{equation}
has invertible differential at $x$ on the height-at-least-$h$ polydisc.

There is $a_0>0$ such that, for every $0<a<a_0$, there are
$(b_a,Z_a)\in\mathcal D$ and a smooth nonvanishing radial stationary
solution $Q_a=A_ae^{i\phi_a}$ of \eqref{profile:similarity}, normalized by
$Q_a(0)>0$.  They have the following properties.
\begin{enumerate}
\item The identities \eqref{profile:amplitude}--\eqref{profile:divergence}
hold, $0<P_a\le1$, and there are constants $c,C>0$, independent of small
$a$, such that
\begin{equation}
 C^{-1}\langle r\rangle^{-4a}\le\mu_a(r)
       \le C\langle r\rangle^{-4a},\qquad
 \nabla w_a\ge c I.
\end{equation}
\item If $a_n\downarrow0$ and $(b_{a_n},Z_{a_n})\to(b,Z)$, then
$j(b,Z)=0$, where $j$ is the free matching function of
Proposition~\ref{free:main}.  With $R=2\sqrt Z$, the profiles converge in
$C^1$ on every compact ball to
\begin{equation}
 Q_0(r)=
 \begin{cases}
 1,&0\le r\le R,\\[2pt]
 \displaystyle\frac{H(-ib,6,-ir^2/4)}{H(-ib,6,-iZ)},&r\ge R.
 \end{cases}
\end{equation}
The exterior amplitude is strictly decreasing and has a positive limit
at infinity.  The convergence is $C^\infty$ on compact subsets of
$\{r>R\}$.  On every fixed ball,
\begin{equation}
 P_{a_n}\ \stackrel{*}{\rightharpoonup}\ b\mathbf1_{\{r<R\}}
       \quad\hbox{in }L^\infty,
\end{equation}
and $\mu_{a_n},w_{a_n}$ converge in $C^1$.  In particular
$P_{a_n}/a_n\to0$ locally uniformly on $\{r>R\}$.
\item On the fixed exterior $r\ge r_b$,
\begin{equation}
 Q_a(r)=r^{\nu_a}f_a(r),\qquad \nu_a=-2a+2ib_a,
 \qquad 0<\kappa\le|f_a(r)|\le\rho<1,
\end{equation}
with $\kappa,\rho$ independent of $a$.  There are coefficients
$m_{a,j}$, with $|m_{a,0}|\ge\kappa$, such that for every pair of fixed
nonnegative integers $N,J$,
\begin{equation}
 \left|D^j\left(f_a(r)-\sum_{q=0}^{N}m_{a,q}r^{-2q}\right)\right|
       \le C_{N,J}r^{-2N-2},\qquad 0\le j\le J,\quad r\ge r_b.
\end{equation}
The constants are uniform as $a\downarrow0$.  In particular,
\begin{equation}
 |D^j(P_a/a)|\le\eta_j(a)r^{-2},\qquad
 |D^je^{2i\phi_a}|\le C_j,\qquad \eta_j(a)\longrightarrow0
\end{equation}
for each fixed $j$.  On the inner ball,
\begin{equation}
 W_a(P_a/a)\le Ca(P_a/a),\qquad r\le r_b,
\end{equation}
whereas $|W_a(P_a/a)|\le\eta(a)r^{-2}$ for $r\ge r_b$, with
$\eta(a)\to0$.  Consequently the positive part of $W_a(P_a/a)$ is
bounded uniformly on the whole space.
\item For each fixed $a$, every Cartesian derivative obeys
\begin{equation}
 |\partial^\beta Q_a(y)|\le C_{a,\beta}\langle y\rangle^{-2a-|\beta|},
 \qquad
 \left|\partial^\beta\big((P_a/a)e^{2i\phi_a}\big)\right|
       +|\partial^\beta(P_a/a)|
       \le C_{a,\beta}\langle y\rangle^{-2-|\beta|}.
\end{equation}
The time-symmetry combination has the improved exterior order
\begin{equation}
 \left|D^j\left((a-ib_a+D/2)Q_a\right)\right|
       \le C_j r^{-2a-2},\qquad r\ge r_b.
\end{equation}
\end{enumerate}

There is a bounded real-linear map $\pi:Y\to\mathbb R^{14}$ such that
