The metric normalization is the one fixed in Theorem~\ref{thm:continuum}; changing it by a deterministic factor changes $a_n$ by that factor.

For each return $C'$ born in a paired sweep of $C$,
\begin{equation}
\overline{C'}\subset C.
\end{equation}
Every return is captured as one untouched negative pocket by finitely many ordinary full-fan branches from $\partial C$, and has empty inherited open target interval.  Conversely a complete negative birth with empty inherited target interval is a stabilized return.  As the finite target lists increase densely, the two-layer walls stabilize exactly on interior compact sets and the uncaptured negative pockets have uniformly vanishing closure diameters.

For all sufficiently small fixed \(\epsilon>0\), the quantiles defined in Section~\ref{conf:el-setup} satisfy

\begin{equation}
\liminf_{j\to\infty} b_j(\epsilon)>0.
\end{equation}

The following possibilities have probability zero for typical-scale limits under the lift:

\begin{itemize}
\item
  all four main halves dip strictly (finite centered test);
\item
  just one positive, protected, and either initial wall, or accessible with the helper's
  two strict dips (finite centered tests).
\end{itemize}

There exists a finite \(a=a(b)\ge0\) such that \(a_m(b)\to a\).
Let \(B_n\), at mesh \(n^{-1}\), be any sequence of free axis
rectangles with endpoints converging to those of a nondegenerate
rectangle \(B\). For every finite collection of smooth shifts
defined near \(\overline B\),
\begin{equation}
 \log\E\exp\{\ip{h}{A_{B_n}g(\cdot/n)}\}
 \longrightarrow \frac a2\int_B|\nabla g|^2.

\end{equation}
Joint limits are Gaussian, with covariance
\(a\int_B\nabla g\cdot\nabla g'\), and all joint moments converge.
For zero-total profiles \(f_n\) whose scaled densities converge in
\(L^2(B)\) to a bounded piecewise continuous \(f\) of integral zero,
\begin{equation}
 \log\E e^{\ip{h}{f_n}}
 \longrightarrow
 \frac a2\ip{f}{(-\Delta_{B,N})^{-1}f}_{L^2(B)}.

\end{equation}
Face smears, after subtracting their totals from a volume smear,
are allowed as well. These limits may be degenerate when \(a=0\).

For the prescribed free-box correlation,
\begin{equation}
 \limsup_{n\to\infty}\frac{\log C_b(n)}{\log n}
       \le-\frac{2\pi}{a(b)}.

\end{equation}
When \(a(b)=0\), the assertion means that the limsup is
\(-\infty\), or equivalently that every fixed polynomial
upper exponent is eventually available.

If $m_o=4$, write $\rho=\sin t$, $c=\cos t$ and parameterize the
regular part of the suspended component by
\[
 (t,y)\longmapsto (\rho y,c),\qquad
 0<t<\pi,\quad y\in\Omega_o.
\]
Its metric is $dt^2+\rho^2 ds_{S^4}^2$, and $\widetilde g=\rho g_o$.
With $E_0=\partial_t$ and $E_\alpha=\rho^{-1}e_\alpha$ for a lifted
orthonormal frame on $S^4$, the data satisfy
\begin{align}
 \widetilde p_0&=c g_o,
 &\widetilde p_\alpha&=(p_o)_\alpha,
 &\widetilde s^2&=s_o^2,
 \\
 \widetilde T_{00}&=0,
 &\widetilde T_{0\alpha}&=0,
 &\widetilde T_{\alpha\beta}&=\rho^{-1}(T_o)_{\alpha\beta}.

\end{align}
The only possibly nonzero components of $\widetilde B$ are
\begin{equation}
 \widetilde B_{\alpha\beta\gamma}
   =\rho^{-2}(B_o)_{\alpha\beta\gamma},\qquad
 \widetilde B_{0\alpha\beta}
 =\widetilde B_{\alpha0\beta}
 =\widetilde B_{\alpha\beta0}
   =-c\rho^{-2}(T_o)_{\alpha\beta}.
\end{equation}
In particular,
\begin{equation}
 \widetilde w=\rho^{-1}w_o,\qquad
 |\widetilde B|^2
 =\rho^{-4}\bigl(|B_o|^2+3c^2w_o^2\bigr),\qquad
 \widetilde H=\rho^{-1}H_o
 \quad\hbox{on the regular side.}
\end{equation}
The volume and side-boundary measures are
\begin{equation}
 dV=\rho^4\,dt\,dV_o,\qquad
 d\sigma=\rho^3\,dt\,d\sigma_o.
\end{equation}
Every local identity of Proposition~\ref{geo:interior-identities}
holds with $m=5$, and Proposition~\ref{geo:boundary-jets} holds on
the regular side. Also $\widetilde s^2<1$ inside and
$\widetilde H,\widetilde w>0$ on that side.

The scalar $h$ and vector field $Z$ satisfy
\begin{equation}
 \diver Z\geq 4h^2+|\nabla h|^2+\epsilon_*w^{2a}
 \qquad\text{on }\Omega_+.
\end{equation}

For integer sequences \(n,n'\to\infty\) with \(n'/n\to d\in(0,\infty)\),
\begin{equation}
                  \frac{M_{n'}}{M_n}\longrightarrow d^{-1/8}.
\end{equation}
There is a constant \(c_{\rm shape}\in(0,\infty)\) such that
\begin{equation}
                  \frac{C_{b_c}(r)}{M_r^2}\longrightarrow c_{\rm shape}
                  \qquad(r\to\infty,\ r\in\Z).
\end{equation}
Here \(C_{b_c}\) is the thermodynamic limit in
\eqref{eq:critical-definition}; that limit precedes \(r\to\infty\).
In particular, \(M_n=n^{-1/8+o(1)}\).

The entry choices can be made so that, for every fixed
\(0<c<c'<3\), uniformly for integers
\(c2^k\le j\le c'2^k\) as \(k\to\infty\),
\begin{equation}
 \begin{split}
 t_j^{(k)}&=\frac{1}{2(\log L)j}
                  +O\!\left(\frac{\log(2+j)}{j^2}\right),\\
 z_j^{(k)}&=O(j^{-1}),\qquad
 \|\mathcal R_j^{(k)}\|_{j,k}=O(j^{-2}).
 \end{split}
\end{equation}
The constants may depend on \(c,c'\) and the fixed map parameters.
In particular the assertion applies at the stop \(j'=N-O(\log N)\)
in the history chosen for \(2^k\le N<2^{k+1}\).

Fix \(0<\epsilon<1/10\).  For all sufficiently large \(N\), put
\(n_0=L^N\), \(n_1=L^{N+1}\), and choose a power \(m'=L^{j'}\) so that
\begin{equation}
 D_N=\frac{n_0}{m'}\asymp N^\epsilon,\qquad
 j'=N-O(\log N).
\end{equation}
Use the entry history for \(N\) in both squares, and let \(t_{j'}\)
be its unbalanced plane gradient coefficient at the stop.  Then
\begin{equation}
 \log\frac{M_{n_1}}{M_{n_0}}
 =-\frac{1-t_{j'}}{2a}(g_{n_1}-g_{n_0})
   +O\left(\frac{D_N^4}{N^2}+\frac{1}{ND_N}\right).
\end{equation}
Moreover, for a constant \(c_G\),
\begin{equation}
                g_{L^N}=2\pi(\log L)N+c_G+o(1).
\end{equation}
All constants are independent of \(N\).

Let $X_1,\ldots,X_m,Y_1,\ldots,Y_m$ be real $d\times d$ matrices.
If $X_i-Y_i$ is invertible for every $i$, then
\begin{equation}

  \sum_{\substack{1\leq i,j\leq m\\i\ne j}}
       \rank(X_i-Y_j)\geq2d_m d,
  \qquad
  d_m=\left\lfloor\frac m2\right\rfloor
      \left\lfloor\frac{m-1}{2}\right\rfloor.
\end{equation}
The sum is over ordered pairs of distinct indices.

For every fixed stable center $x$,
\begin{equation}
 \Pbb\bigl(\exists t\in[1,2]\ \forall n\in\mathcal N:
 x+t2^{-n}\notin B\bigr)\le2p.

\end{equation}

Let \(n\ge1\) be finite, let \(s,N_B\ge0\) be finite, and let \(0\le\eta\le1\). Every state \(\rho\) on \(n\) modes with
\(\Tr\rho\sum_{j=1}^n a_j^\dagger a_j<\infty\) satisfies
\begin{equation}
 \frac1n S\!\left(\mathcal E_{\eta,N_B}^{\otimes n}(\rho)\right)
 \ge g\!\left(\eta g^{-1}\!\left(\frac{S(\rho)}n\right)
                   +(1-\eta)N_B\right).
\end{equation}
In particular, the exact constrained minimum is
\begin{equation}
 \min_{\substack{\rho\text{ a state on }n\text{ modes}\\
                  \Tr\rho\sum_{j=1}^n a_j^\dagger a_j<\infty\\
                  S(\rho)=ns}}
 \frac1n S\!\left(\mathcal E_{\eta,N_B}^{\otimes n}(\rho)\right)
 =g\!\left(\eta g^{-1}(s)+(1-\eta)N_B\right).
\end{equation}
It is attained by the product thermal input \(\tau_{g^{-1}(s)}\). No independence assumption is imposed among the modes of \(\rho\); only the environment is required to be independent of that input.

At every coordinate of every space, let $m>0$ and $x,y\in\R$ be given.
Suppose each $Z\in\mathcal T$ is supported on finitely many values of the
parameter tuple $(m,x,y)$, and $\mathcal T$ is invariant under scalar
multiplication by functions of this tuple.  If the four families
\begin{equation}
 mf(x)e^x,\quad mf(x)e^{-x},\quad mf(y)e^y,\quad mf(y)e^{-y}
\end{equation}
satisfy comparison, then so does
\begin{equation}
 F=m\frac{f(x)f(y)}{f(x+y)}.
\end{equation}

The positive weights
\begin{equation}
 F_s(v)=\frac1{h_s}
 \frac{f(h_sv/2)f(-h_s/2)}{f(h_s(v-1)/2)}
 =\frac{b_s(v)-(r_s+\tfrac12)v}{1-v}
\end{equation}
satisfy \eqref{eq:weight-comparison}.  The quotient at $v=1$ is understood
continuously.  For each fixed $r_s>0$ there are constants
$0<c_s\le C_s<\infty$, independent of the minimizing states, such that
$c_s\le F_s(v)\le C_s$ for every $v\in\R$.

Let \(0\le\bar N<\infty\), \(0\le\eta_C<\eta_B\), and
\(\eta_B+\eta_C\le1\). The classical capacity region for the channel
and coding model above, with rates in nats per use, is the closed
convex hull of the nonnegative pairs \((R_B,R_C)\) satisfying, for
some \(0\le\beta\le1\),
\begin{equation}
\begin{aligned}
 R_B&\le g(\eta_B\beta\bar N),\\
 R_C&\le g(\eta_C\bar N)-g(\eta_C\beta\bar N),
\end{aligned}
\end{equation}
where \(g\) is the natural-log function in~\eqref{eq:g-definition}.

Under the assumptions and notation of Lemma~\ref{lem:type-deficit},
there exist $c>0$ and an integer $n_0$ such that, for each $n\ge n_0$,
there is a deterministic finite integer $B_n\ge a_n$ satisfying
\begin{equation}
 \E\!\left[\mathbf1_{E_n}
       \sum_{\ell=a_n}^{B_n}c_\ell(\nu_{\omega,n})\right]\ge cn.
\end{equation}
Here $c_\ell(\nu)$ is the maximum total weight of fair two-point laws
with separations in $[2^{-\ell},2^{1-\ell})$ whose weighted sum is a
submeasure of $\nu$, as in Lemma~\ref{lem:pair-bound}.
The constants $b,A,A',c,n_0$ are independent of $n$ and $\omega$;
no growth bound on $B_n$ is asserted.

For every datum and regular stability in Theorem~\ref{thm:main}, the
coefficient map induces a graded $R$-algebra surjection
\begin{equation}

 B_F\twoheadrightarrow H_F^*(X).
\end{equation}

The quotient $B_0$ for the full topological torus satisfies the
coefficientwise graded bound
\begin{equation}
 \Hilb(B_0;q)\ \leq
 \sum_{m\in\mathcal M(\mathbf v)}
 q^{C(\mathbf v)-D_m+\mathbf w\cdot(\mathbf v-\mathbf l)}h_m(q).
\end{equation}
Every exponent displayed in the sum is a nonnegative integer.

For every finite array $m$,
\begin{equation}
 \frac{1}{(q)_m}
 =\sum_{k+m'=m}
   q^{w(k)+b(k,m')}\frac{h_{m'}(q)}{(q)_k}.
\end{equation}

In the formal power series ring $\C(q)[[z_i:i\in Q_0]]$,
\begin{equation}
 \sum_m z^{\|m\|}q^{-D_m-w(m)}h_m(q)
 =
 \frac{\displaystyle\sum_m
       z^{\|m\|}q^{-D_m-w(m)}/(q)_m}
      {\displaystyle\sum_m z^{\|m\|}q^{-D_m}/(q)_m}.
\end{equation}

For a quiver with a loop at every vertex of positive dimension,
\begin{equation}
 P_{X_{\det}(v,w)}(q)
 =\sum_{\|m\|=v}
   q^{C(v)-D_m+w\cdot(v-l)}h_m(q).
\end{equation}

At every finite depth, each of the following changes produces a
degraded root experiment:
\begin{enumerate}
 \item replacing \(\lambda\) by \(c\lambda\), where \(0\leq c\leq1\);
 \item replacing a regular offspring count \(b_+\) by an integer
       \(2\leq b_-\leq b_+\);
 \item replacing a Poisson offspring mean \(d_+\) by
       \(0<d_-\leq d_+\).
\end{enumerate}
Consequently each change can only decrease the expected total variation
advantage and the moments \(\E x\) and \(\E x^2\), both at finite
depth and in their limits.

At $\lambda=-a$, $d=a^{-2}$, the uniform posterior law is the only
permutation-invariant fixed point in either of the following ranges:
\begin{enumerate}
 \item regular offspring, with integer $d$ and $0<a\le.448$;
 \item Poisson offspring, with $0<a\le.477$.
\end{enumerate}
In particular the regular assertion covers every integer $d\ge5$.

For step paths on arbitrary partitions,
\begin{align}

 |V_f(p)-V_f(q)|&\le\tfrac12\|f'\|_\infty^2\|p-q\|_{L^1},\\
 |\ell(h')-\ell(h)|&\le\tfrac12\|h'-h\|_{L^1}.
\end{align}
Thus $V_f$ extends uniquely and continuously to all nondecreasing
$[0,1]$-valued paths, and $\ell$ extends to all bounded
nonnegative nondecreasing paths. Moreover,
\begin{equation}

 \int_s^1p(u)\,du\ge\int_s^1q(u)\,du
 \quad\hbox{for every }s\in[0,1]
 \quad\Longrightarrow\quad V_f(p)\le V_f(q).
\end{equation}

The entropy in Definition~\ref{def:entropy} is nonnegative,
nondecreasing in pointwise path order, and satisfies
$S_{\mathrm I}(0)=0$. The variational infimum is finite, and
\begin{equation}

 \inf_q\{\alpha V_f(q)+S_{\mathrm I}(q)\}
 =\inf_{\substack{q\text{ step}\\q_{k-1}<1}}
       \{\alpha V_f(q)+S_{\mathrm I}(q)\}.
\end{equation}

For every subsequential pair $(p,h)$ just constructed,
\begin{equation}
 S_{\mathrm I}(p)=\ell(h)+\frac12\int_0^1p(u)h(u)\,du.
\end{equation}
The right side uses the continuous extension of $\ell$ to bounded
nondecreasing fields.

Suppose $f:\mathbb R\to\mathbb R$ is Borel and
\begin{equation}
 \mathbb E|f(G)|+\mathbb E e^{f(G)}<\infty.
\end{equation}
For $J,K>0$, let $f_{J,K}=\min\{K,\max\{-J,f\}\}$. The uniform limit
\begin{equation}
 V_f=\lim_{J\to\infty}\lim_{K\to\infty}V_{f_{J,K}}
 \quad\text{on }\mathcal Q
\end{equation}
exists and is continuous in $L^1$. With this definition, the variational
formula \eqref{thm:formula} is finite and holds in expectation and in
probability.

For fixed interval weights, uniformly on compact sets of nonnegative
nondecreasing step field values,

\begin{equation}
l_n(h)\ \longrightarrow\ \min_{q_0\le\cdots\le q_{k-1}\,;\ 0\le q_i<1}
       \left\{S(q)-\sum_i w_i h_i q_i\right\}
\end{equation}

as $n\to\infty$. Furthermore, for each fixed $0\le B<1$, if $0\le q(u)\le B$ a.e. is nondecreasing and

\begin{equation}
2h(u)=A_q(q(u)),\qquad A_q(r):=\int_0^r\frac{dt}{D_q(t)^2}\quad(0\le r<1),
\end{equation}

then

\begin{equation}
l_n(h)=S(q)-\int_0^1 hq+o(1),
\end{equation}

where the error tends to zero uniformly over these $q$.

Choose any deterministic parameters $v(N)\in\mathcal G_N$, with $N$
running along any subsequence tending to infinity. Suppose that the omitted
system's overlap array and the full system's arrays
\[
 \big(R_{\ell j},B_N(x^\ell,x^j),C_N(x^\ell)\big)_{\ell,j\ge1}
\]
converge in law in all finite restrictions, under their respective disorder
and Gibbs averages. Let $\mu$ be the off-diagonal two-replica law of the
omitted limiting array, and let $q$ be its quantile. Then the limiting full
and omitted overlap arrays have the same law. There are constants
$a_{\rm d},c$ and a deterministic nonnegative nondecreasing function $a$,
specified $\mu$-almost everywhere, such that the full-system limit satisfies
almost surely
\begin{equation}
\begin{aligned}
 B_{\ell j}&=a(R_{\ell j})\quad(\ell\ne j),\qquad
 B_{\ell\ell}=a_{\rm d},\qquad C_\ell=c,\\
 0&\le a\le a_{\rm d}\le\alpha\|f'\|_\infty^2.
\end{aligned}
\end{equation}
Moreover,
\begin{equation}
\begin{aligned}
 c+a_{\rm d}&=\int r\,a(r)\,\mu(dr),\\
 a(r)&=A_q(r)=\int_0^r\frac{dt}{D_q(t)^2}
                       \qquad(\mu\text{-a.e. }r),\\
 \sup\operatorname{supp}\mu&\le B_*:=
       \frac{\alpha\|f'\|_\infty^2}{1+\alpha\|f'\|_\infty^2}<1.
\end{aligned}
\end{equation}
The law $\mu$ and the quantities $a,a_{\rm d},c$ may depend on the chosen
subsequential limit; the bound $B_*$ does not.

For every $p\in(0,1)$, there is an open $1$-periodic set $H\subseteq\R$
with $\rho(H)\le6p$ such that
\begin{equation}
 \text{for every }x\in\R\text{ and }t\in[1,2],
 \quad x+tq^n\in H\text{ for some integer }n\ge1.
\end{equation}

There is $a\in\Q_p^\times$ such that
\begin{equation}
 e_3=a e_2\quad\text{in }H^3_{\mathrm b}(\mathcal Y_{1,C}).
\end{equation}
The class $e_2$ is pulled back from the actual integral frame
group of the rank-two kernel.

After passing to a subsequence, there is an undirected graph
\(\mathcal G\) on \(P\) with at least \(cN^2\) edges such that, for every
vertex \(p\) and every irreducible projective variety
\(Y\subset\mathbb P^{d-1}\) of dimension \(a\),
\begin{equation}
 \#\{q:\{p,q\}\in\mathcal G,\ \pi_p(q)\in Y\}
 \le C\,\deg(Y)A^a.
\end{equation}
The positive constants \(c,C\) are fixed along the subsequence.

For every non-core profile,
\begin{equation}
 \sum_{i=1}^d b_i=0,\qquad b_1<0<b_d,\qquad b_1+b_2<0.
\end{equation}
On a plateau after $j$ cuts, its carrier family has degree at most
$e_j\exp(o(s))$.  Every subcollection of total degree $a$ meets the
piece in at most
\begin{equation}
 a\left(\prod_{i>j}D_i\right)\exp(o(s))
\end{equation}
points.  This counts all points touching those components, whether
or not they have been assigned to them.  Finally, for every fixed
$\alpha>0$, every subset $S$ of at least $\alpha n$ piece points has
\begin{equation}
 H_S(T_s(b))\ge\sigma(b)\exp(-o(s))
\end{equation}
at each interior testing time, and with the usual limiting
interpretation at a cut time.

Fix $C_0\geq1$.  Let $A\geq1$ and let $\mathcal P$ be a finite set of
distinct parameters $[v:y]\in\mathcal Q$, all with $v\ne0$.  Assume:
\begin{enumerate}
\item[(i)] For every $\lambda\in\mathcal P$ there is a homogeneous polynomial
      of positive degree at most $C_0A$ which is nonzero at $\lambda$ and
      zero at every other member of $\mathcal P$.
\item[(ii)] Every projective $\mathbf P^r\subset\mathcal Q$ contains at most
      $C_0A^{r-1}$ members of $\mathcal P$.
\end{enumerate}
There is a constant $C=C(e,C_0)$ such that
\begin{equation}
 \#\{\lambda\in\mathcal P:F_\lambda\subset V\}
 \leq C\deg(V)A^h,
 \qquad \dim V=s_0+h,\quad 1\leq h<r,

\end{equation}
for irreducible proper affine varieties $V\subset S$, in either of these
settings:
\begin{enumerate}
\item[(a)] All such $V$ are allowed, and $|\mathcal P|\leq C_0A^r$.
\item[(b)] Only $V$ contained in the zero set of some nonzero polynomial
      of degree at most $C_0A$ are allowed.  No bound on
      $|\mathcal P|$ is required.
\end{enumerate}

With the weights chosen above, every such curve satisfies
\begin{equation}

 \deg_W C\ge(1+\sigma)\sum_{P\mapsto a_j}h_P,
\end{equation}
where the sum includes all branches through the prescribed points.

For every fixed integer $J\geq2$ and every pair of fixed phase vectors
$(\zeta_k)_{k=1}^{J-1}$ and $(\xi_k)_{k=1}^{J-1}$ of absolute value one,
the corresponding labels satisfy
\begin{equation}
 \lim_{x\to\infty}\frac1x\sum_{1\leq n<x}
                   \overline{g_x(n)}F_x(n+1)=0,
\end{equation}
where $F_x=f_x-\mu$ and the limit is through all integer scales.

There is a function $r(H)$ tending to zero as $H\to\infty$ such that,
for every real multiplicative function $g:\N\to[-1,1]$ and
$2\leq H\leq X$,
\begin{equation}
 \frac1X\int_X^{2X}
   |\mathcal A_Hg(z)-\mathcal L_Xg|^2\,dz\leq r(H).
\end{equation}

For every multiplicative function $g:\N\to\C$ with $|g|\leq1$ and
$X\geq H\geq10$,
\begin{equation}
 \frac1X\int_X^{2X}|\mathcal A_Hg(z)|^2\,dz
 \ll (1+M(g;X))e^{-M(g;X)}
       +\left(\frac{\log\log H}{\log H}\right)^2
       +(\log X)^{-1/50},
\end{equation}
with an absolute implied constant.

Let $w_3$ be smooth and supported in a fixed compact subinterval of
$(0,\infty)$.  Uniformly for
$0.9B\le\log X\le2.2B$, $q\le B^{15}$, $(u,q)=1$, and real $\xi$ with
$|\xi|\le B^{14}$,
\begin{equation}
 \sum_c A_0(c)w_3(c/X)e(cu/q+\xi c/X)
 =X\frac{\mu_{\rm Mob}(q)}{\varphi(q)}
       \int w_3(t)m_B(\log(Xt)/B)e(\xi t)\,dt
       +O(XB^{-50}).

\end{equation}
The convention $q=1$ is included.  The constant in the error is controlled
by a fixed constant times finitely many low-order smooth norms of $w_3$;
the expansion order defining $m_B$ is independent of $w_3$.

Let $\nu_z$ be the law of the product of primes of $\mathcal P$ selected
independently with probabilities $z/p$, and write $s=\log a/B$ for its log
coordinate.  For $d\le B^{15}$, every such product is a unit modulo $d$.
Uniformly for all intervals $I'\subset[B^{-1/10},3.2]$ and unit residues
$r\pmod d$,
\begin{equation}
 \Prob_{\nu_z}(s\in I',\ a\equiv r\pmod d)
 =\frac1{\varphi(d)}\int_{I'}f_{z,B}(s)\,ds+O(B^{-80}).

\end{equation}
Uniformly for $0\le\delta\le1$,
\begin{equation}
 \Prob_{\nu_z}(s\le\delta)\ll(\delta+1/R)^z.

\end{equation}
For each positive integer $n\le\exp(3.2B)$,
\begin{equation}
 \nu_{1/2}(n)\ll\frac{A_0(n)}{Bn},

\end{equation}
where both sides are zero unless $n$ is a squarefree rough product, apart
from the allowed empty product $n=1$.

There is $c_5>0$, independent of all sufficiently large fixed
$C_*$, for which the nonnegative energy below satisfies the displayed
lower bound:
\begin{equation}
\begin{gathered}
 I_{2,x}
 = \frac1x\sum_{c\ge1}
   \rho_0(\log c/B)A(c)
   \sum_{m\ge1}K(m)
   \left|
     \sum_{\substack{a\ge1\\c\mid am+1}}
     A(a)K(l_a)\psi(a/(Tc))
     \phi(am/x)F_x(am+1)
   \right|^2,
 \\
 \liminf_{B\to\infty}\ \liminf_{x\to\infty}
       \frac{I_{2,x}}{BT}\ge c_5
\end{gathered}
\end{equation}
Its diagonal contribution is negligible:
\[
 \lim_{B\to\infty}\ \limsup_{x\to\infty}
       \frac{I_{2,x}^{\mathrm{diag}}}{BT}=0.
\]
Here $I_{2,x}^{\mathrm{diag}}$ denotes the terms with equal
coefficient indices on expanding the square, and
$l_a=(am+1)/c$ as in \eqref{eq:10}.

Let $\mathcal M_{ik}(S_i,S_k;s)$ be a symmetric real kernel,
zero on nonpairs, with total absolute mass $O(B^{10})$
uniformly in its arguments. Then
\begin{equation}
\begin{split}
 &\E_u\left\|
  \bigl(\mathcal K_{k-i}(u+i,s)
  -\mathcal M_{ik}(S_i(u),S_k(u);s)\bigr)_{i,k}
  \right\|_\square\\
 &\hspace{15pt}\le o(1)+
 \E_{(S_i)\,\mathrm{indep}}
 \left\|\bigl(\mathcal L_{ik}(S_i,S_k;s)
                   -\mathcal M_{ik}(S_i,S_k;s)\bigr)_{i,k}\right\|_\square.
\end{split}
\end{equation}
The error is uniform for $s\in\mathcal S$.

For every fixed coarse partition, uniformly for \(1\le d\le B\),
