For each $b>0$ there are a Hilbert space $\mathcal K_b$, a compact
self-adjoint operator $X_b$, and a unitary representation
$g\mapsto U_g$ of $\mathcal G$ commuting with $X_b$, such that
\begin{equation}
 Z_n(b,g)=\Tr(X_b^nU_g)
 \qquad(n\ge4,\ g\in\mathcal G).
\end{equation}
The operator $X_b$ and the representation commute with complex
conjugation. Moreover $X_b$ is Hilbert--Schmidt, so $X_b^k$ is trace class
for every integer $k\ge2$. If $\lambda_i(b)$ are its nonzero eigenvalues,
counted with multiplicity, then
\begin{equation}
 \sum_i|\lambda_i(b)|^k<\infty\quad(k\ge2),\qquad
 Z_n(b)=\sum_i\lambda_i(b)^n\quad(n\ge4).
\end{equation}

For every even $L\ge4$, let $H_L$ be a non-scalar finite-dimensional
self-adjoint Hamiltonian. Suppose that $a\in\R$ and, for each $b>0$,
a real finite or countable list $(\lambda_i(b))$ satisfy
\[
 \sum_i|\lambda_i(b)|^4<\infty,\qquad
 Z_L(b):=\Tr e^{-b(H_L+aLI)}=\sum_i|\lambda_i(b)|^L
 \quad(L\ge4\text{ even}).
\]
Define $S,T$ by \eqref{eq:purities} and $G$ by
\eqref{eq:bootstrap-coefficient}. Let $n_0\ge4$ be even,
$b_0>0$, and let $u_0,C$ satisfy
\begin{equation}
 0<u_0<\frac16,\qquad G(u_0)\le C,\qquad
 r:=Cu_0<1,\qquad C(1-3u_0)>3.
\end{equation}
Suppose
\begin{equation}
 S(n_0,b_0)\ge1-u_0,\qquad T(2n_0,b_0)\ge1-u_0.
\end{equation}
For $j\ge0$, set
\begin{equation}
 n_j=2^j n_0,\qquad b_j=2^j b_0,\qquad
 u_j=C^{-1}r^{2^j}.
\end{equation}
Then
\begin{equation}
 S(n_j,b_j)\ge1-u_j,\qquad T(2n_j,b_j)\ge1-u_j.
\end{equation}
For every even $L\ge n_0$, the physical ground state is unique, and
the gap above it satisfies
\begin{equation}
 \gamma_L>\frac{\log(1/r)}{b_0}.
\end{equation}

For the self-adjoint Hamiltonians \eqref{eq:main-H}, the normalized
ground states of the even periodic rings have a subsequence, as
$L\to\infty$, converging on every local operator to a state $\omega$.
Every such limit satisfies
\begin{equation}
 \omega(A^*[H,A])\ge\frac{\log20}{784}
 \bigl(\omega(A^*A)-|\omega(A)|^2\bigr)
\end{equation}
for every local operator $A$.

In the integral endomorphism ring of \(\widetilde A_S\),
\begin{equation}
\Phi^3-D_1\Phi^2+qD_2\Phi-q^3D_3=0.
\end{equation}

abstract:
We prove the reverse logarithmic Kodaira inequality for a surjective connected-fiber morphism \(f:(X,E)	o(Y,D)\) of smooth projective reduced simple-normal-crossing pairs, with \(\mathop{\mathrm{Supp}}
olimits (f^*D)\subseteq\mathop{\mathrm{Supp}}
olimits E\), such that <i>X</i> and every boundary stratum are smooth over \(Y\setminus\mathop{\mathrm{Supp}}
olimits D\). Together with logarithmic subadditivity, the inequality gives additivity, including both negative-infinity cases. This resolves Popa's logarithmic additivity conjecture positively in the projective reduced-SNC, stratum-smooth setting.

statements.text:
Under these hypotheses,
\begin{equation}
 \kappa(X,L_X)\leq\kappa(Y,L_Y)+\kappa(F,L_F).
\end{equation}
If either term on the right is $-\infty$, then
$H^0(X,mL_X)=0$ for every $m>0$.

For the pairs in Theorem~\ref{thm:upper-bound},
\begin{equation}
 \kappa(X,K_X+E)=\kappa(Y,K_Y+D)+\kappa(F,K_F+E_F).
\end{equation}

For every component $D_i$ of $D_0$,
\begin{equation}
                 \nu(\mathcal H|_{D_i})<\nu(\mathcal H).
\end{equation}
If $\nu(\mathcal H)=0$, then $D_0$ is empty.

For every vertex \(v\), there is \(C<\infty\), depending only on \(d\)
at the critical parameter, such that
\begin{equation}

 \begin{aligned}
 A_v(t)&\le1+\frac{d\theta^2}{1-b\theta^2}
      &&\text{if }b\theta^2<1,\quad t\ge0,\\
 \E A_v(t)&\le\frac{C}{\omega(t)}
      &&\text{if }b\theta^2=1,\quad t>0,\\
 \E\int_0^T A_v(t)\dd t&<\infty
      &&\text{for every }T<\infty\text{ in either case}.
 \end{aligned}
\end{equation}
The same fixed-time and integrated upper bounds hold with
\(\sum_u C_{vu}(t)^2\) in place of \(A_v(t)\).

For every finite $T>0$ there are $c,C>0$, depending only on $d$, and
$C_T<\infty$, depending also on $T$, such that for $0<t\le T$ and
every integer $r\ge2\ell_*(t)$,
\begin{equation}
 \begin{aligned}
 Q_r(t)&\le C e^{-c\omega(t)r}\,rS(t)
       +C_T r^2\exp(-c b^{cr}),\\
 L_r(t)&\le C e^{-c\omega(t)r}\,V(t)
       +C_T\exp(-c b^{cr}).
 \end{aligned}

\end{equation}
At every integer $r\ge1$, without a lower length restriction,
\begin{equation}
 Q_r(t)\le2C_{\mathrm{var}}rS(t),\qquad L_r(t)\le V(t),

\end{equation}
where $C_{\mathrm{var}}$ is the constant in
Proposition~\ref{prop:path-variance}.  The hypothesis for
\eqref{eq:weighted-paths} follows in particular from
$r\ge2(C_0+1)/\omega(t)$.

Every exterior in Definition~\ref{def:prepared} satisfies
\begin{equation}
 E_0\ge\frac12\left(\frac{A_0}{\omega}\right)^{(n-2)/(n-1)}.
\end{equation}

For every smooth $f,Z$ and every smooth $g,K$ the following identity
holds, without a field equation or energy hypothesis:
\begin{equation}
 \frac12e^{2t}R_{\widehat g}
 =\mu+J(w)+\mathcal T+w(F)-F\tau-u^{-1}\divg_g V,

\end{equation}
where $2\mu=R_g+\tau^2-|K|^2$, $J=\divg_gP_K$, and
\begin{equation}
 \begin{aligned}
 \mathcal T={}&\frac12|T^0|^2+|M+s_pa_wy|^2
       +\left(ks_p-\frac{(k-1)^2}{4}v\right)|y|^2+ks_pd x^2\\
 &-\frac{k-1}{2k}(F-\chi j)^2+\chi j^2-\chi Fj+F^2
       +2s_p\chi j a_w x .
 \end{aligned}

\end{equation}
The quantity $\mathcal T$ is smooth, including where $df=0$.

For $0\leq p\leq N$ and $0\leq v<1$ the quadratic form in
Equation~\eqref{eq:scalar:quadratic} is nonnegative, and
\begin{equation}
 |T|^2+|M|^2+d j^2+F^2+|dt|_{A_d}^2
                 \leq C_k(1+N)^2\mathcal T.

\end{equation}
At $dt=0$ one has, with constants depending only on $k$,
\begin{equation}
 c_k\bigl(|T^0|^2+|M|^2+F^2+\chi j^2\bigr)
 \leq\mathcal T\leq
 C_k\bigl(|T^0|^2+|M|^2+F^2+\chi j^2\bigr).

\end{equation}

For every pair of smooth functions $f,Z$ on the filled manifold,
\begin{equation}
 \frac12e^{2t}R_{\widehat g}
 =\mu+J(w)+\mathcal T+w(F)-F\tau
       -u^{-1}\operatorname{div}_g V.
\end{equation}
The quadratic expression in Equation~\ref{sy:invariant-T} has the
following exact block expansion:
\begin{equation}
\begin{aligned}
 \mathcal T={}&\tfrac12|T^0|^2+|M+s_pa_wy|^2
       -\tfrac14v|y|^2+2s_p(|y|^2+dx^2)\\
 &-\tfrac14(F-\chi j)^2+\chi j^2-\chi Fj+F^2
       +2s_p\chi ja_wx.
\end{aligned}
\end{equation}
These identities require neither a constraint inequality nor a
field extension to the filling.

For all the variables in Equation~\ref{sy:variables},
\begin{equation}
 |T|^2+|M|^2+dj^2+F^2+|dt|_{A_d}^2
 \le20(1+N)^2\mathcal T.
\end{equation}
At a point where $dt=0$, set
$\mathcal E_0=|T^0|^2+|M|^2+F^2+\chi j^2$.
Then, independently of $N$,
\begin{equation}
 \tfrac12\mathcal E_0\le\mathcal T\le\mathcal E_0.
\end{equation}

The strict prepared rest data satisfy
\begin{equation}
 E_*\ge Q,
 \qquad
 \sqrt{\frac{a_g(S)}{4\pi}}
      \le E_*+\sqrt{E_*^2-Q^2}.
\end{equation}
This conclusion allows a different fixed choice of future or past
boundary sign on each component.

The smooth multipliers on the original boundary satisfy
\begin{equation}
 X=u\nu,\qquad \partial_\nu u+K(X,\nu)=\kappa,
 \qquad \kappa=\frac c2>0.
\end{equation}
Either \(u>0\) everywhere on connected \(S\), or \(u=0\) everywhere
there.  In the first case,
\begin{equation}
 dW=2\kappa X^\flat\quad\text{on }S.
\end{equation}
In the second case, in original outward normal distance \(s\),
\begin{equation}
 u=\kappa s+O(s^2),\qquad X=O(s^2).
\end{equation}
In both cases \(W>0\) on a deleted collar of \(S\).  The coefficient
\(h_*=\mu_m/u^2\) in Equation~\eqref{va:null-stress} is a smooth
nonnegative function supported in a compact subset of
\(\operatorname{int}\Omega\), and extends by zero through \(S\).

For each fixed $S$ there is a finite $\beta_0(S)$ such that, for every
fixed finite $\beta\ge\beta_0(S)$, one has $m=m_{S,\beta}>0$ and
\begin{equation}
 \lim_{\substack{L\to\infty\\L\text{ even}}}
  \left\langle
     \exp\!\left(\frac1V\sum_{a=1}^3t_aM_L^a\right)
  \right\rangle_{\beta,L}
   =\frac1{4\pi}\int_{\mathbb S^2}e^{m t\cdot n}\dd\sigma(n)
   =\frac{\sinh(m|t|)}{m|t|}
 \qquad(t\in\R^3).
\end{equation}
Here $\sigma$ is surface-area measure on $\mathbb S^2$, and the quotient
at $t=0$ is interpreted as $1$. In addition,
\begin{equation}
 \lim_{\substack{L\to\infty\\L\text{ even}}}
   \frac1{V^2}\sum_{x,y\in\Lambda_L}
          \langle S_x\cdot S_y\rangle_{\beta,L}=m^2.
\end{equation}

The mean entropy exists on $\mathcal S_{\rm TI}$, is upper
semicontinuous and affine, and
\begin{equation}
 P_a(t)=\max_{\omega\in\mathcal S_{\rm TI}}
       \{\mathfrak s(\omega)+e_0(\omega)+t\omega(a)\}.
\end{equation}
In particular, writing $P_0=\beta p_{S,\beta}(0)$, the set
\[
 \mathcal E_\beta=
 \{\omega\in\mathcal S_{\rm TI}:
            \mathfrak s(\omega)+e_0(\omega)=P_0\}
\]
is a nonempty compact face of $\mathcal S_{\rm TI}$.  Every local limit
of periodic zero-field Gibbs states belongs to $\mathcal E_\beta$,
and
\begin{equation}
 P_a'(0+)=\max_{\omega\in\mathcal E_\beta}\omega(a).
\end{equation}
The extreme points of $\mathcal E_\beta$ are precisely its states that
are extreme in $\mathcal S_{\rm TI}$; we call these states ergodic.

Every ergodic translation-invariant state $\omega\in\mathcal E_\beta$
satisfies
\begin{equation}
 \omega(X_0)^2+\omega(Y_0)^2+\omega(Z_0)^2=m^2.

\end{equation}

The periodic zero-field Gibbs states satisfy
\begin{equation}
 \liminf_{L\to\infty}\frac1{V^2}
        \sum_{a=1}^3\langle(M_L^a)^2\rangle\ge m^2.
\end{equation}

Fix $\alpha>0$, $M=\lfloor\alpha N\rfloor$, and $f\in C_b(\R)$. Suppose the law of $A_N$ is invariant under left and right orthogonal multiplication and, in probability,
\begin{equation}
\frac1{r_N}\sum_{r=1}^{r_N}\delta_{s_{N,r}}\Longrightarrow\nu,
\qquad
\max_{r\le r_N}\operatorname{dist}(s_{N,r},\supp\nu)\longrightarrow0,
\end{equation}
where $\nu$ is a deterministic compactly supported probability measure on $[0,\infty)$. Then $F_N(A_N,f)$ converges in probability and in mean to a deterministic value $F_{\alpha,\nu}(f)$.

\pagebreak[3]
Here is its formula. Approximate the singular slots in operator norm by finitely many positive values $s_1,\ldots,s_h$ whose multiplicities satisfy $n_j/M\to p_j>0$. Thus $\sum_jp_j=\min(1,1/\alpha)$. Put $v_j=\alpha p_j$, and, if $\alpha<1$, add an input null block with $v_0=1-\alpha$. Let $\mathcal I=\{1,\ldots,h\}$ when $\alpha\ge1$ and $\mathcal I=\{0,1,\ldots,h\}$ otherwise. The variable $\rho_i$ is the fraction of the input squared norm assigned to block $i$. The value for this finite approximation is
\begin{equation}
\sup_{\substack{\rho_i>0\\\sum_{i\in\mathcal I}\rho_i=1}}
\left\{
\frac12\sum_{i\in\mathcal I}v_i\log\frac{\rho_i}{v_i}
+\alpha P_p^f\left(\left(\frac{s_j^2\rho_j}{\alpha}\right)_{j=1}^h\right)
\right\}.
\end{equation}
The limit of \eqref{eq:radialformula} as the spectral mesh tends to zero is $F_{\alpha,\nu}(f)$. Blocks with zero limiting proportion are not used in \eqref{eq:radialformula}; the no-outlier assumption ensures the required approximations with positive limiting proportions.

In Theorem~\ref{thm:main}, or Proposition~\ref{prop:aspect}, let $s_-=\min\supp\nu$ and $s_+=\max\supp\nu$. The no-outlier assumption may be weakened to
\begin{equation}
\max_{r\le\min(M,N)}\operatorname{dist}(s_{N,r},[s_-,s_+])\longrightarrow0
\quad\hbox{in probability}.
\end{equation}
If $\alpha<1$, the interval may instead be $[0,s_+]$, using the macroscopic structural right null space at its lower endpoint. Forced left zeros do not provide such an endpoint.

There is an absolute integer $q_H\ge2$ such that the following holds for
each integer $q\ge q_H$.  Let $H$ have a locally $q$-connected hierarchy,
and let $\mathcal M$ be any collection of its nonroot nodes satisfying
$|O(A)|\ge |P(A)|/q$.  Then $H$ has a shortcut matrix $D$ such that
\begin{equation}
 \frac{1}{|O(A)|}\sum_{e\in O(A)}R_D(e)\le q^{-31/40}
 \qquad(A\in\mathcal M).
\end{equation}
The cutoff is independent of the graph, the hierarchy depth and the
marked collection $\mathcal M$.

Let $\epsilon>0$, and let $v_1,\ldots,v_m$ be independent random vectors
with finite support in $\mathbb C^d$.  If
\begin{equation}
 \sum_{i=1}^m\mathbb E[v_iv_i^*]=I_d,
 \qquad \mathbb E\|v_i\|^2\leq\epsilon\quad(1\leq i\leq m),

\end{equation}
then
\begin{equation}
 \mathbb P\left\{
 \left\|\sum_{i=1}^m v_iv_i^*\right\|
       \leq(1+\sqrt\epsilon)^2\right\}>0.

\end{equation}
Here $*$ denotes conjugate transpose and the norm is the operator norm.
In particular, some outcome satisfies the corresponding
positive-semidefinite upper bound.  Real vectors are a special case.

For every integer $n\ge1$ and every origin-symmetric convex body
$K\subset\R^n$,
\begin{equation}
 |K|\,|K^\circ|\ge\frac{4^n}{n!}.
\end{equation}
Equality holds if and only if $K$ is a linear Hanner body.

For a model \(p\) and every \(s\in S\),
\begin{equation}
 \Ideal_D(p(s))=\Ideal_D(Q(U_s)).
\end{equation}
Given countably many models \(p_i:S\to D\), there is a separable
subalgebra \(D_0\subseteq D\) containing their ranges and the
constants \(Q\), such that, for every \(\gamma\in T(D_0)\),
\begin{equation}
 \gamma\circ p_i=m\otimes F(\gamma|_Q)
 \quad\hbox{for every }i.
\end{equation}
It may also contain any prescribed countable subset of \(D\).

The definition of \(J(U)\) is independent of representatives and
makes it a closed two-sided ideal of \(D\). The assignment is
order preserving, and
\begin{equation}
 J(U)\subseteq\Ideal_D(Q(U)).
\end{equation}
If \(\rho\) is a regularized limit and its restriction
\(\sigma=\rho|_Q\) is densely finite on \(Q(U)\), then
\begin{equation}
 \rho|_{J(U)}=0.
\end{equation}
All assertions use the same conventions in finite matrix algebras.

There is a completely positive contraction $h:S\to D=Q_\infty$ with the
following properties.

For every open $U\subseteq X$, $s\in S(U)$, and $z\in S$,
\begin{equation}
 h(sz)-h(s)h(z),\quad h(zs)-h(z)h(s)\ \in J(U).
\end{equation}
If $s=f\otimes a\in\mathcal E$ is controlled inside $U$, and $\rho$ is a
regularized limit trace whose restriction $\sigma=\rho|_Q$ is densely
finite on $Q(U)$, then
\begin{equation}
 \rho(h(s)^2)=\left(\int_Y f^2\,dm\right)F(\sigma)(a^2).
\end{equation}
Finally, for every $f\otimes a\in\mathcal E$ with $f\ne0$,
\begin{equation}
 Q(U_a)\subseteq\Ideal_D\bigl(h(f\otimes a)\bigr).
\end{equation}
The test family may be enlarged in advance by any countable family of
the controlled elementary tests just described.

The target vector
\begin{equation}
 \bigl((t_i^{(1)},t_i^{(2)},t_i^{(2)})_i;(y_j^2)_j\bigr)
\end{equation}
belongs to the closed convex hull of the candidate vectors.

For the horizontal data of Definition~\ref{tame:data}, and the tame
height defined below, one has
\begin{equation}
 C\Omega_0L(f\otimes\varepsilon,1)\frac{Z'}{d_0}
   =\pm(2-a_*)\,\frac{h_\lambda^K(Q_X,Q_X)}{\delta}.
\end{equation}
This assertion requires the odd functional sign and the nonzero
companion value, but does not assume \(\an(E)=1\) or that \(E(\Q)\)
spans the rational Selmer group. In particular, if \(Q_X\) is torsion,
then \(Z'=0\).

Let \(f\) be a normalized primitive weight-two newform of trivial nebentypus and level \(N_f\), and let \(\mathcal A\) be its modular abelian factor. Let \(K\) have odd fundamental discriminant \(-D<-4\), prime to \(N_f\), and suppose every prime dividing \(N_f\) splits in \(K\). Thus \(\mathcal O_K^\times=\{\pm1\}\), and the split height formula \eqref{eq:GZ} applies. Let \(F_f\) be a finite extension of \(\mathbb Q_2\) containing the image of a fixed Hecke coefficient embedding, and let \(V_f\) be the corresponding two-dimensional Tate representation over \(F_f\), allowing a further finite scalar extension when needed. Assume \(V_f|_{G_K}\) absolutely irreducible. Then
\[
 \begin{gathered}
 L(f/K,s)\ \text{has a simple zero at }1\\
 \Longrightarrow\quad
 H^1_f(K,V_f)=F_f y,\qquad y\ne0,\qquad \tau y=-w(f)y,
                                                                    \tag{K0}
 \end{gathered}
\]
where \(y\) is the Kummer class of the projected Hilbert trace. The Selmer notation on the right means ordinary Kummer finite conditions, with conjugate rational twist components over \(\mathbb Q\) recovered by quadratic isogeny. In particular the summand whose \(L\)-function has nonzero central value has zero such Selmer and the simple-zero summand rank one, since \(w(f)\) is the functional sign over \(\mathbb Q\) and the split product sign is minus. Dual Tate via a polarization gives the same assertions rationally. The conclusion concerns the characteristic-zero Selmer rank at the indicated coefficient. For a general \(\mathcal A\), no assertion of finiteness for its entire prime-primary Tate--Shafarevich group is included.

On the gauge-invariant core,
\begin{equation}

\begin{aligned}
 \cH(h,m)&=\frac12p^2+U_{h,m}
   +\frac{\ii}{2}\theta^t\left(\frac32mT-hK_j\gamma^j\right)\theta,
       \qquad K_j=\ad(x_j),\\
 2U_{h,m}&=\sum_{\mathrm{cyc}}
       \abs{h[x_a,x_b]-2mx_c}^2
       +h^2\sum_{\substack{i<j\\j>3}}\abs{[x_i,x_j]}^2
       +m^2\sum_{d=4}^9\abs{x_d}^2,\\
 D_v(h,m)^2&=\cH(h,m)+mJ(R(v)),
       \qquad R(v)_{ij}=s_jv^t\gamma^i\gamma^jTv.
\end{aligned}
\end{equation}
The cyclic sum uses \((a,b,c)=(1,2,3),(2,3,1),(3,1,2)\).
The matrix \(R(v)\) is skew, preserves \(\R^3\oplus\R^6\), and has
zero spin-basis average. The same formulas hold for an orthogonal
direct sum of compact color algebras and abelian color spaces.

Under the hypotheses of Proposition~\ref{prop:profile-compactness}, after
Proposition~\ref{prop:exterior-estimate} has been proved at size \(N\),
there is also a full-collapse profile \(F_0\in\cK_N\). Its squared norm is
the mass of the limiting norm measure at zero. If the squared norm
measures are tight, then
\begin{equation}
 \lim_j\norm{\psi_j}^2
       =\norm{F_0}^2+\sum_{C\text{ proper}}\norm{F_C}^2.
\end{equation}
For any finite simultaneously extracted list, one likewise has
\begin{equation}
 \lim_j\ip{\psi_j^a}{\psi_j^b}
 =\ip{F_0^a}{F_0^b}+
       \sum_{C\text{ proper}}\ip{F_C^a}{F_C^b}.
\end{equation}
The space \(\cK_N\) is allowed to have unknown dimension in this statement.

Under the supposition above, there is a sequence of finite sets
$P\subset\R^2$ of real algebraic points, with $n=|P|\to\infty$, and
nonempty directed graphs $E$ on $P$, with the following properties.
Their densities $d_n=|E|/[n(n-1)]$ tend to $\theta$, and every fiber has
$k_e\ge n^{s-o(1)}$, uniformly in $e$. For a fixed constant $B_0$,
\begin{equation}
  q\le B_0\pi,\qquad q_X,q_Y\le B_0\alpha,\qquad
  \frac{q_X+q_Y}{2}\ge(1-o(1))\alpha
\end{equation}
pointwise, and
\begin{equation}
  q_Y\{y:d^-(y)<n^\gamma\}=O(n^{\gamma-1})=o(1).
\end{equation}
Finally, put $\lambda_n=1/\log n$. For every subset $C\subset P$, with
$m=|C|$ and $p_e=\mu_e(C)$,
\begin{equation}
 \E_e\,\1_C(x_e)p_e\1_{\{p_e\ge\lambda_n\}}
 \le
 \begin{cases}
   (1+o(1))\pi(C^2),&m>n^{1-c},\\
   o(1)\pi(C^2),&m\le n^{1-c}.
 \end{cases}
\end{equation}
All the errors are uniform in vertices, fibers, and subsets wherever
these occur.

For
\begin{equation}
 J_t=\int_{\Hh}\frac{\mu_t(v)}{|v|^2}\,\dd A(v),
\end{equation}
there is a constant $K<\infty$ such that
\begin{equation}
 \E\int_0^\infty J_t^2\,\dd t
 \le K m^2\area(\Omega)<\infty.
\end{equation}
Consequently $J_t$ is finite for almost every capacity time, almost surely.

For every simplicial set $K$, the canonical map
\begin{equation}
 \theta_K=\eta_{\Sd^2K}:\Sd^2K\longrightarrow\Street L_nK
\end{equation}
is a weak equivalence.

For every nonempty finite set $A\subset F$,
\begin{equation}
  \max_{h\in S}\frac{|hA\mathbin{\triangle}A|}{|A|}
  \geq \frac{\delta^2/L^2-4/D}{4(1-1/D)}>0.
\end{equation}

Let $G(x,u)$ satisfy the analytic and transversality hypotheses of
Lemma~\ref{lem:ambient-tube}. Suppose that the zero family admits a
proper holomorphic map $b:M\to\{G=0\}$ over the parameter disk such that
\begin{enumerate}
\item $q:M\to D$ is a smooth family;
\item $b$ is an isomorphism away from the origin section;
\item $E=b^{-1}(\{x=0\})$ is a relative normal-crossing divisor.
\end{enumerate}
Here the last condition means that, in local coordinates consisting of
fiber coordinates and $u$, the support of $E$ is a union of coordinate
hyperplanes in the fiber coordinates. Then $G$ has the trivialization
of Lemma~\ref{lem:ambient-tube}.

For every positive contraction $h\in D$ and $0<\eta<1$, there is a
projection $p\in D$ such that
\begin{equation}
 p\le\mathbf 1_{[\eta,1]}(h)\quad\text{in }D^{**},
 \qquad
 \tau(p)=\tau((h-\eta)_+)
       \quad(\tau\in\Lambda).

\end{equation}
In addition, for $k_\eta(s)=\min\{s/\eta,1\}$ on $[0,1]$, one has
\begin{equation}
 k_\eta(h)p=p=pk_\eta(h)\quad\text{in }D.

\end{equation}

Fix $R\ge1$.  For every finite set $E\subset A$ of selfadjoint
contractions, every finite set $H\subset A$ of contractions, and every
$\sigma>0$, there is a selfadjoint $d\in A$ with $\norm{d}\le R$ such
that, simultaneously,
\begin{equation}
 \begin{aligned}
  \norm{[d,a]}_{2,T}&<\sigma &&(a\in E),\\
  \sup_{\tau\in T}|\tau(bd)|&\le3/R^3+\sigma &&(b\in H),\\
  \sup_{\tau\in T}|\tau(b(d^2-1))|&\le3/R^2+\sigma &&(b\in H),\\
  \sup_{\tau\in T}\tau(d^4)&\le3+\sigma.
 \end{aligned}

\end{equation}

For every integer $N\geq1$ there exist mutually commuting selfadjoint
elements $d_{N,1},\ldots,d_{N,N}\in D\cap A'$, each of norm at most
$N$, with the following properties.  Put
\[
  C_{N,j}=C^*(A,d_{N,1},\ldots,d_{N,j-1}),
  \qquad
  s_N=\frac{1}{\sqrt N}\sum_{j=1}^N d_{N,j}.
\]
For every contraction $b\in C_{N,j}$ and $\tau\in\Lambda$,
\begin{equation}

  |\tau(bd_{N,j})|\leq\frac{3}{N^3},\qquad
  |\tau(b(d_{N,j}^2-1))|\leq\frac{3}{N^2},\qquad
  \tau(d_{N,j}^4)\leq3.
\end{equation}
For every fixed $t\in\R$,
\begin{equation}

  \lim_{N\to\infty}
  \sup_{\substack{\tau\in\Lambda\\a\in A,\ \norm{a}\leq1}}
  \left|\tau(ae^{its_N})-e^{-t^2/2}\tau(a)\right|=0.
\end{equation}

If $E\subset D$ is finite dimensional and unital, $Y\in D_+$,
$0<t<1$, and $\varepsilon>0$, there is a projection $p\in D\cap E'$ with
\begin{equation}
 \tau(pd)=t\tau(d)\quad(d\in E),\qquad
 \tau(pY)\le t\bigl(\tau(Y)+\varepsilon\bigr)\quad(\tau\in \Lambda).
\end{equation}

Let $0<\lambda<1$, let $\mathcal F$ be a finite set of self-adjoint
